window.__ARXIV_DATA__ = {"papers":[{"id":"2608.11205v1","title":"AdvFD: Boosting Visual Generation via Adversarial Fr'echet Distance Loss","abstract":"Fréchet distance has recently emerged as an effective distribution-level objective for generator post-training, complementing the conventional sample-level diffusion and flow-matching losses. However, directly optimizing Fréchet objectives can cause Fréchet hacking. The target metrics keep improving, but visual quality and Fréchet alignment in other feature spaces may stagnate or deteriorate. We attribute this failure to the static pretrained feature spaces used by existing Fréchet losses. These feature spaces provide incomplete and fixed views of the differences between real and generated distributions. To address this limitation, we propose Adversarial Fréchet Distance (AdvFD), which complements the static representation targets in FD-Loss with a calibrated adversarially learned representation. AdvFD augments the original static Fréchet objective with a learnable representation that adversarially maximizes the Fréchet discrepancy between real and generated samples, while the generator minimizes the same discrepancy in the resulting adaptive feature space. To prevent the adversarial representation from trivially increasing the objective through feature amplification, we further introduce real-feature whitening, which normalizes its scale and covariance geometry and stabilizes the min--max optimization. Extensive experiments show that AdvFD consistently improves one-step generator post-training across both JiT and pMF backbones and across different model scales.","authors":["Mingju Gao","Jingkai Zhou","Kun Gai","Changqian Yu","Hao Tang"],"published":"2026-08-11T17:59:56Z","updated":"2026-08-11T17:59:56Z","abstract_url":"https://arxiv.org/abs/2608.11205v1","html_url":"https://arxiv.org/html/2608.11205v1","pdf_url":"https://arxiv.org/pdf/2608.11205v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"html","source_text_chars":83290,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation, diffusion 相关；摘要显示其主要贡献为：Fréchet distance has recently emerged as an effective distribution-level objective for generator post-training, complementing the conventional sample-level diffusion and flow-matching losses. However, directly optimizing Fréchet objectives can cause Fréchet h...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:06+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11204v1","title":"Surgical WAM: A World-Action Model for Data-Efficient Surgical Robot Learning","abstract":"Learning reliable surgical manipulation policies is bottlenecked by the scarcity of action-labeled demonstrations: teleoperated surgical robot (e.g., dVRK) trajectories with synchronized kinematics are costly to collect, while surgical tasks demand precise contact handling, long-horizon reasoning, and bimanual coordination. Endoscopic video is comparatively inexpensive and abundant relative to synchronized video--kinematics trajectories, and a natural way to exploit it is to learn world models of surgical scenes. However, existing surgical world models use video primarily for simulation or policy evaluation, and rarely translate the learned dynamics into closed-loop control. This gap raises our central question: under a fixed budget of action-labeled demonstrations, does action-free video pretraining improve closed-loop surgical manipulation? To answer it, we introduce the Surgical World-Action Model (Surgical WAM), a unified generative model built on Cosmos Policy that jointly predicts future endoscopic observations and executable surgical robot action chunks. Surgical WAM first learns surgical visual dynamics from action-free video and is then fine-tuned on the fixed action-labeled budget; at deployment, it acts as a closed-loop, receding-horizon controller that executes a short prefix of each predicted action chunk and replans from the resulting observation. On a suite of four simulated surgical manipulation tasks, video pretraining improves the average success rate from 63.5% to 77.8%, including an absolute gain of 20 percentage points on PegTransfer, with the largest improvements on contact-rich and bimanual tasks. These results demonstrate that action-free video provides transferable visual dynamics priors for learning surgical robot control with limited action supervision, positioning data-efficient video pretraining as a practical path toward scaling up surgical robot learning.","authors":["Wenrui Bao","Tianyun Jiang","Zhiben Chen","Ser-Nam Lim","Peter D. Peng","Yuzhang Shang"],"published":"2026-08-11T17:59:13Z","updated":"2026-08-11T17:59:13Z","abstract_url":"https://arxiv.org/abs/2608.11204v1","html_url":"https://arxiv.org/html/2608.11204v1","pdf_url":"https://arxiv.org/pdf/2608.11204v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":50575,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Learning reliable surgical manipulation policies is bottlenecked by the scarcity of action-labeled demonstrations: teleoperated surgical robot (e.g., dVRK) trajectories with synchronized kinematics are costly to collect, while surgical tasks demand precise co...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:06+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11203v1","title":"Capturing Uncertainty in Human Motion for Representation Learning in Soccer","abstract":"This paper presents a self-supervised representation learning framework for understanding 3D skeleton-based human motion in soccer, using future motion prediction as the learning objective. Since human motion is inherently uncertain, accounting for multiple plausible futures is essential for capturing the underlying motion dynamics and learning effective representations. To this end, we introduce a conditioning module for motion prediction that models a probabilistic distribution over discretized future motions in 3D Euclidean space, learning multimodality with explicit supervision from future trajectories. Experiments on large-scale soccer player tracking data show that our approach substantially improves motion prediction accuracy. Moreover, the learned representations effectively transfer to multiple soccer downstream applications, demonstrating strong cross-task generalization.","authors":["Yizhou Xu","Lars Bretzner","Tiesheng Wang","Atsuto Maki"],"published":"2026-08-11T17:59:10Z","updated":"2026-08-11T17:59:10Z","abstract_url":"https://arxiv.org/abs/2608.11203v1","html_url":"https://arxiv.org/html/2608.11203v1","pdf_url":"https://arxiv.org/pdf/2608.11203v1.pdf","matched_keywords":["3d","representation","multimodal"],"source_used":"html","source_text_chars":114098,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, representation, multimodal 相关；摘要显示其主要贡献为：This paper presents a self-supervised representation learning framework for understanding 3D skeleton-based human motion in soccer, using future motion prediction as the learning objective. Since human motion is inherently uncertain, accounting for multiple p...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:06+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11201v1","title":"VidForensics-M1: Meta-Detection Reinforcement Learning with Verifiable Temporal Grounding for AI-Generated Video Forensics","abstract":"Recent advances in video generation models have significantly improved the realism of synthetic videos, blurring the boundary between generated and authentic content and raising concerns about misinformation. Existing MLLM-based detectors mainly rely on supervised fine-tuning or label-level reinforcement learning, where coarse supervision limits generalization to unseen scenarios and emerging video generators. To overcome these limitations, we are the first to introduce \\textbf{meta-detection} into AI-generated video detection, enabling reliable forgery detection by jointly optimizing predicted labels and supporting evidence within reinforcement learning. This paradigm requires reliable evidence signals and effective mechanisms to integrate them into label-level optimization. Textual rationales provide semantic descriptions of forgery artifacts, but their generation and verification depend on external models, making supervision vulnerable to hallucinations and semantic biases. In contrast, temporal grounding provides more objective and verifiable evidence, as manipulated intervals can be precisely controlled during forgery construction. Based on this insight, we propose an automated data construction pipeline that generates paired real-fake videos by replacing temporal segments with boundary-frame-conditioned video generation models. Furthermore, we introduce \\textbf{Evidence-Guided Reward Redistribution}, which performs evidence-aware credit assignment by redistributing rewards among label-correct responses according to evidence quality. This preserves reliable label supervision while encouraging detectors to acquire fine-grained and verifiable forgery localization capabilities. Extensive experiments demonstrate that \\textbf{VidForensics-M1} effectively leverages verifiable temporal evidence to achieve robust and generalizable AI-generated video detection.","authors":["Bowei Liu","Zheng Lu","Yuhan Bian","Xinchen Zhang","Xingming Shui","Yuesheng Huang","Xuhuan Li","Zihao Liu","Yifan Yang","Jun Zhou","Xiu Li"],"published":"2026-08-11T17:58:10Z","updated":"2026-08-11T17:58:10Z","abstract_url":"https://arxiv.org/abs/2608.11201v1","html_url":"https://arxiv.org/html/2608.11201v1","pdf_url":"https://arxiv.org/pdf/2608.11201v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":77817,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Recent advances in video generation models have significantly improved the realism of synthetic videos, blurring the boundary between generated and authentic content and raising concerns about misinformation. Existing MLLM-based detectors mainly rely on super...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:07+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11191v1","title":"Test-Time Self-Evolving GUI Visual Grounding via Reflection-Guided On-Policy Self-Distillation","abstract":"GUI Visual Grounding is a fundamental capability for GUI agents. Existing models typically freeze their parameters after deployment, limiting their ability to adapt to unseen interfaces. Although recent methods attempt to adapt models via test-time reinforcement learning, they cannot reflect upon failed exploration. To overcome this, we propose a Test-Time Self-Evolving framework that enables models to improve after deployment without human-annotated ground truth. It constructs a closed-loop of Exploration, Evaluation, Reflection, and Internalization. Specifically, the agent first explores unseen interfaces by predicting grounding coordinates for given instructions. To evaluate these explorations, we introduce an MLLM-based Reflector to assess the generated results and provide the corresponding reasoning reflections. To internalize reflection knowledge into the model weights, we propose Reflection-Guided On-Policy Self-Distillation, which translates high-level reasoning into dense token-level supervision via a conditioned self-teacher. Furthermore, we design a Contrastive Calibration method to prevent incorrect auto-regressive prefixes from corrupting the supervisory signals during failed explorations. Extensive experiments across six benchmarks demonstrate our framework's effectiveness, achieving an average accuracy improvement of 7.4% over the base model. To the best of our knowledge, this is the first work to successfully exploit on-policy self-distillation for test-time adaptation in GUI visual grounding. By filling the gap in post-deployment adaptation, our framework completes the self-evolving capability of GUI agents. The code will be released.","authors":["Shiyu Xuan","Zechao Li"],"published":"2026-08-11T17:50:25Z","updated":"2026-08-11T17:50:25Z","abstract_url":"https://arxiv.org/abs/2608.11191v1","html_url":"https://arxiv.org/html/2608.11191v1","pdf_url":"https://arxiv.org/pdf/2608.11191v1.pdf","matched_keywords":["agent"],"source_used":"html","source_text_chars":56602,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent 相关；摘要显示其主要贡献为：GUI Visual Grounding is a fundamental capability for GUI agents. Existing models typically freeze their parameters after deployment, limiting their ability to adapt to unseen interfaces. Although recent methods attempt to adapt models via test-time reinforcem...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:07+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11167v1","title":"MultiModal Code-Switching: Interleaving Visual Objects into Language for Explicit Object-Level Alignment","abstract":"Existing Multimodal Large Language Models (MLLMs) predominantly rely on image-text pairs for modality alignment pretraining, mapping global image representations to long textual descriptions. However, this image-level alignment suffers from referential ambiguity: models struggle to infer the correspondences between multiple visual objects and textual entities from the global representation, leading to data inefficiency and suboptimal semantic grounding. To address this, we propose MultiModal Code-Switching (MMCS), a novel pretraining paradigm that provides explicit object-level supervision. Inspired by the linguistic phenomenon of code-switching, MMCS interleaves vision and language by replacing textual entities with their corresponding visual objects, enforcing local vision-language grounding. We further develop a scalable data synthesis pipeline to generate a pretraining dataset of 773K samples with accurate object-entity correspondences. Experiments show that MMCS is highly data-efficient: with only 50K samples, it matches or surpasses models trained on 600K image-text pairs. Furthermore, MMCS consistently improves visual grounding and perception capabilities across varying model scales.","authors":["Changhao Xiang","Shangyu Xing","Zhen Wu","Jianbing Zhang","Xinyu Dai"],"published":"2026-08-11T17:28:52Z","updated":"2026-08-11T17:28:52Z","abstract_url":"https://arxiv.org/abs/2608.11167v1","html_url":"https://arxiv.org/html/2608.11167v1","pdf_url":"https://arxiv.org/pdf/2608.11167v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"html","source_text_chars":89399,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation, multimodal 相关；摘要显示其主要贡献为：Existing Multimodal Large Language Models (MLLMs) predominantly rely on image-text pairs for modality alignment pretraining, mapping global image representations to long textual descriptions. However, this image-level alignment suffers from referential ambigu...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:07+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11150v1","title":"CausalSplat: Towards Comprehensive Hierarchical Reasoning in 3D Gaussian Splatting","abstract":"While 3D Gaussian Splatting (3DGS) has advanced open vocabulary scene understanding, existing methods remain confined to explicit queries. They struggle to interpret implicit intents, complex spatial constraints, and commonsense reasoning required for practical embodied interactions. To address this gap, we introduce the task of reasoning 3D Gaussian segmentation and construct two benchmarks, Causal-LERF and Causal-ScanNet. These benchmarks systematically evaluate commonsense, spatial, affordance, and counterfactual reasoning. Evaluations reveal that current state of the art methods perform poorly on these reasoning challenges. Therefore, we propose CausalSplat, a framework that integrates vision-language models with 3D scene graphs to disentangle explicit structural perception from implicit logical inference. Extensive experiments demonstrate that CausalSplat achieves state of the art performance on our reasoning benchmarks while showing strong generalizability on standard referring and open vocabulary 3D segmentation tasks. Project Page: https://jiayuding031020.github.io/CausalSplat","authors":["Jiayu Ding","Meilu Song","Yun Chen","Wei Gao","Ge Li"],"published":"2026-08-11T17:09:49Z","updated":"2026-08-11T17:09:49Z","abstract_url":"https://arxiv.org/abs/2608.11150v1","html_url":"https://arxiv.org/html/2608.11150v1","pdf_url":"https://arxiv.org/pdf/2608.11150v1.pdf","matched_keywords":["3d"],"source_used":"html","source_text_chars":63995,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d 相关；摘要显示其主要贡献为：While 3D Gaussian Splatting (3DGS) has advanced open vocabulary scene understanding, existing methods remain confined to explicit queries. They struggle to interpret implicit intents, complex spatial constraints, and commonsense reasoning required for practic...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:07+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11149v1","title":"PRMU: A Corpus-Free Benchmark for Person-Centric Knowledge Unlearning in Multimodal Large Language Models","abstract":"Multimodal large language models (MLLMs) have demonstrated remarkable capabilities in storing and recalling rich person-related knowledge, raising increasing concerns about reliable knowledge removal. However, existing machine unlearning approaches for MLLMs typically assume access to original forget and retain corpora, which are often unavailable in realistic deletion scenarios. To address this limitation, we introduce PRMU, a benchmark for evaluating corpus-free multimodal unlearning under realistic person-centric deletion requests. PRMU focuses on naturally acquired person-related knowledge and evaluates whether models can remove target knowledge while preserving related knowledge through diverse textual and visual probes, including adversarial evaluation and fine-grained locality analysis. To facilitate research in this setting, we further introduce Similarity-Gated Projection Editing (SGPE), a lightweight corpus-free unlearning baseline with knowledge displacement, protected parameter-space editing, and locality-aware multimodal control. Extensive experiments on representative MLLMs reveal that existing unlearning methods often suffer from unfavorable forgetting-locality trade-offs, with significant locality degradation under aggressive forgetting settings, and remain vulnerable to multimodal knowledge reactivation. Meanwhile, SGPE provides a competitive trade-off between target forgetting, locality preservation, and general multimodal utility. We hope PRMU can facilitate future research toward realistic and scalable multimodal machine unlearning. Code and dataset will be released at https://github.com/2231122/PRMU.","authors":["Huafeng Chen","Yueming Lyu","Ziyuan Chen","Wenda Tan","Chenyang Si","Liucheng Guo","Caifeng Shan"],"published":"2026-08-11T17:09:28Z","updated":"2026-08-11T17:09:28Z","abstract_url":"https://arxiv.org/abs/2608.11149v1","html_url":"https://arxiv.org/html/2608.11149v1","pdf_url":"https://arxiv.org/pdf/2608.11149v1.pdf","matched_keywords":["multimodal"],"source_used":"html","source_text_chars":50830,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 multimodal 相关；摘要显示其主要贡献为：Multimodal large language models (MLLMs) have demonstrated remarkable capabilities in storing and recalling rich person-related knowledge, raising increasing concerns about reliable knowledge removal. However, existing machine unlearning approaches for MLLMs...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:07+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11142v1","title":"SAR2Agri: Learning SAR Intensity Representations for Agricultural Monitoring","abstract":"Agricultural monitoring faces unique challenges, arising from the landscape's complex temporal, phenological, and climate dynamics, yet monitoring them is critical for ensuring food security. Synthetic Aperture Radar (SAR) satellites offer all-weather day-night imaging capability supporting key monitoring tasks including crop type mapping, yield prediction and phenological event detection. Existing multimodal remote sensing foundation models including TerraMind and CopernicusFM learn SAR representations by grounding them in optical imagery using joint encoding and contrastive learning techniques, while SAR-specific foundation models such as SAR-JEPA, SARMAE, and SAR-W-MixMAE primarily focus on target detection, flood mapping, and land cover classification applications. Recent work has introduced phenology inspired temporal pretext tasks with optical imagery which has shown strong performance on agricultural downstream tasks. In this work, we propose the first self-supervised learning pipeline focused on using only SAR intensity imagery for agricultural applications. We improve the temporal pretext tasks through masking and curriculum learning to enhance the pretraining pipeline's ability to capture phenological features from SAR. On the SICKLE benchmark, our final model achieves 84.9% IoU on crop type mapping, outperforming optical baselines (by 15.3 pt) and existing SAR baselines (by 2.2 pt), demonstrating the effectiveness of our proposed pipeline for pretraining SAR intensity encoders for agricultural monitoring.","authors":["Moti Rattan Gupta","Anupam Sobti"],"published":"2026-08-11T17:01:26Z","updated":"2026-08-11T17:01:26Z","abstract_url":"https://arxiv.org/abs/2608.11142v1","html_url":"https://arxiv.org/html/2608.11142v1","pdf_url":"https://arxiv.org/pdf/2608.11142v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"html","source_text_chars":61351,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation, multimodal 相关；摘要显示其主要贡献为：Agricultural monitoring faces unique challenges, arising from the landscape's complex temporal, phenological, and climate dynamics, yet monitoring them is critical for ensuring food security. Synthetic Aperture Radar (SAR) satellites offer all-weather day-nig...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:07+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11123v1","title":"AlbumentationsX: One Augmentation Pipeline for Images and Related Annotations","abstract":"Augmentation can corrupt a training example when an image and its annotations receive different random changes. A crop must use the same coordinates for the image, mask, boxes, keypoints, stereo views, video frames, or volume. Code paths that choose these values separately can silently misalign the data. AlbumentationsX keeps the transform list, probabilities, annotation settings, and random seed in one Compose object. Each call chooses random values once and applies them to every supported part of the training example. The library keeps each object's mask, box, and label together and lets projects add their own transforms. It can also save the pipeline definition, show what happened in one call, and run that call again. The examples place Compose after files have been decoded into arrays and before PyTorch groups examples into a batch. AlbumentationsX executes the declared transforms. Practitioners still decide whether a flip, crop, color change, or other operation preserves the correct label for their task.","authors":["Vladimir Iglovikov"],"published":"2026-08-11T16:34:47Z","updated":"2026-08-11T16:34:47Z","abstract_url":"https://arxiv.org/abs/2608.11123v1","html_url":"https://arxiv.org/html/2608.11123v1","pdf_url":"https://arxiv.org/pdf/2608.11123v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":23720,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Augmentation can corrupt a training example when an image and its annotations receive different random changes. A crop must use the same coordinates for the image, mask, boxes, keypoints, stereo views, video frames, or volume. Code paths that choose these val...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:08+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11077v1","title":"Learning Gaussian Structure: Intervention-Guided Density Control for Feed-Forward Driving Reconstruction","abstract":"Feed-forward Gaussian reconstruction has recently emerged as an efficient approach for driving scene reconstruction. However, prevailing LiDAR-based methods preserve the initial correspondence between observed points and Gaussian primitives, treating the initialized primitive set as the final representation. Unlike optimization-based 3DGS, these methods cannot accumulate gradients during training to determine how the scenes representation should be densified. Meanwhile, the shared sparse backbone only fuses observations from different timestamps implicitly, without explicitly aggregating cross-time evidence for individual primitives. In this paper, we present Learning Gaussian Structure (LGS), a framework that enhances both Gaussian structure and primitive attributes. Our key observation is that changes in local gradient responses induced by a prune or add intervention reveal whether the corresponding structural adjustment benefits reconstruction. Based on this observation, our Gaussian Densify Policy learns a Densify Map comprising Prune and Addition Scores from controlled interventions, and directly adjusts the Gaussian structure during inference. We further develop a compact Cross-Time Point Query that explicitly retrieves and aggregates neighboring features from Gaussian primitives at other timestamps for reliable attribute prediction. Extensive experiments on the Waymo Open Dataset and PandaSet demonstrate that LGS consistently outperforms existing methods.","authors":["Hang Li","Jiahe Li","Meiying Gu","Jin Zheng","Lina Yu","Xiao Bai"],"published":"2026-08-11T15:38:55Z","updated":"2026-08-11T15:38:55Z","abstract_url":"https://arxiv.org/abs/2608.11077v1","html_url":"https://arxiv.org/html/2608.11077v1","pdf_url":"https://arxiv.org/pdf/2608.11077v1.pdf","matched_keywords":["3d","representation"],"source_used":"html","source_text_chars":45411,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, representation 相关；摘要显示其主要贡献为：Feed-forward Gaussian reconstruction has recently emerged as an efficient approach for driving scene reconstruction. However, prevailing LiDAR-based methods preserve the initial correspondence between observed points and Gaussian primitives, treating the init...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:08+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11051v1","title":"HUI360: A 360° Egocentric Dataset and Baselines for Human-Robot Interaction Anticipation","abstract":"As robots increasingly operate in human-populated environments, anticipating human intentions is essential for enabling proactive and socially aware behavior. Automatic anticipation of human-robot interactions is thus emerging as a crucial perception challenge for embodied agents. To this end, we introduce HUI360, the largest dataset for human-robot interaction anticipation in the wild and its set of baselines. The dataset was collected from a mobile robot, in the wild, over multiple days within a 3-month period, and in several environments, capturing natural, spontaneous behaviors from both passersby and users, and encompassing a diverse range of individuals. This variety enables evaluating and improving the generalization capabilities of interaction anticipation models. We designed a pipeline and share code for automatic interaction annotation in arbitrary 360-degree equirectangular videos, along with interfaces for manual refinement. Using this pipeline, we release the HUI360 open set of 1M pre-processed annotations, including detailed 2D poses, facial keypoints, and segmentation masks, obtained using state-of-the-art computer vision methods and manually curated to ensure high-quality tracking and interaction annotation. Additionally, we release the raw panoptic 360-degree images captured from the robot's egocentric viewpoint (on demand, for research purpose only in compliance with GDPR). Finally, we establish benchmark baselines for interaction anticipation, including the first cross-dataset evaluations for this task: to this end, we also release 6M annotations for another existing in-the-wild outdoor dataset collected from a mobile robot (SSUP-HRI). Dataset and code can be found at https://hucebot.github.io/hui360.","authors":["Raphael Lorenzo-Louis","Fabio Amadio","Bertrand Luvison","Serena Ivaldi"],"published":"2026-08-11T15:22:14Z","updated":"2026-08-11T15:22:14Z","abstract_url":"https://arxiv.org/abs/2608.11051v1","html_url":"https://arxiv.org/html/2608.11051v1","pdf_url":"https://arxiv.org/pdf/2608.11051v1.pdf","matched_keywords":["video","agent"],"source_used":"html","source_text_chars":74301,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, agent 相关；摘要显示其主要贡献为：As robots increasingly operate in human-populated environments, anticipating human intentions is essential for enabling proactive and socially aware behavior. Automatic anticipation of human-robot interactions is thus emerging as a crucial perception challeng...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:08+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11050v1","title":"3D Weighted Geometric Graph Neural Networks for Sheep Facial Pain Assessment","abstract":"Deep learning systems perform mainly within the 2D for a single image domain and take the face as a single-dimension representation, losing sight of the 3D anatomy of sheep and cross-landmark spatial relationships that are intrinsic to the clinically proven Sheep Pain Facial Expression Scale (SPFES). This paper presents the \\textbf{3D Sheep Pain Facial Expression System (3D-SPFES)}, a novel, monocular depth-aware geometric graph neural network system that integrates each SPFES facial landmark, such as the ears, eyes, and nose, into 3D Euclidean space estimated from a single RGB camera by using VideoDepthAnything, thus preventing the need for specialized depth hardware. Each landmark node includes a feature vector containing its 3D spatial coordinates, estimated surface normal, and facial attribute class embedding. Edges linked to nodes are assigned weights based on an aggregate metric that combines both Euclidean distance and surface co-planarity in a 3D space. A Weighted Geometric Graph Neural Network (WG-GNN) studies this graph using $\\mathcal{K} = 3$ geometry-aware message-passing layers enhanced by a scaled dot-product attention method that selectively enhances anatomically relevant inter-landmark messages. The resultant node embeddings are combined into $\\mathcal{O} = 3$ pain-level clusters and integrated into a Normalized Pain Score (NPS) within the range of $[0, 100%]$ a confidence-weighted, SPFES-derived scoring method.","authors":["Alam Noor","Luis Almeida","Mohamed Daoudi"],"published":"2026-08-11T15:21:36Z","updated":"2026-08-11T15:21:36Z","abstract_url":"https://arxiv.org/abs/2608.11050v1","html_url":"https://arxiv.org/html/2608.11050v1","pdf_url":"https://arxiv.org/pdf/2608.11050v1.pdf","matched_keywords":["video","3d","representation"],"source_used":"html","source_text_chars":65562,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d, representation 相关；摘要显示其主要贡献为：Deep learning systems perform mainly within the 2D for a single image domain and take the face as a single-dimension representation, losing sight of the 3D anatomy of sheep and cross-landmark spatial relationships that are intrinsic to the clinically proven S...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:08+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11037v1","title":"Multi-Level Evidence Aggregation for Robust Facial Phenotype Retrieval in Rare Genetic Disorder Prioritization","abstract":"AI-assisted facial phenotyping supports rare genetic disorder prioritization by retrieving visually similar diagnosed cases from facial image reference databases such as the GestaltMatcher Database (GMDB). Existing GestaltMatcher-based retrieval frameworks compare each test image with individual gallery images in a facial phenotype embedding space. However, this pointwise formulation does not fully exploit available evidence, because patients may have multiple images and disorders may be represented by multiple diagnosed gallery patients. We propose an inference-time multi-level evidence aggregation framework that improves facial phenotype retrieval without modifying the underlying GestaltMatcher-Arc encoder. The framework combines embedding-level patient aggregation of multiple images from the same individual, patient-weighted disorder centroids, and hybrid individual-centroid scoring to integrate test-patient observations, disorder-level gallery evidence, and local nearest-neighbor evidence. We evaluated the approach on GMDB v1.1.4 across disorders represented during training (GMDB-Freq), unseen disorders (GMDB-Rare), and multi-image patient subsets, using a unified gallery containing both GMDB-Freq and GMDB-Rare disorders. Multi-level evidence aggregation improved mean per-disorder top-$N$ retrieval accuracy across all evaluation subsets. Top-1 accuracy increased from 38.52% to 48.82% on GMDB-Freq and from 19.38% to 23.79% on GMDB-Rare. On multi-image subsets, top-1 accuracy increased from 46.12% to 60.94% on GMDB-Multi-Freq and from 18.54% to 26.71% on GMDB-Multi-Rare. These findings show that inference-time aggregation can improve next-generation facial phenotype retrieval without retraining the encoder, supporting a shift from isolated single-image matching toward multi-level aggregation of patient and disorder evidence for rare-disorder prioritization.","authors":["Alexander Hustinx","Carolin Kaffiné","Behnam Javanmardi","Tzung-Chien Hsieh","Peter Krawitz"],"published":"2026-08-11T15:12:44Z","updated":"2026-08-11T15:12:44Z","abstract_url":"https://arxiv.org/abs/2608.11037v1","html_url":"https://arxiv.org/html/2608.11037v1","pdf_url":"https://arxiv.org/pdf/2608.11037v1.pdf","matched_keywords":["retrieval"],"source_used":"html","source_text_chars":121520,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 retrieval 相关；摘要显示其主要贡献为：AI-assisted facial phenotyping supports rare genetic disorder prioritization by retrieving visually similar diagnosed cases from facial image reference databases such as the GestaltMatcher Database (GMDB). Existing GestaltMatcher-based retrieval frameworks co...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:08+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11017v1","title":"R4DSG: Relative 4D Scene Graph Memory for Object-Centric Question Answering in Long Egocentric Video","abstract":"Long-horizon egocentric video is a rich substrate for wearable AI assistants, but object-centric questions such as where an item was moved, when it last changed state, or why it was relocated remain difficult because caption- and transcript-based memories rarely preserve persistent object identity or structured spatial change. Existing long-video QA methods mainly emphasize temporal grounding and clip retrieval, while prior 3D scene-graph methods typically assume stronger geometry than free-motion wearable RGB video provides, including point clouds, RGB-D input, posed views, sparse reconstruction, or reconstructed scenes. R4DSG introduces a relative 4D scene graph memory for long egocentric video. Instead of storing raw graph sequences, R4DSG converts video into compact queryable memory entries indexed by time, place, persistent objects, anchor-relative change, and local interaction context. The main idea is to separate stable anchors from dynamic objects, maintain persistent object identity across frames, and represent object state through anchor-relative transitions rather than a globally aligned world model. Built on recent RGB-only advances in promptable video segmentation, temporal propagation, and relative 3D lifting, the method produces a retrieval-ready memory directly usable for long-horizon question answering. Evaluation on a 255-question object-related subset from EgoLifeQA shows, under question-only retrieval, a 6.7-point overall gain over EgoRAG-Text and a 12.5-point gain on when questions, which highlights the value of temporally organized object memory. These results position relative 4D scene graphs as a practical memory substrate for wearable assistants, AR systems, and embodied multimedia agents. GitHub Page: https://dualtransparency.github.io/R4DSG/.","authors":["Ke Ma","Yamin Mao","Weiming Li","Shuai Tan","Yijie Zhong","Hao Chen","Haofen Wang","Meng Wang"],"published":"2026-08-11T15:00:15Z","updated":"2026-08-11T15:00:15Z","abstract_url":"https://arxiv.org/abs/2608.11017v1","html_url":"https://arxiv.org/html/2608.11017v1","pdf_url":"https://arxiv.org/pdf/2608.11017v1.pdf","matched_keywords":["video","retrieval","3d","agent"],"source_used":"html","source_text_chars":53367,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, retrieval, 3d, agent 相关；摘要显示其主要贡献为：Long-horizon egocentric video is a rich substrate for wearable AI assistants, but object-centric questions such as where an item was moved, when it last changed state, or why it was relocated remain difficult because caption- and transcript-based memories rar...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:08+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11013v1","title":"Watching Synthetic Videos: Aligning Cross-modal Representations with Visual Synthesis for Zero-shot Video Captioning","abstract":"Text-only training is a popular paradigm in zero-shot video captioning, where the video distribution is not available to the model during training, leading to a cross-modal gap between the training (text-only) and the inference (video-only). Previous works attempt to bridge the gap through simple linear transformations. However, the inherent gap between text and video makes cross-modal representation space alignment insufficient, resulting in inaccurate sentences. To address this issue, we propose a novel zero-shot video captioning framework (WSV) consisting of two training stages, which first generates corresponding synthetic video latent representations via a pretrained text-to-video generation model. To strengthen the fidelity of the latent representations, we propose a polisher capable of bridging the gap between real and synthetic video distributions. Subsequently, we design a prompter that conditions GPT-2 on the polished latent representations to generate the captions in the second training stage. During inference, an input video is encoded by a pretrained 3D Causal VAE and then fed directly into the prompter, which in turn guides GPT-2 to produce the final caption. Experimental results conducted on MSVD, MSR-VTT, and VATEX datasets demonstrate that our proposed method achieves scores of 52 and 95.7 on the B@4 and CIDEr metrics, respectively.","authors":["Liangyu Fu","Junbo Wang","Yuke Li","Ya Jing","Xuecheng Wu","Zhiyong Wang"],"published":"2026-08-11T14:57:44Z","updated":"2026-08-11T14:57:44Z","abstract_url":"https://arxiv.org/abs/2608.11013v1","html_url":"https://arxiv.org/html/2608.11013v1","pdf_url":"https://arxiv.org/pdf/2608.11013v1.pdf","matched_keywords":["video","3d","representation"],"source_used":"html","source_text_chars":48639,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d, representation 相关；摘要显示其主要贡献为：Text-only training is a popular paradigm in zero-shot video captioning, where the video distribution is not available to the model during training, leading to a cross-modal gap between the training (text-only) and the inference (video-only). Previous works at...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:09+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10995v1","title":"HNDiff: Haze-Noise Diffusion for Image Dehazing","abstract":"Existing diffusion-based methods have recently made significant progress in image dehazing. However, they typically neglect the physics of haze formation and reconstruct clean images from pure Gaussian noise, thereby limiting their restoration potential. To address this issue, we propose Haze-Noise Diffusion (HNDiff), a novel diffusion framework that embeds the atmospheric scattering model as an inductive bias. By grounding diffusion in physical principles, HNDiff ensures that the restoration aligns more closely with underlying mechanisms of haze formation. In its forward process, we introduce joint haze-noise diffusion with a haze-aware noise scheduler, which progressively adds both haze and noise to an image. Essentially, the scheduler adapts noise levels according to haze density, meaning that regions with heavier haze receive stronger noise injection to encourage content generation, while clearer regions receive lighter noise to better preserve details, which directly links the forward degradation process with the physics of haze. In the reverse process, we then derive a physically consistent dehazing-denoising process that simultaneously removes haze and noise to restore a clean image in a manner aligned with the forward degradation process. To further enhance practicality, we propose Latent HNDiff, which compiles clean latent priors that can be seamlessly integrated into existing dehazing networks to boost performance. Extensive experiments show that our work significantly improves leading dehazing backbones and achieves state-of-the-art results on benchmark datasets. The project page is available at https://jin-ting-he.github.io/HNDiff .","authors":["Jin-Ting He","Fu-Jen Tsai","Yan-Tsung Peng","Min-Hung Chen","Chia-Wen Lin","Yen-Yu Lin"],"published":"2026-08-11T14:47:38Z","updated":"2026-08-11T14:47:38Z","abstract_url":"https://arxiv.org/abs/2608.10995v1","html_url":"https://arxiv.org/html/2608.10995v1","pdf_url":"https://arxiv.org/pdf/2608.10995v1.pdf","matched_keywords":["diffusion"],"source_used":"html","source_text_chars":55627,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 diffusion 相关；摘要显示其主要贡献为：Existing diffusion-based methods have recently made significant progress in image dehazing. However, they typically neglect the physics of haze formation and reconstruct clean images from pure Gaussian noise, thereby limiting their restoration potential. To a...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:09+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10985v1","title":"PEAK: Precise and Persistent Concept Erasure via k-Sparse Autoencoders","abstract":"Erasing concepts from large-scale text-to-image (T2I) diffusion models has become increasingly crucial due to the growing concerns over copyright infringement, privacy violations, and offensive content. Existing approaches struggle to achieve both precise and persistent concept erasure: inaccurate localization of concept-related representations may cause unintended semantic interference, while incomplete removal of the underlying concept knowledge allows adversarial recovery. To address this dilemma, we propose PEAK, a \\textbf{\\textit{precise}} and \\textbf{\\textit{persistent}} concept erasure framework via k-Sparse Autoencoders (kSAEs). PEAK first trains a kSAE on internal activations of the diffusion denoising network to decompose dense representations into interpretable sparse features. By contrasting sparse activations induced by target and non-target prompts, PEAK identifies a compact set of target-specific features according to both activation strength and frequency. These localized features are then used for parameter optimization, where PEAK selectively suppresses target-related activations while preserving complementary non-target ones towards the original model. This feature-guided optimization embeds concept erasure directly into diffusion parameters, eliminating the need for additional inference-time intervention and facilitating effective persistence against adversarial attacks. Extensive experiments demonstrate that PEAK achieves effective and robust concept erasure. On the I2P benchmark, PEAK reduces NudeNet detections from 582 to 6, lowers the average attack success rate (ASR) from 96.52\\% to 5.63\\%, and preserves general generation quality on MS-COCO with a near-zero KID. Our code and models are available at: https://github.com/manmanTAT/PEAK","authors":["Man Jiang","Ouxiang Li","Weibao Xue","Zhenhua Tang","Yuan Wang","Shuo Wang","Yanbin Hao"],"published":"2026-08-11T14:38:01Z","updated":"2026-08-11T14:38:01Z","abstract_url":"https://arxiv.org/abs/2608.10985v1","html_url":"https://arxiv.org/html/2608.10985v1","pdf_url":"https://arxiv.org/pdf/2608.10985v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"html","source_text_chars":71459,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation, diffusion 相关；摘要显示其主要贡献为：Erasing concepts from large-scale text-to-image (T2I) diffusion models has become increasingly crucial due to the growing concerns over copyright infringement, privacy violations, and offensive content. Existing approaches struggle to achieve both precise and...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:09+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10981v1","title":"ThinkAfford: Affordance-Centric Reasoning for Fine-Grained 3D Grounding in Cluttered Scenes","abstract":"Task-driven 3D affordance grounding aims to localize the functional region in a cluttered 3D scene that enables an action specified by a natural-language instruction. Existing methods either predict 3D masks directly or construct them by selecting and fusing intermediate 2D/3D regions. However, they remain vulnerable to two intertwined failure modes: the predicted or selected regions may miss the target interaction area or have unsuitable granularity, while language grounding may confuse visually similar alternatives under relational instructions. To this end, we introduce ThinkAfford, which decouples high-recall affordance proposal generation from instruction-grounded reasoning. Specifically, the Affordance Proposal Generation module first uses learnable affordance prompts and multi-level visual features to predict interaction-conditioned heatmaps, extracting a variable number of fine-grained proposals without parsed object or part names as segmentation prompts. Visual-Prompted Affordance Reasoning then reasons over labeled proposal overlays using the full instruction, returning identifiers in a structured \"think-then-answer\" response. Moreover, Group Relative Policy Optimization uses proposal-level rewards from lifted 3D overlap to align VPAR selection with final 3D grounding. On the SceneFun3D validation split, ThinkAfford achieves 10.69% AP50 and 25.46% AP25 under the official evaluator, outperforming comparable 3D open-vocabulary and vision-language-model-based 2D-to-3D baselines. Module-level diagnostics further show that APG attains 77.5% recall at 25% intersection-over-union, while GRPO-trained VPAR achieves 72.1% selection accuracy on APG-covered queries, compared with 63.4% under supervised fine-tuning.","authors":["Xinrui Lin","Sha Zhang","Shumin Wang","Zenghuan Zhu","Jiajun Deng","Yanyong Zhang"],"published":"2026-08-11T14:36:16Z","updated":"2026-08-11T14:36:16Z","abstract_url":"https://arxiv.org/abs/2608.10981v1","html_url":"https://arxiv.org/html/2608.10981v1","pdf_url":"https://arxiv.org/pdf/2608.10981v1.pdf","matched_keywords":["3d"],"source_used":"html","source_text_chars":39689,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d 相关；摘要显示其主要贡献为：Task-driven 3D affordance grounding aims to localize the functional region in a cluttered 3D scene that enables an action specified by a natural-language instruction. Existing methods either predict 3D masks directly or construct them by selecting and fusing...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:09+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10964v1","title":"CARE: Confidence-Aware Reasoning for Reliable Medical VQA","abstract":"Reinforcement Fine-Tuning (RFT) has enabled medical Multimodal Large Language Models (MLLMs) to produce Chain-of-Thought (CoT) reasoning for visual question answering, yet these models suffer from $\\textit{confidence miscalibration}$---a systematic gap between expressed certainty and actual diagnostic accuracy that undermines clinical trust. We propose $\\textbf{CARE}$, a $\\textbf{C}$onfidence-$\\textbf{A}$ware medical $\\textbf{RE}$asoning framework that jointly optimizes accuracy and calibration through a dual-stage pipeline. First, a scalable Medical-CoT synthesis provides structured cold-start data for Supervised Fine-Tuning. Second, Group Relative Policy Optimization (GRPO) with a novel $\\textbf{Confidence-Aware Reward (CAR)}$ mechanism ties the model's confidence to diagnostic correctness within the reward signal. Across three Medical VQA benchmarks, $\\textbf{CARE}$ achieves the highest diagnostic accuracy while obtaining the lowest Expected Calibration Error and Hallucination Rate, establishing a foundation for trustworthy clinical decision support. Our code is available at https://github.com/anotherbricki/CARE.","authors":["Yuetian Du","Yucheng Wang","Zhenyuan Chen","Luyuan Chen","Rongyu Zhang","Jinjian Zhang","Wei Zhou","Zhijie Xu","Ming Kong","Zhan Zhou","Jie Liu","Qiang Zhu"],"published":"2026-08-11T14:28:52Z","updated":"2026-08-11T14:28:52Z","abstract_url":"https://arxiv.org/abs/2608.10964v1","html_url":"https://arxiv.org/html/2608.10964v1","pdf_url":"https://arxiv.org/pdf/2608.10964v1.pdf","matched_keywords":["multimodal"],"source_used":"html","source_text_chars":27937,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 multimodal 相关；摘要显示其主要贡献为：Reinforcement Fine-Tuning (RFT) has enabled medical Multimodal Large Language Models (MLLMs) to produce Chain-of-Thought (CoT) reasoning for visual question answering, yet these models suffer from $\\textit{confidence miscalibration}$---a systematic gap betwee...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:09+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10954v1","title":"Evidence-Grounded Trustworthy Multimodal Reasoning and Evaluation Benchmark in Complex Urban Scenes","abstract":"While Multimodal Large Language Models (MLLMs) demonstrate impressive performance in benign scenarios, their cognitive reliability deteriorates significantly in complex scenes under adverse conditions. In these settings, models often rely on implicit inference without sufficient visual evidence, leading to a disconnect between perception and reasoning. Meanwhile, existing outcome-oriented benchmarks evaluate only final predictions and fail to diagnose failures in the underlying reasoning process. To address this gap, the authors propose AD2-Bench, which introduces a Hierarchical Visual Diagnosis framework that decomposes reasoning into a structured Chain of Evidence (CoE). This fine-grained diagnosis reveals that robust multimodal reasoning fundamentally depends on accurate evidence acquisition. Building on this perspective, the authors formulate reasoning from a probabilistic viewpoint and identify two primary causes of reasoning failure: Spatial Ambiguity, where models fail to distinguish target objects from background clutter, resulting in localization errors; and Semantic Uncertainty, where degraded visual features lead to incorrect semantic interpretation, resulting in understanding errors. To overcome these evidence deficiencies, they further propose Evidence-grounded Visual Reasoning (EGVOR), which replaces implicit reasoning with the explicit generation of Evidence Atoms - structured spatial-semantic triplets that enforce tight alignment between localization and semantic understanding. The model is trained through a hierarchical curriculum that progresses from reflective supervision construction to reinforcement learning, where reducing reasoning variance is explicitly rewarded. Extensive experiments demonstrate that EGVOR substantially improves reasoning stability under adverse conditions, providing a more robust framework for trustworthy multimodal cognition.","authors":["Zhaoyang Wei","Bowen Jiang","Xumeng Han","Jiashu Li","Xuehui Yu","Yuling Liu","Guorong Li","Zhenjun Han","Jianbin Jiao"],"published":"2026-08-11T14:23:07Z","updated":"2026-08-11T14:23:07Z","abstract_url":"https://arxiv.org/abs/2608.10954v1","html_url":"https://arxiv.org/html/2608.10954v1","pdf_url":"https://arxiv.org/pdf/2608.10954v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10952v1","title":"Multiple Scale Latents for Learned Image Compression","abstract":"Most learned image compression systems rely on a single latent representation combined with a hyperprior, which limits their ability to efficiently capture image structure across spatial scales. In this work, we propose a hierarchical latent representation to improve the efficiency of the entropy model. By using multiple latents at different scales, each with its own entropy model, we better capture the spatial structure of the latent representation. Our experiments show that this approach achieves a 17.9% BD-rate reduction over VVC on Kodak, demonstrating the effectiveness of multi-scale latent representations. Furthermore, the approach is orthogonal to other advances in learned image compression, making it a versatile addition to existing methods.","authors":["Jonas Brenig","Radu Timofte"],"published":"2026-08-11T14:22:20Z","updated":"2026-08-11T14:22:20Z","abstract_url":"https://arxiv.org/abs/2608.10952v1","html_url":"https://arxiv.org/html/2608.10952v1","pdf_url":"https://arxiv.org/pdf/2608.10952v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10949v1","title":"StreamFlow: Dynamic Memory Flows for Streaming Video Understanding","abstract":"Streaming video understanding requires multimodal large language models (MLLMs) to preserve relevant evidence from continuously evolving streams under strict causality and bounded memory. Yet existing paradigms remain limited: model-based methods require intrusive backbone updates, while memory-based methods expend substantial visual-encoding computation on temporally redundant content and rely on rigid access to visual history. To address these limitations, we introduce StreamFlow, an efficient visual memory framework that enables dynamic, on-demand access to historical visual information. StreamFlow combines a lightweight, dynamics-aware mid-term memory that filters temporal redundancy before visual encoding with a latent long-term memory that consolidates historical video content into visual latents accessible to subsequent reasoning. During generation, an attention-guided retrieval mechanism injects relevant visual latents when the model's reliance on visual evidence weakens. StreamFlow achieves state-of-the-art streaming video understanding performance, reaching 67.73% overall accuracy on StreamingBench, while also delivering strong performance on offline long-video benchmarks. Relative to the vanilla setting, it improves the visual attention score (VAS) by 59.1% while reducing end-to-end latency and peak memory by 50.4% and 21.1%, respectively, enabling more visually grounded and efficient reasoning.","authors":["Muxin Fu","Yifan Zhang","Wentao Zhang","Fangming Guo","Qian Chen","Guibin Zhang","Shuicheng Yan","Bo An"],"published":"2026-08-11T14:19:03Z","updated":"2026-08-11T14:19:03Z","abstract_url":"https://arxiv.org/abs/2608.10949v1","html_url":"https://arxiv.org/html/2608.10949v1","pdf_url":"https://arxiv.org/pdf/2608.10949v1.pdf","matched_keywords":["video","retrieval","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10938v1","title":"GS-CPE: Unified 6-Degree-of-Freedom Camera Pose Estimation via 3D Gaussian Splatting","abstract":"Despite substantial progress in visual localization, from scene coordinate regression to direct camera pose regression, achieving both robust generalization and high accuracy remain challenging. This study introduces GS-CPE (Gaussian Splatting based Camera Pose Estimation), a coarse-to-fine framework for 6-DoF camera pose estimation that unifies geometry-based coarse pose estimation with robust 3D Gaussian Splatting (3DGS) warping based pose refinement. GS-CPE first estimates a coarse pose via retrieval-guided geometric pose estimation on a 3DGS scene representation, then refines it by minimizing a visibility aware masked RGB warping objective in a multi-scale optimization framework, with adaptive re-rendering. Extensive experiments on indoor and outdoor benchmarks including 7Scenes, Cambridge Landmarks, FAST-LIVO2 datasets, and a custom dataset demonstrate state-of-the-art performance, consistently outperforming in both accuracy and generalization.","authors":["Huaiyuan Weng","Chul Min Yeum","Su-Min Kang"],"published":"2026-08-11T14:06:51Z","updated":"2026-08-11T14:06:51Z","abstract_url":"https://arxiv.org/abs/2608.10938v1","html_url":"https://arxiv.org/html/2608.10938v1","pdf_url":"https://arxiv.org/pdf/2608.10938v1.pdf","matched_keywords":["retrieval","3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10933v1","title":"SafeCA: Safe Cross-Attention Localization and Regulation for Text-to-Video Jailbreak Defense","abstract":"Text-to-Video (T2V) generative models are vulnerable to jailbreak attacks in real-world deployment, leading them to produce harmful or inappropriate content. Existing defense approaches mainly rely on input filtering or reconstruction, which not only incur high computational latency but also tend to distort semantics. To address these issues, we experimentally and systematically analyze the differences between clean and jailbreak samples in the cross-attention feature space, revealing for the first time a cumulative separation effect and a progressively increasing trend of linear separability between the two during the diffusion process. Based on this insight, we propose SafeCA, a feature-level defense mechanism for safe cross-attention localization and regularization. Firstly, we identify key defensive regions and values through attention stability analysis using cross-attention features collected from clean prompts within a single inference. Secondly, SafeCA mitigates anomalous activations via attention masking with energy normalization and introduces a lightweight semantic-space adapter to redirect abnormal semantic flows. Furthermore, we detect and suppress potentially malicious tokens by back-propagating feature anomaly signals to the input cue words, thereby enhancing the deployability of the defense in commercial models. Experimental results show that SafeCA reduces the jailbreak success rate by about 20% on mainstream T2V models, adds almost no inference overhead (+0.1s), and maintains good text-video semantic consistency. Overall, SafeCA provides an architecture-level, deployable protection paradigm for T2V generation models.","authors":["Siyuan Liang","Yupeng Qiu","Junfeng Fang","Rong-Cheng Tu","Jiaxing Huang","Dacheng Tao"],"published":"2026-08-11T14:01:24Z","updated":"2026-08-11T14:01:24Z","abstract_url":"https://arxiv.org/abs/2608.10933v1","html_url":"https://arxiv.org/html/2608.10933v1","pdf_url":"https://arxiv.org/pdf/2608.10933v1.pdf","matched_keywords":["video","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10932v1","title":"Temporally Grounded Compositional Camera Motion Understanding via Geometric Knowledge Distillation","abstract":"Understanding camera motion is fundamental to video perception, with applications in spatial intelligence and controllable video generation. Multimodal large language models (MLLMs) provide a natural interface for this task, but existing work typically assigns one or more labels to an entire clip. Such clip-level recognition overlooks two defining properties of real camera motion: it can change within a shot, and multiple movements can occur simultaneously. We therefore formulate camera-motion understanding as temporally grounded, compositional recognition, which requires a model to localize motion-consistent intervals and identify every movement active within each interval. We introduce CamChoreo, a benchmark of 4,229 real single-shot clips with expert-annotated temporal segments. Its annotations use a compact vocabulary of 20 direction-aware labels, and nearly half of the segments contain compound camera motion, with multiple movement primitives active simultaneously. Recognizing such fine-grained, compositional motion is hard for current MLLMs, whose visual encoders emphasize semantic content rather than the geometric evidence on which camera motion depends. Directly injecting features from a frozen 3D foundation model addresses this gap, but requires running the expensive geometry model on every input; we refer to this baseline as CamInject. We instead propose CamDistill, which distills the same geometric knowledge into lightweight camera tokens during training and removes the 3D model at inference. CamDistill matches the accuracy of direct feature injection without running the 3D teacher at inference. Together, CamChoreo and CamDistill advance camera-motion understanding from clip-level labeling to temporally grounded, compositional recognition. Project page: https://ddz16.github.io/cammotion.github.io/.","authors":["Dazhao Du","Shiyan Du","Jian Liu","Yongjian Yu","Bohai Gu","Tao Han","Hualuo Liu","Eric Liu","Yujia Zhang","Xi Chen","Song Guo"],"published":"2026-08-11T14:00:02Z","updated":"2026-08-11T14:00:02Z","abstract_url":"https://arxiv.org/abs/2608.10932v1","html_url":"https://arxiv.org/html/2608.10932v1","pdf_url":"https://arxiv.org/pdf/2608.10932v1.pdf","matched_keywords":["video","3d","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10908v1","title":"Order Matters: LVLMs as Judges for Temporal Reasoning in Image Sequences","abstract":"As generative multimedia evolves from static image synthesis to complex, interleaved visual narratives, a foundational bottleneck has emerged: the judgment crisis. While human perception naturally synthesizes the temporal and logical flow of a story, automated evaluation systems remain largely \"blind\" to sequential continuity, often failing to distinguish between a coherent narrative and a semantically shuffled or contradictory sequence. This work identifies a critical structural gap in current multimodal evaluation paradigms, arguing that the reliance on Large Vision-Language Models (LVLMs) as judges is fundamentally limited by architectural biases. Our analysis reveals a profound performance dichotomy: while models may appear competent in isolated pointwise scoring, they suffer a catastrophic collapse when required to perform pairwise discrimination of temporal order. We demonstrate that this is not merely a data-scarcity issue but a structural one. Through a series of diagnostic probes, we uncover systematic positional asymmetries, specifically primacy and recency effects, where a model's judgment of a story is significantly influenced by the placement of a frame, often more than by its semantic consistency. These biases, potentially rooted in causal masking and rotary embeddings, suggest that current transformer-based judges are inherently ill-equipped for long-form visual reasoning. By exposing these blind spots, we challenge the multimedia community to move beyond snapshot-centric metrics and instead pioneer Temporally-Aware Evaluation paradigms that treat visual sequences as unified logical structures rather than unordered collections of frames.","authors":["Martina Ianaro","Guilherme Fernandes","Maurizio Gabbrielli","Joao Magalhaes"],"published":"2026-08-11T13:29:03Z","updated":"2026-08-11T13:29:03Z","abstract_url":"https://arxiv.org/abs/2608.10908v1","html_url":"https://arxiv.org/html/2608.10908v1","pdf_url":"https://arxiv.org/pdf/2608.10908v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10888v1","title":"Sensor-Informed Per-Point Covariance for Structured-Light 3D Imaging","abstract":"Per-point uncertainty models are important in structured-light 3D reconstruction for probabilistic registration, fusion, and quality assessment. In practice, however, point-cloud covariances are often modeled as isotropic constants or inferred from local surface geometry and therefore do not explicitly reflect the measurement process. This is a limitation in fringe projection profilometry (FPP), where phase noise propagates through calibrated reconstruction and produces strongly anisotropic 3D uncertainty. This paper presents a sensor-informed first-order method for constructing a per-point 3 x 3 covariance field from experimentally measured phase precision and calibrated phase-to-depth and phase-to-3D mappings. The formulation separates a rank-1 phase-induced covariance from an effective full-rank completion obtained by incorporating fitted lateral image-space perturbation scales. Repeated-plane experiments under fixed imaging conditions show close alignment of the dominant covariance direction with the viewing ray, and consistency between the dominant phase-induced uncertainty scale and scalar depth uncertainty. In G-ICP registration, the proposed covariance substantially improves over a constant isotropic model while providing a sensor-derived uncertainty representation complementary to conventional geometry-based covariances.","authors":["Sehoon Tak","Jae-Sang Hyun"],"published":"2026-08-11T13:05:22Z","updated":"2026-08-11T13:05:22Z","abstract_url":"https://arxiv.org/abs/2608.10888v1","html_url":"https://arxiv.org/html/2608.10888v1","pdf_url":"https://arxiv.org/pdf/2608.10888v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10886v1","title":"GESTO: Human-Centric Spatio-Temporal Memory for Reasoning in Dynamic Scenes","abstract":"Robots operating in human environments need memories that capture not only what objects exist and where, but also how people use them over time and how individual interactions compose into goal-directed activities. Existing 4D scene graphs preserve object and place histories but omit activity structure, whereas activity representations are either not grounded in persistent 3D scenes or rely on externally provided event boundaries and object associations. We present GESTO (Grounded Event and Spatio-Temporal memOry), a spatio-temporal memory that couples a persistent 4D scene graph with a two-level hierarchy of atomic human--object interactions and goal-driven events. From an RGB-D observation stream, GESTO automatically extracts timestamped interactions, grounds them to persistent scene entities, groups them into events, and uses event context to refine uncertain object associations. A relation-aware tool-calling agent queries the resulting memory for activity-centric spatio-temporal reasoning. We evaluate GESTO on the reproducible text, binary, and time categories of an existing benchmark, together with 40 new Space2Event and Event2Space queries. GESTO achieves scores of 0.71, 0.75, and 0.70 on the standard categories, approaching a method supplied with ground-truth event and object grounding, while substantially outperforming the same reasoning framework when these inputs are removed. It further achieves 0.73 and 0.75 on Space2Event and Event2Space queries. Ablations show that hierarchical event structure and context-aware grounding refinement provide complementary benefits, supporting activity-grounded hierarchical memory for retrospective reasoning in dynamic human environments.","authors":["Ermanno Bartoli","Buwei He","Dennis Rotondi","Sebastian Koch","Federico Tombari","Kai O. Arras","Patric Jensfelt","Yixi Cai","Iolanda Leite"],"published":"2026-08-11T13:03:33Z","updated":"2026-08-11T13:03:33Z","abstract_url":"https://arxiv.org/abs/2608.10886v1","html_url":"https://arxiv.org/html/2608.10886v1","pdf_url":"https://arxiv.org/pdf/2608.10886v1.pdf","matched_keywords":["3d","agent","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10870v1","title":"NullEdit: Stealthy Image Protection via VLM Condition Redirection","abstract":"Modern image editors combine vision-language models (VLMs) with diffusion transformer backbones to modify a single reference image according to instructions without fine-tuning. This capability also enables unauthorized manipulation of publicly released images. Existing inference-time defenses either invalidate edits through conspicuous corruption, thereby exposing the protection, or allow them to proceed with identity or reference content drift, thereby failing to prevent the editing behavior itself. We instead target a stealthy and harmless no-op in which the requested edit is suppressed, the output remains natural and source-preserving without conspicuous artifacts or identity replacement, and harmful semantics requested by malicious instructions are absent. We propose NullEdit, which targets the VLM representation jointly formed from the reference image and instruction before it conditions the downstream DiT backbone. Using normal-edit and no-edit anchors, NullEdit redirects this representation, while cross-prompt gradient averaging transfers protection to held out instructions. Across Step1X-Edit and Qwen-Image-Edit on CelebA-HQ and VGGFace2, NullEdit reduces the EditReward IF score by 0.813 on average relative to the SOTA baseline while preserving subject identity and source content.","authors":["Weiyao Huang","Liqin Wang","Ziqi Sheng","Wei Lu"],"published":"2026-08-11T12:46:09Z","updated":"2026-08-11T12:46:09Z","abstract_url":"https://arxiv.org/abs/2608.10870v1","html_url":"https://arxiv.org/html/2608.10870v1","pdf_url":"https://arxiv.org/pdf/2608.10870v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10864v1","title":"Multi-View Relational Distillation for Spatial Reasoning with Vision-Language Models","abstract":"Vision-language models (VLMs) have achieved strong image and video understanding, yet their visual-spatial representations remain geometrically fragile, leading to failures in spatial reasoning needed for embodied AI, robotics, and autonomous driving. Prior approaches to geometry grounding either fine-tune VLMs on spatial question answering, which can perpetuate spurious visual representations, or fuse features from large geometry-grounded vision models, which substantially increases model size at inference. Knowledge distillation from geometry-grounded vision models offers an alternative, but directly matching multi-view teacher features can disrupt the pretrained alignment between visual and textual representations, degrading object- and language-semantic capabilities. We propose multi-view relational distillation (MVRD), which distills patch-wise cosine similarities across views instead of the teacher features themselves. These relations encode geometric correspondences adequate for spatial understanding, while leaving the student representation underdetermined, allowing it to remain close to its pretrained vision- language space. Across representative VLMs, MVRD improves visual-spatial reasoning, outperforming supervised fine-tuning and feature distillation while approaching feature fusion methods with considerably fewer added parameters and lower latency. We show that MVRD makes visual representations more geometric while retaining language alignment, and generalizes to 3D scene understanding tasks such as object grounding, dense captioning, and question answering.","authors":["Kiet T. Nguyen","Hanbo Shim","Jinwoo Kim","Seunghoon Hong"],"published":"2026-08-11T12:34:41Z","updated":"2026-08-11T12:34:41Z","abstract_url":"https://arxiv.org/abs/2608.10864v1","html_url":"https://arxiv.org/html/2608.10864v1","pdf_url":"https://arxiv.org/pdf/2608.10864v1.pdf","matched_keywords":["video","3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10860v1","title":"Flex-$π$: A Multi-Stream World-Action Model with Compute Flexibility","abstract":"World-action models (WAMs) predict the future to act better, but nearly all of them predict only RGB latents, trained purely for pixel reconstruction, with no explicit signal for the 3D geometry or object semantics manipulation needs. We find a surprising free lunch: the same frozen video-generation VAE that encodes RGB also encodes 3D pointmaps almost losslessly, with no pointmap-specific training at all. This lets us supervise Flex-$π$, a 6B-parameter WAM, on 3D geometry and object-centric DINO semantics alongside RGB, at no cost in new sensors, new pre-training, or inference latency. Every visual signal is projected into this shared latent space and denoised jointly with actions inside a Mixture-of-Transformers backbone; per-stream dropout with cross-modality forcing then lets a single trained checkpoint run on any subset of these streams, from a fast action-only mode to full joint generation. The result is a policy that is exceptionally demonstration-efficient and generalizes well, beating the strongest baselines by up to 2-7$\\times$ on dexterous, precise, real-world bimanual manipulation tasks both in and out of distribution, all while running faster than $π_{0.5}$. Our project website: https://flex-pi.github.io/","authors":["Ge Yan","Jinghao Liu","Yuzhi Fan","Lei Cai","Minwen Liao","Jesse Zhang","Dieter Fox"],"published":"2026-08-11T12:33:51Z","updated":"2026-08-11T12:33:51Z","abstract_url":"https://arxiv.org/abs/2608.10860v1","html_url":"https://arxiv.org/html/2608.10860v1","pdf_url":"https://arxiv.org/pdf/2608.10860v1.pdf","matched_keywords":["video","3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10838v1","title":"PolyLayout: Hierarchical VLM-Guided Layout Generation Beyond Rectangular Rooms","abstract":"Generating physically plausible 3D room layouts is essential for home furnishing retail, enabling customers to visualize products in their own homes and confidently make purchasing decisions. However, a gap exists between academic research and real-world application: existing solutions primarily focus on algorithmic strategies for furniture placement, largely neglecting the non-rectangular geometries and strict door/window constraints prevalent in real homes. To bridge the gap, we introduce a hybrid, hierarchical framework tailored for retail, specifically designed to support scalable spatial planning applications. Our system decouples generation into three stages: (1) functional furniture clustering and fine-grained intra-zone placement; (2) macro-routing guided by a vision-language model (VLM) to anchor both these clustered zones and any remaining standalone furniture within diverse polygonal boundaries; and (3) rule-based optimization for collision-free micro-arrangements that respect architectural constraints. We evaluate our system on production-scale catalogs and a representative set of irregular real-world topologies. Our results show that our approach attains the highest perceptual plausibility while maintaining good geometric compliance at relatively low latency, and extends to irregular boundaries that existing methods do not natively support.","authors":["Yutong Jiang","Zahra Atashgahi","Carlos Soto Garcia Delgado","Ruben Brokkelkamp","Davide Zanutto","Efşan Sökmen","Shahin Shahkarami"],"published":"2026-08-11T12:04:14Z","updated":"2026-08-11T12:04:14Z","abstract_url":"https://arxiv.org/abs/2608.10838v1","html_url":"https://arxiv.org/html/2608.10838v1","pdf_url":"https://arxiv.org/pdf/2608.10838v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10835v1","title":"UniProbe: A Learnable Token-Level Hallucination Detector for Large VLMs using Multi-Structural Internal Representations","abstract":"Large Vision-Language Models (LVLMs) achieve impressive visual reasoning and dialogue capabilities, yet frequently hallucinate content unsupported by the visual input. Effective mitigation requires token-level localization, enabling targeted intervention without discarding the entire response. Existing detectors require expensive full-model fine-tuning, rely on external verifiers that ignore the model's generation process, or reduce internal signals to isolated features and hand-crafted statistics, discarding spatial, sequential, and relational structure. We introduce \\textbf{UniProbe}, a lightweight, unified, learnable detector that models a frozen LVLM's heterogeneous computational trace from a single forward pass. UniProbe constructs a directed graph over image patches, query tokens, and generated tokens, with attention weights encoding their relations. It processes this trace with alternating structure-aware modules: a GNN for relational evidence, a ViT for 2-D visual geometry, and a GRU for response order. Interleaving them allows spatial, relational, and sequential evidence to interact throughout the detector. We further develop a streaming variant for hallucination-aware decoding, which detects and resamples hallucinated tokens during generation, and a self-adaptation strategy aligning the detector with the LVLM's own generations. Across diverse LVLM backbones, UniProbe achieves state-of-the-art token-level and object-hallucination detection. During decoding, it reduces object hallucinations by up to 55\\% at $1.06\\times$ the latency of standard generation.","authors":["Dvir Samuel","Guy Bar-Shalom","Fabrizio Frasca","Ethan Fetaya","Yftah Ziser","Gal Chechik","Haggai Maron"],"published":"2026-08-11T12:01:59Z","updated":"2026-08-11T12:01:59Z","abstract_url":"https://arxiv.org/abs/2608.10835v1","html_url":"https://arxiv.org/html/2608.10835v1","pdf_url":"https://arxiv.org/pdf/2608.10835v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10827v1","title":"MIRA: Medical Image Reflection for Agentic Diagnosis","abstract":"Medical visual agents can use tools to inspect images and retrieve external knowledge, but indiscriminate tool use may introduce noisy or misleading evidence. Reliable diagnosis therefore requires not only acquiring additional observations, but also verifying whether tool actions are necessary and whether the resulting evidence supports the current hypothesis. We introduce MIRA (Medical Image Reflection for Agentic Diagnosis), a medical visual diagnostic framework for autonomous evidence search and reflective verification. MIRA dynamically invokes image-processing operations, including zooming, grounding, pointing, rotation, and measurement, as well as web search, while evaluating the relevance and consistency of the acquired evidence. We develop MIRA through a two-stage training strategy. First, a tool-augmented Monte Carlo Tree Search data engine explores diverse diagnostic hypotheses and jointly verifies visual grounding accuracy and semantic consistency to construct supervised fine-tuning trajectories. Second, reinforcement learning further improves decision-making through online reflective principle evolution: failure cases are distilled into candidate principles, and only principles that improve held-out rollout rewards are retained. Across nine medical visual reasoning benchmarks, MIRA achieves an average score of 64.73, improving its Qwen3-VL-8B backbone by 7.44 points. It also increases useful tool-use judgments from 56.2% to 73.8% and reduces harmful judgments from 8.9% to 1.6%. Qualitative analyses show that MIRA can re-examine evidence, correct premature conclusions, and adapt its tool-use strategy. Project page: https://MIRA-VL.github.io/","authors":["Shengzhi Wang","Jun Yang","Kai Wu","Xiaozhong Ji","Yiwen Ye","Ziyang Chen","Mingliang Xiong","Wen Fang","Mingqing Liu","Mengyuan Xu","Miaoxuan Shan","Caiyan Liu","Bin He","Qingwen Liu"],"published":"2026-08-11T11:57:27Z","updated":"2026-08-11T11:57:27Z","abstract_url":"https://arxiv.org/abs/2608.10827v1","html_url":"https://arxiv.org/html/2608.10827v1","pdf_url":"https://arxiv.org/pdf/2608.10827v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10824v1","title":"Neural Introspection Gating for Adaptive KV-Cache Reuse in Vision-Language-Action Models","abstract":"Vision-Language-Action(VLA) models map camera images and language instructions directly to motor commands through a single autoregressive transformer. In real-time control, they still spend substantial compute recomputing key-value(KV) representations for visual tokens that barely change across neighboring frames. Recent work such as VLA-Cache reduces that cost by reusing KV states for visually static patches, but its policy relies only on observation-space heuristics and does not account for the model's own uncertainty. We propose Gated VLA-Cache, a lightweight, training-free extension that augments visual-similarity caching with neural introspection. The method monitors the logit margin between the top two predicted action tokens, a zero-cost confidence signal available during decoding. When the margin drops below a threshold, the cache is invalidated and a full recompute is triggered. Evaluated on four LIBERO benchmark suites with both OpenVLA and OpenVLA-OFT, Gated VLA-Cache improves reliability when blind caching hurts. On LIBERO-Goal and LIBERO-Long, it recovers over 100% of the lost accuracy while retaining 80% of the compute savings.","authors":["Zhijie Wu","Kento Kawaharazuka","Kei Okada"],"published":"2026-08-11T11:53:10Z","updated":"2026-08-11T11:53:10Z","abstract_url":"https://arxiv.org/abs/2608.10824v1","html_url":"https://arxiv.org/html/2608.10824v1","pdf_url":"https://arxiv.org/pdf/2608.10824v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10807v1","title":"Modelling Geographic Atrophy Progression using Implicit Neural Representations","abstract":"Age-related Macular Degeneration (AMD) is the major cause of blindness in the Western world. Its late dry phase is characterised by irreversible atrophic areas, namely Geographic Atrophy (GA). Longitudinal Fundus Autofluorescence (FAF) image acquisitions are currently the main tool for assessing lesion growth over time at the image level. However, due to its highly individualised progression, the evolution of late AMD remains poorly understood. In this work, we propose using Implicit Neural Representations (INRs) to model GA progression at the individual level in a low-data setting. Our approach generates both FAF and GA segmentation at both past and future time points. Among the comparison models, our method achieves competitive segmentation quality across different scenarios, yielding the lowest Mean Absolute Error (MAE) for the GA lesion area and the highest DICE score, without sacrificing FAF image quality. The code is available at https://github.com/SimoneSarrocco/ga-progression-with-inrs.","authors":["Simone Sarrocco","Paul Friedrich","Florentin Bieder","Christina Bornberg","Philippe Valmaggia","Peter Maloca","Philippe Cattin"],"published":"2026-08-11T11:26:01Z","updated":"2026-08-11T11:26:01Z","abstract_url":"https://arxiv.org/abs/2608.10807v1","html_url":"https://arxiv.org/html/2608.10807v1","pdf_url":"https://arxiv.org/pdf/2608.10807v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10798v1","title":"Beyond Fixed Luminance: Towards Panchromatic and Orthochromatic Image Colorization","abstract":"Most image colorization systems operate in $Lab$ space by predicting chroma ($ab$) while preserving an input-derived luminance channel ($L$). While effective on standard benchmarks, this fixed-luminance design restricts brightness changes and becomes unreliable when grayscale formation deviates from natural-image luminance, as in historical orthochromatic photography. We propose a luminance-agnostic colorization framework that formulates colorization as full-RGB image editing using a foundation image-editing model. To bridge modern panchromatic and historical orthochromatic conditions, we introduce a mixed grayscale objective that trains the model under both standard luminance grayscale and a red-insensitive grayscale formation. Experiments on COCO, ImageNet, and a multi-instance benchmark show that our method is competitive on standard grayscale inputs and substantially more robust under orthochromatic inputs, with qualitative comparisons and a human study indicating fewer visible color artifacts.","authors":["Swarnim Maheshwari","Syed Imam Ali","Vineeth N. Balasubramanian"],"published":"2026-08-11T11:12:24Z","updated":"2026-08-11T11:12:24Z","abstract_url":"https://arxiv.org/abs/2608.10798v1","html_url":"https://arxiv.org/html/2608.10798v1","pdf_url":"https://arxiv.org/pdf/2608.10798v1.pdf","matched_keywords":["instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10796v1","title":"E$^3$mo-Bench: A Scalable Benchmark for Multimodal Evoked and Expressed Emotion Understanding via Bayesian Pairwise Alignment","abstract":"Understanding both expressed and evoked emotions is critical for multimodal large language models (MLLMs) to achieve comprehensive affect-aware interactions. However, existing benchmarks typically examine expressed and evoked emotions in isolation or are constrained to coarse-grained and incomplete affective characterizations. To bridge this gap, we introduce E$^3$mo-Bench, a scalable benchmark comprising $12{,}314$ question-answer pairs across $2{,}524$ videos with predefined affective perspectives. It evaluates evoked and expressed emotion understanding via $3$ complementary tasks: emotion perception, open-vocabulary recognition, and valence-arousal-dominance (VAD) assessment. To efficiently scale reliable continuous annotations, we propose Bayesian Pairwise Alignment, which aggregates sparse, low-burden pairwise judgments into anchor-referenced VAD estimates. Furthermore, we develop E$^3$mo-Score, a training-free agent that aggregates complementary judgments from a five-model committee to improve VAD estimation. Extensive experiments validate the effectiveness of our framework and expose a pronounced performance skew between evoked and expressed emotion paradigms. These findings, coupled with MLLMs' persistent deficits in fine-grained recognition and dimensional assessment, chart a clear course for advancing multimodal emotional intelligence.","authors":["Lancheng Gao","Ziheng Jia","Shengyan Li","Zixuan Xing","Jiarui Wang","Huiyu Duan","Xiongkuo Min"],"published":"2026-08-11T11:05:22Z","updated":"2026-08-11T11:05:22Z","abstract_url":"https://arxiv.org/abs/2608.10796v1","html_url":"https://arxiv.org/html/2608.10796v1","pdf_url":"https://arxiv.org/pdf/2608.10796v1.pdf","matched_keywords":["video","agent","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10790v1","title":"MVTrack: Ultrafast Appearance-Free Moving Object Tracking from Compressed Bitstreams","abstract":"Deploying modern video trackers at scale is bottlenecked by the computational cost of RGB-based object detectors. To this end, we present MVTrack, an ultrafast tracker for moving objects that operates directly on H.264 bitstreams. MVTrack combines MVDet, a lightweight detector for motion vector fields, with MVLink, a minimalist kinematic association module. On VIRAT, MVTrack outperforms YOLO26n while using 60$\\times$ fewer parameters, requiring 40$\\times$ fewer FLOPs, and reducing CPU latency by 8.6$\\times$. These results demonstrate that compressed video data alone can enable accurate and scalable surveillance tracking, thereby bypassing the need for pixel reconstruction.","authors":["Iñaki Erregue","Kamal Nasrollahi","Sergio Escalera"],"published":"2026-08-11T10:53:22Z","updated":"2026-08-11T10:53:22Z","abstract_url":"https://arxiv.org/abs/2608.10790v1","html_url":"https://arxiv.org/html/2608.10790v1","pdf_url":"https://arxiv.org/pdf/2608.10790v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10764v1","title":"FADE: From Passive Verification to Active Discovery in Counterfactual Video Understanding","abstract":"Counterfactual video understanding evaluates whether models grasp physical and commonsense regularities. However, existing multiple-choice question (MCQ) benchmarks inadvertently leak target events through their questions and candidate options. This reduces the core challenge from active discovery to text-guided verification. In this paper, we present FADE, an effective training framework for counterfactual discovery and explanation. Our method is built on an evidence-first, two-stage training paradigm. First, evidence-internalized supervised fine-tuning grounds the model's predictions in decisive visual anomalies. Second, we apply a fading-anchor reinforcement learning strategy that progressively removes textual guidance, compelling the model to independently discover and explain evidence. To rigorously evaluate this capability, we also introduce an effective pipeline that converts existing MCQ datasets into aligned MCQ, open-ended question answering (OQA), and captioning tasks without requiring additional data curation. Our simple approach yields strong results. Using Qwen3-VL-8B as the baseline, FADE achieves state-of-the-art strict paired scores across all three tasks on DualityVidQA-test and IPV-Bench, outperforming GPT-5.6. In specific, when transitioning from constrained MCQs to unconstrained OQA and captioning, our model demonstrates remarkable robustness. Its performance retention is 90.4% and 67.4% on DualityVidQA-test-substantially higher than the 48.1% and 30.7% retained by GPT-5.6. We hope this simple framework can serve as a solid baseline for future research in unconstrained counterfactual video understanding.","authors":["Fufangchen Zhao","Jinhu Fu","Jiachen Lei","Jiahong Wu","Xiangxiang Chu","Danfeng Yan"],"published":"2026-08-11T10:22:08Z","updated":"2026-08-11T10:22:08Z","abstract_url":"https://arxiv.org/abs/2608.10764v1","html_url":"https://arxiv.org/html/2608.10764v1","pdf_url":"https://arxiv.org/pdf/2608.10764v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10758v1","title":"Where To Look? : Causal Tracing of Vision Encoders in VLM","abstract":"Vision-language models can describe an image with remarkable accuracy, yet a more fundamental question remains unanswered: what visual information actually drives their answers? In this work, we investigate this question through causal tracing, and we observe that highly causal vision tokens often lie outside the target region. Extending the analysis to larger vision-language models reveals a similar pattern across models and corruption settings, suggesting that strong multimodal performance does not necessarily imply spatially localized causal representations. We further investigate: can these models preserve visual structure when appearance cues are removed? and find that visual cues are exploited to understand visual structures. Together, our experiments expose a gap between seeing, using, and reasoning over visual structure, and provide a causal framework for studying how visual information is transformed, preserved, and ultimately used by modern vision-language models.","authors":["Naren Kumar S","Tirth Bhatt","Mayank Singh"],"published":"2026-08-11T10:17:34Z","updated":"2026-08-11T10:17:34Z","abstract_url":"https://arxiv.org/abs/2608.10758v1","html_url":"https://arxiv.org/html/2608.10758v1","pdf_url":"https://arxiv.org/pdf/2608.10758v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10756v1","title":"Embodied Multimodal Grounding for Open-Vocabulary Mobile Manipulation via Semantic 3D Gaussian Splatting","abstract":"Embodied mobile manipulation requires language, visual observations, three-dimensional scene structure, and action feasibility to be aligned before execution. We study open-vocabulary target grounding with few-shot manipulation in local household workspaces and present an embodied multimodal grounding framework that integrates active multi-view Semantic 3D Gaussian Splatting (Semantic-3DGS), reachability-aware base positioning, and a diffusion-based vision-language-action policy. A task-driven local Semantic-3DGS serves as a shared interface across active sensing, language-conditioned 3D localization, obstacle-aware scene reasoning, base preparation, and semantic conditioning of the action model. To preserve pretrained action priors, the 3D semantic cues are injected only into the late action-expert blocks. In expanded 50-trial real-robot evaluations against representative vision-language-action (VLA) approaches, the full system achieves 60% long-horizon success compared with 40% for PointVLA and 28% for DexVLA, and reaches 74% success in heavily cluttered manipulation compared with 52% for the single-view variant and 46% for PointVLA. It also maintains 75% success under a 75 cm height shift and eliminates photo-induced false grasps. These results indicate that explicit, refreshable 3D semantic grounding can improve robustness under clutter, occlusion, viewpoint variation, and embodiment constraints.","authors":["Huosen Ou","Dongni Song","Yuncong Wang","Tao Zhou","Yiding Ji"],"published":"2026-08-11T10:16:30Z","updated":"2026-08-11T10:16:30Z","abstract_url":"https://arxiv.org/abs/2608.10756v1","html_url":"https://arxiv.org/html/2608.10756v1","pdf_url":"https://arxiv.org/pdf/2608.10756v1.pdf","matched_keywords":["3d","multimodal","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10744v1","title":"Beyond Pixels: From Video Priors to 4D Worlds","abstract":"4D generation synthesizes dynamic 3D scenes from conditions such as text or images. Existing methods either reconstruct generated RGB videos with a separate 4D model or adapt a particular video generator to predict geometry directly. The former suffers from distribution mismatch and error propagation, whereas the latter ties 4D prediction to a specific generator and may require retraining when the generator or conditioning regime changes. We ask whether the final denoised latents of video models that share a variational autoencoder (VAE) can instead provide a reusable interface to explicit 4D prediction. Building on this insight, we introduce direct latent-to-4D generation and instantiate it as Latent-to-4D, which bypasses RGB by aligning a video latent with the token grid of a pretrained 4D decoder and refining it through frame-wise and global spatiotemporal attention. Trained on roughly 1K existing reconstruction clips, a single checkpoint transfers unchanged across multiple video diffusion transformers within the same VAE family. On Text4D-200 and I4D-200, Latent-to-4D surpasses matched same-latent Wan+4RC cascades in projection-based DINO-F1 by 2.88--3.45 and 5.81 points, respectively, while also being preferred by human raters for geometry, temporal stability, and overall quality.","authors":["Zihao Liu","Xiaolong Shen","Zhenglin Zhou","Ruijie Quan","Yi Yang"],"published":"2026-08-11T10:02:41Z","updated":"2026-08-11T10:02:41Z","abstract_url":"https://arxiv.org/abs/2608.10744v1","html_url":"https://arxiv.org/html/2608.10744v1","pdf_url":"https://arxiv.org/pdf/2608.10744v1.pdf","matched_keywords":["video","3d","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10724v1","title":"InterPruner: Interactive Structured Pruning via Taylor-Implicit Criterion and Language-Prior Modulator for Multimodal Object Detection","abstract":"Multimodal object detection proves effective in remote sensing, especially the RGB-Infrared paradigm. The parallel feature extractors provide rich multimodal information for robust detection, yet introduce substantial channel redundancy and computational overhead. Existing pruning methods can reduce channel redundancy, but they are designed for unimodal backbones, overlooking cross-modal interactions and dynamic scene-wise redundancy. In this paper, we propose InterPruner, the first interactive structured channel pruning framework for RGB-infrared object detectors. Specifically, we first derive a Taylor-Implicit Criterion(TIC) to quantify channel importance via high-order Taylor expansion and the implicit function theorem. Then, a Modality Interaction Redundancy Analyzer (MIRA) identifies redundant channels via mutual compensability assessment. Finally, a Scene-Prior Channel Anchor (SPCA) uses language priors as semantic anchors to measure channel-scene relevance for dynamic channel importance estimation. Cross-modality channel pruning for RGB-Infrared detection is yet unexplored. Extensive experiments on RGB-infrared object detection dataset demonstrate that InterPruner maintains high performance with negligible degradation. Specifically, it even achieves a 0.6% mAP increase on the FLIR dataset when pruning 50% of the channels. Code will be available on GitHub to facilitate future work.","authors":["Qi Ming","Zihan Yang","Shaoguang Huang","Si Sun","Hanqing Zhang","Nanqing Liu","Jiahui Lv","Juan Fang","Aleksandra Pizurica"],"published":"2026-08-11T09:42:23Z","updated":"2026-08-11T09:42:23Z","abstract_url":"https://arxiv.org/abs/2608.10724v1","html_url":"https://arxiv.org/html/2608.10724v1","pdf_url":"https://arxiv.org/pdf/2608.10724v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10720v1","title":"Ex-Omni-2D: Expressive Omni-Modal Dialogue Models with Native Visual Presence","abstract":"Omni-modal dialogue models can understand multimodal inputs and synthesize spoken replies, yet their responses remain visually disembodied. We introduce \\textbf{Ex-Omni-2D}, an omni-modal dialogue framework that generates a coordinated response comprising text, personalized speech, and reference-conditioned video. Given a multimodal query, reference image, and reference audio, the model predicts a structured \\textit{Visual Thought Plan} (VTP) describing scene, emotion, and motion, followed by response text and native multi-codebook speech units. These units form a shared acoustic-temporal interface: they are decoded into speech and aligned online with video frames. This interface enables the response and avatar pathways to be learned from heterogeneous speech, dialogue, and avatar-video data, avoiding the need for large-scale query--text--speech--video supervision. A full-sequence Video Generator serves as the primary Teacher. For efficient incremental generation, we further distill it into a few-step block-causal \\emph{Streaming Student} whose Prefix Streaming mechanism carries a clean latent across consecutive chunks to reduce cumulative late-chunk degradation. With four-step inference, the complete four-GPU pipeline achieves an end-to-end RTF of 1.293 at $400\\times720$/$720\\times400$, providing a practical quality--efficiency operating point.","authors":["Haoyu Zhang","Zhipeng Li","Xiaoying Tang","Tianshu Yu","Yiwen Guo"],"published":"2026-08-11T09:37:11Z","updated":"2026-08-11T09:37:11Z","abstract_url":"https://arxiv.org/abs/2608.10720v1","html_url":"https://arxiv.org/html/2608.10720v1","pdf_url":"https://arxiv.org/pdf/2608.10720v1.pdf","matched_keywords":["video","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10712v1","title":"Compact Feed-Forward 3D Gaussians via Saliency-Guided Primitive Merging","abstract":"3D scene reconstruction, modeling, and rendering are highly relevant for numerous tasks, and 3D Gaussian splatting has become a standard choice in this context. Its feed-forward variants provide fast reconstruction from sparse input views but often produce per-pixel primitives, leading to highly redundant and thus inefficient representations. We present a structure-aware merging pipeline that takes per-pixel primitives from any feed-forward method and consolidates them into a compact, content-adaptive Gaussian set while largely retaining visual quality at just $\\frac{1}{20}^\\text{th}$ of the Gaussians of a per-pixel method. We group spatially coherent Gaussians of similar appearance into variable-size clusters via adaptive superpixel segmentation guided by a saliency map, which allocates fine segments to textured regions and coarse segments to homogeneous areas. We compress each cluster into a compact latent representation through a learned encoder, then match and consolidate representations across views based on geometric overlap and feature similarity via a learned merger. A level-of-detail decoder then produces the final Gaussians at a controllable resolution, enabling a flexible quality-efficiency trade-off at inference. As a post-processing module, the pipeline is backbone-agnostic, leveraging the strengths of existing feed-forward methods. This leads to better and more robust quality than achieved by previous approaches that target a reduction in primitive count, while providing a highly compact representation, that can be rendered efficiently.","authors":["Tim-Felix Fassch","Jochen Kall","Cyrill Stachniss"],"published":"2026-08-11T09:32:08Z","updated":"2026-08-11T09:32:08Z","abstract_url":"https://arxiv.org/abs/2608.10712v1","html_url":"https://arxiv.org/html/2608.10712v1","pdf_url":"https://arxiv.org/pdf/2608.10712v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10708v1","title":"Self-Geometry: GT-Free and Plug-and-Play Test-Time Adaptation for Geometrically Consistent 3D Vision Foundation Models","abstract":"Recent Vision Foundation Models (VFMs) predict depth, camera pose, and pointmap in a single forward pass without per-scene optimization, achieving strong generalization. However, enforcing explicit multi-view geometric consistency, e.g., through bundle adjustment, is computationally costly and is thus not imposed during VFM pretraining, so such inconsistency can arise. To address this, implicit self-consistency derived from model outputs (e.g., pointmaps, features), though enforced at test-time in prior work, delivers inherently limited performance gain, especially on scenes where the pretrained VFM is highly inaccurate. In contrast to this implicit signal, we propose Self-Geometry, a plug-and-play test-time adaptation pipeline that directly imposes explicit multi-view geometric constraints using 2D pixel correspondences as pseudo ground-truth. Our proposed Self-Geometry consists of Geometric Disentanglement Optimization, which combines Multi-View Consistency and Epipolar Consistency losses with Gradient Disentanglement to prevent gradient conflict; Frame Angular-Neighbor, a view sampler based on SO(3) geodesic distances for lightly imposing these constraints; and Lightweight TTA, which adapts VFMs via LoRA. Our method achieves consistent improvements in both pose and geometry estimation across six VFMs (VGGT, $π^3$, DA3-Giant/Large/Base/Small) and four benchmarks (7Scenes, ETH3D, ScanNet++, HiRoom).","authors":["Seokhyun Youn","Dahyeon Kye","Sung-Ho Bae","Jihyong Oh"],"published":"2026-08-11T09:28:50Z","updated":"2026-08-11T09:28:50Z","abstract_url":"https://arxiv.org/abs/2608.10708v1","html_url":"https://arxiv.org/html/2608.10708v1","pdf_url":"https://arxiv.org/pdf/2608.10708v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10706v1","title":"MMArt A Multi-Perspective Multimodal Dataset for Visual Art Understanding","abstract":"Recent vision-language models demonstrate impressive general visual understanding, yet their art interpretation remains shallow: they describe surface content but struggle with formal analysis, grounded historical interpretation, or affective characterization. We argue this is not only a model but also a dataset limitation. Existing art datasets are single perspective resources, where no dataset provides narrative, formal, emotional, and historical perspectives simultaneously for the same artworks. We introduce MMArt, a large-scale dataset of 74,234 WikiArt paintings, each annotated with four independently annotated perspectives plus a harmonized unified caption, produced by specialized vision-language models or human annotation and validated through complementary quality evaluations. Two complementarity analyses establish that perspectives encode genuinely distinct information. A generative analysis shows that formal analysis descriptions best preserve compositional style, and historical descriptions carry strong affective signal in reconstructed images. A discriminative retrieval analysis reveals task-asymmetry: narrative descriptions drive retrieval (R@1 = 44.0%), while formal descriptions, strongest for reconstruction, are nearly nondiscriminative at retrieval scale (R@1 = 7.8%). Leave-one-out analysis further confirms that historical descriptions are the least replaceable perspective across both tasks. Together, the two analyses establish that no single perspective suffices for all tasks, directly motivating MMArt multi-perspective design. The dataset, code, and additional information are available at https://shuaiwang97.github.io/MMArt/.","authors":["Shuai Wang","Wangyuan Ding","Yixian Shen","Jia-Hong Huang","Stevan Rudinac","Monika Kackovic","Nachoem Wijnberg","Marcel Worring"],"published":"2026-08-11T09:28:20Z","updated":"2026-08-11T09:28:20Z","abstract_url":"https://arxiv.org/abs/2608.10706v1","html_url":"https://arxiv.org/html/2608.10706v1","pdf_url":"https://arxiv.org/pdf/2608.10706v1.pdf","matched_keywords":["retrieval","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10682v1","title":"Visual Geometry Foundation-Aware Gaussians for Single-Frame Surround-View Driving Reconstruction","abstract":"Single-frame surround-view reconstruction faces severe geometric instability and rendering artifacts due to minimal inter-camera overlap. While existing methods rely on complex decoders or auxiliary cues, they remain bottlenecked by the weak geometric capacity of upstream features. We argue that leveraging pretrained visual geometry priors strengthens upstream representations and alleviates the geometric ambiguity in sparse surround views. To this end, we propose VGGD, a visual geometry foundation-aware 3D Gaussian Splatting framework for feed-forward surround-view driving reconstruction, which shifts geometric modeling to the frontend and adapts foundation priors to the driving camera setting. First, VGGD leverages VGGT to provide transferable multi-view geometric prior tokens. Next, we introduce a Dual-Path Neck to decouple geometry-consistent and appearance-aware representations, improving appearance completion in weakly observed regions. We further apply Scale Warmup to stabilize early geometry learning and suppress scale drift under ego-pose changes. Finally, we use a hybrid pixel--volume Gaussian decoder to produce a renderable 3D Gaussian scene for novel-view synthesis. Experiments on the nuScenes single-frame benchmark show that VGGD achieves the best overall rendering quality among the compared methods and improves relative geometric consistency.","authors":["Junhong Lin","Jinlong Wang","Xianda Guo","Yanlun Peng","Wei Zheng","Guoqing Liu","Hanli Wang","Tiesong Zhao","Wei Gao"],"published":"2026-08-11T09:04:33Z","updated":"2026-08-11T09:04:33Z","abstract_url":"https://arxiv.org/abs/2608.10682v1","html_url":"https://arxiv.org/html/2608.10682v1","pdf_url":"https://arxiv.org/pdf/2608.10682v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10677v1","title":"Chartography: A Benchmark for Professional Chart Understanding","abstract":"Professionals across medicine, engineering, finance, manufacturing, and the sciences often make consequential decisions from charts. Existing chart benchmarks do not sufficiently measure this ability: they are dominated by bar, line, and pie formats, rely on shorter reasoning chains, and are nearing saturation, with frontier models already scoring 80-90%. We introduce Chartography, a benchmark of 100 tasks that pair charts drawn from professional practice, in domain-specific formats that standard chart benchmarks rarely include, with questions written by professionals who read these charts for a living and independently verified by three additional experts. In an evaluation of 30 frontier-model configurations (20 scored trials per task), the best configuration reaches only 45.0% mean pass@1; the remainder span 9.0-39.5%. Failures concentrate in visual perception: models can miss nuanced features, misread values along sparsely labeled axes, mishandle projected 3D geometry, and violate domain conventions encoded in the chart. We release all tasks, images, provenance metadata, and evaluation code.","authors":["Suhaas Garre","Chris Mutty","Sushant Mehta","Edwin Chen"],"published":"2026-08-11T08:57:25Z","updated":"2026-08-11T08:57:25Z","abstract_url":"https://arxiv.org/abs/2608.10677v1","html_url":"https://arxiv.org/html/2608.10677v1","pdf_url":"https://arxiv.org/pdf/2608.10677v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10665v1","title":"VERDICT: Training-Free Step-Wise Verification of Multimodal Reasoning via Disagreement-Aware Consensus","abstract":"Multimodal large language models often generate reasoning chains containing subtle errors that lead to incorrect answers. Current verification approaches have notable limitations. Existing approaches either require expensive labelled supervision with inconsistent cross-task performance or aggregate scores from multiple sources by simple aggregations, missing a key insight: when these scores disagree, that disagreement itself carries important information about whether a reasoning step is truly valid or not. We formalise this as a coupled scoring problem among disparate, frozen verifiers, interpretable as a coordination game with a unique closed-form equilibrium where agreement signals valid steps while disagreement reveals instability. Towards this end, we propose a training-free domain-agnostic step-wise verification approach we call VERDICT: VERification via Disagreement-Informed Coupled Thresholding. To our knowledge, VERDICT is the first training-free verifier that makes the structure of cross-modal disagreement explicit and actionable. It computes consensus scores through a closed-form solution, enabling both disagreement-aware filtering and stability-conscious ranking of reasoning steps. Evaluated across six benchmarks, \\method consistently improves over the base model by up to +5.95%, and performs competitively with domain-specific critics that demand extensive supervision, demonstrating that cross-modal agreement provides robust verification signals without task-specific adaptation and Training-Free Verification","authors":["Rohit Sinha","Kunal Tilaganji","Tanuja Ganu","Nagarajan Natarajan","Amit Sharma","Vineeth Balasubramanian"],"published":"2026-08-11T08:46:38Z","updated":"2026-08-11T08:46:38Z","abstract_url":"https://arxiv.org/abs/2608.10665v1","html_url":"https://arxiv.org/html/2608.10665v1","pdf_url":"https://arxiv.org/pdf/2608.10665v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10657v1","title":"Retrieval-Augmented Vision Foundation Models for Robust Leukemia Cell Classification across Multiple Microscopy Datasets","abstract":"Leukemia cell image classification is challenged by real-world domain shifts from acquisition, staining, illumination, and site protocols, causing single-dataset models to generalize poorly in real clinical scenarios. This work presents a robust framework for leukemia classification across multiple heterogeneous datasets using a two-stage pipeline with a pretrained vision foundation model. Stage 1 performs binary classification (leukemia vs. non-leukemia) and is trained using 122,167 single-cell images. Stage 2 is conditionally applied to Stage 1 positives to perform subtype classification into Acute Lymphoblastic Leukemia (ALL) and Acute Myeloid Leukemia (AML), trained using 69,400 single-cell images. Labels are harmonized across five heterogeneous datasets to enable cross-dataset training, and performance is evaluated on a held-out dataset protocol to assess domain-shift generalization. Within this pipeline, three encoders are benchmarked (DinoBloom, pretrained on single-cell images; BiomedCLIP, pretrained on biomedical data; and CLIP as a general-purpose model) under linear probing, Low-Rank Adaptation (LoRA), and a Retrieval-Augmented Classification (RAC) module that retrieves the top-k most similar cell images to provide cytomorphological grounding. The objective is to quantify how much domain-specific pretraining contributes to performance under domain shift, and whether cost-effective adaptation and retrieval can be a viable alternative to expensive domain-specialized pretraining. The held-out protocol additionally serves as a diagnostic tool, revealing when classification performance is attributable to dataset-specific artifacts rather than to cytomorphological features.","authors":["Carlos Zamora","Hiram Zuniga","Ulises Orozco-Rosas","Kenia Picos"],"published":"2026-08-11T08:39:16Z","updated":"2026-08-11T08:39:16Z","abstract_url":"https://arxiv.org/abs/2608.10657v1","html_url":"https://arxiv.org/html/2608.10657v1","pdf_url":"https://arxiv.org/pdf/2608.10657v1.pdf","matched_keywords":["retrieval"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10636v1","title":"DistilVDR: A Compact End-to-End Visual Document Retriever via Dual-Student Distillation","abstract":"Visual document retrieval (VDR) is dominated by multi-billion-parameter models that are slow to index at full corpus scale and expensive to serve. Prior compression routes either train a smaller multi-vector encoder from scratch or distil only the query side; neither yields a compact single-vector retriever end-to-end. We present DistilVDR, a 524M end-to-end VDR system distilled bilaterally from a single 8B vision-language teacher under a pointwise cosine alignment loss. All supervision comes from the frozen teacher's embedding space, which was itself trained with relevance supervision, so the student objective needs no relevance labels, negative sampling, or contrastive term. We match VDR's text-query and image-document input asymmetry with an asymmetric encoder-only student that concentrates visual capacity on the document side and keeps the query side at 70M parameters. We release two variants that share the same encoders and training and differ only in the document encoder's visual-tile budget: DistilVDR-HiRes attains 61.74 average NDCG@5 on ViDoRe v1+v2+v3 (86.9% of the 8B teacher) and leads every reproduced sub-1B baseline on the high-resolution-sensitive v3 benchmark, while DistilVDR-Fast attains 59.98 at a 3 times smaller visual-token budget. Both variants store one million documents in a 15.6 times smaller index than the strongest sub-1B multi-vector baseline and index the corpus an order of magnitude faster. The code is available at https://github.com/Ryenhails/NanoVDR.","authors":["Zhuchenyang Liu","Ziyi Wang","Yao Zhang","Yu Xiao"],"published":"2026-08-11T08:23:39Z","updated":"2026-08-11T08:23:39Z","abstract_url":"https://arxiv.org/abs/2608.10636v1","html_url":"https://arxiv.org/html/2608.10636v1","pdf_url":"https://arxiv.org/pdf/2608.10636v1.pdf","matched_keywords":["retrieval"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10635v1","title":"MedUP: Awakening Unified Understanding and Perception in Medical Vision-Language Models","abstract":"Medical Vision-Language Models (Med-VLMs) excel at verbalizing visual content, yet precise visual perception, segmentation, and grounding remain challenging. Existing approaches either verbalize regions as coordinate strings or rely on external modules that decouple perception from understanding, creating representation gaps for region-language alignment. We present MedUP, a Med-VLM that natively unifies perception and understanding within a shared token space. At its core lies UniMedTok, a region tokenizer that encodes masks as discrete tokens in the LLM vocabulary, enabling the model to seamlessly interleave mask tokens with text. We curate UniMed-Train, a 1.84M-instance corpus spanning text-guided segmentation, region-grounded understanding, medical VQA and CoT-based segmentation, and introduce UniMed-Bench for unified evaluation. Extensive experiments show that MedUP outperforms native, agentic, and dual-decoder Med-VLMs across all tasks while remaining competitive with specialist segmentors, demonstrating the strong potential of unified understanding and perception modeling.","authors":["Yuan Wang","Hualiang Wang","Yixin Chen","Songtao Jiang","Shujian Gao","Jiaming Lin","Siming Fu","Jian Wu","Zuozhu Liu"],"published":"2026-08-11T08:22:13Z","updated":"2026-08-11T08:22:13Z","abstract_url":"https://arxiv.org/abs/2608.10635v1","html_url":"https://arxiv.org/html/2608.10635v1","pdf_url":"https://arxiv.org/pdf/2608.10635v1.pdf","matched_keywords":["agent","representation","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10628v1","title":"InSight-doc: Agentic Visual Perception for Long-Document Understanding","abstract":"Long-document understanding often requires reasoning over many visually rich pages, making inference costly and prone to context rot. In this work, we propose InSight-doc, an agentic visual perception framework that treats visual resolution as an adaptive reasoning-time resource. InSight-doc starts from low resolution and selectively zooms into high-resolution regions for finer evidence, without relying on any external retriever. To train such an agent, we construct an active-perception corpus of 17.9K high-quality SFT examples with region-level zoom-in trajectories, accompanied by 19.2K hard RL examples. Through SFT+RL, InSight-doc-8B improves the baseline by 4.3--16.4 accuracy points over document VQA benchmarks. On long documents, it reduces hallucination by more than 40% and inference latency by 41%--68% while maintaining an accuracy lead. Our code, datasets, and model are released at https://github.com/m-Just/InSight-doc .","authors":["Kaican Li","Weiyan Xie","Lewei Yao","Jiannan Wu","Lanqing Hong","Yongxiang Huang","Nevin L. Zhang"],"published":"2026-08-11T08:15:16Z","updated":"2026-08-11T08:15:16Z","abstract_url":"https://arxiv.org/abs/2608.10628v1","html_url":"https://arxiv.org/html/2608.10628v1","pdf_url":"https://arxiv.org/pdf/2608.10628v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10602v1","title":"Gaussian Sculpting: End-to-End Controllable Surface Reconstruction via Field Optimization","abstract":"3D Gaussian Splatting (3DGS) has recently enabled real-time novel view synthesis with impressive quality. However, it struggles to recover accurate surfaces under limited viewpoints and due to the inherent irregularity of Gaussian primitives. The resulting geometric errors are notoriously difficult to correct manually. To address these issues, we propose Gaussian Sculpting, a fully differentiable end-to-end framework for high-quality surface reconstruction. Our key insight is to anchor Gaussians onto an evolving differentiable surface, allowing them to guide signed distance field (SDF) optimization instead of extracting the surface only during post-processing. To enable stable gradient isolation during joint optimization, we design a bi-level training strategy in which the outer loop optimizes the geometry represented by the SDF, while the inner loop updates the Gaussians with the geometry fixed. We further impose constraints on Gaussian parameters to ensure consistency with the underlying surface, thereby improving both geometric and appearance fidelity during optimization. In addition, we introduce a multi-resolution subdivision scheme based on octree-like partitioning to preserve fine details while reducing memory consumption. Experiments on object-level scenes demonstrate that our method effectively removes redundant surfaces, recovers missing structures caused by limited viewpoints, and achieves strong reconstruction quality even at relatively low resolutions.","authors":["Ke Jiaxin","Juncheng Liu","Yi Wang","Zhouhui Lian","Bin Liu","Shengfa Wang","Xiangjia He"],"published":"2026-08-11T07:42:24Z","updated":"2026-08-11T07:42:24Z","abstract_url":"https://arxiv.org/abs/2608.10602v1","html_url":"https://arxiv.org/html/2608.10602v1","pdf_url":"https://arxiv.org/pdf/2608.10602v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10600v1","title":"BooST: Bridging Semantics and Motions for Efficient Skill Transfer","abstract":"Skill abstraction---the process of learning reusable and temporally extended behaviors---has emerged as a key paradigm for improving sample efficiency and generalization in robot learning. For efficient skill transfer to real robots, learned skills must generalize across tasks and domains, remain robust to visual and dynamic perturbations, and be efficient enough for practical deployment. However, existing methods typically satisfy only a subset of these properties, as they capture either high-level semantic intent (what) or low-level motion dynamics (how). This incomplete skill transfer yields weak priors for policy learning, thereby demanding substantial in-domain data for downstream adaptation. To address these challenges, we introduce BooST, a two-stage framework that explicitly bridges semantics and motions to satisfy all three desiderata. BooST first leverages a cross-modal VQ-VAE to capture both semantic intent and motion dynamics, yielding a unified skill representation. It then distills this representation into a lightweight policy for efficient downstream adaptation to new tasks. Extensive experiments across simulation and real-robot settings demonstrate that BooST achieves superior few-shot adaptation, cross-domain skill transfer, and robustness to dynamic visual distractors, while maintaining a lightweight yet expressive design suitable for real-world deployment.","authors":["Jusuk Lee","Daesol Cho","Jonghun Shin","Seungyeon Yoo","Jonghae Park","Taekbeom Lee","H. Jin Kim"],"published":"2026-08-11T07:35:12Z","updated":"2026-08-11T07:35:12Z","abstract_url":"https://arxiv.org/abs/2608.10600v1","html_url":"https://arxiv.org/html/2608.10600v1","pdf_url":"https://arxiv.org/pdf/2608.10600v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10566v1","title":"Iterative Erasure Count Is Not an Affine-Invariant Concept Dimension","abstract":"How many directions does a neural representation use to encode a concept? A common answer repeatedly erases probe directions and reports the stopping count or cumulative removed rank. We show that both quantities can change under an information-preserving invertible reparameterization, so neither is intrinsically a concept dimension. We distinguish model-defined population quantities (generating dimension, sufficient linear dimension, and minimum guarding rank) from procedure-defined quantities such as stopping count and cumulative edit rank. In a population Gaussian construction, an invertible shear preserves the prediction problem and all three quantities, yet changes the cumulative Euclidean erasure count from one to two. The separation holds for Moore--Penrose ordinary least squares and every finite nonnegative ridge weight. For a two-output full-QR procedure matching our motivating video analysis, cumulative edit rank similarly changes from two to the ambient dimension four. Conversely, the complete cumulative metric-QR trajectory is affine-equivariant when its positive-definite metric, probe, regularizer, and tie-breaking are transported consistently; exact covariance is one corollary, not a canonical semantic metric. In a known-rank finite-sample Adam/QR calibration, identity mixing stops after one accepted update in all 20 large-sample runs, whereas each tested shear $a\\in\\{.5,.75,1,1.25,2\\}$ accepts at least two updates in all 20 runs. Controlled reparameterizations of frozen V-JEPA2 features preserve rank-zero predictions yet alter later Euclidean trajectories under practical optimization. These visual contact experiments are stress tests, not estimates of contact dimension. Iterative erasure therefore returns a procedure-relative estimand jointly determined by representation geometry and the full measurement procedure, not a semantic dimension by itself.","authors":["Tingan Jin","Shuhang Dong","Haosong Li","Chung-Hsien Chou"],"published":"2026-08-11T06:53:50Z","updated":"2026-08-11T06:53:50Z","abstract_url":"https://arxiv.org/abs/2608.10566v1","html_url":"https://arxiv.org/html/2608.10566v1","pdf_url":"https://arxiv.org/pdf/2608.10566v1.pdf","matched_keywords":["video","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10524v1","title":"Rethinking Text-Based Image Retrieval in Specific Domain","abstract":"Driven by the rapid advancement of vision-language representation learning, Text-based Image Retrieval (TBIR) has made notable progress. However, existing benchmarks are predominantly constructed on an exclusive single-match assumption between query and images. While effective in general scenarios, this assumption fails to reflect practical system performance in specific domains (e.g., surveillance), where a single query often corresponds to multiple relevant candidate images. To address this limitation, we design a Domain-Specific Multi-Match Text-based Image Retrieval (DSMM-TBIR) data engine. Leveraging this engine, we construct Security Multi-Match TBIR (SecMM-TBIR), a benchmark comprising 50k surveillance images with 200 comprehensive queries. Furthermore, we observe that vanilla contrastive learning in specific domains suffers from severe false negatives, forcing the model to push apart semantically similar pairs and thus degrading retrieval performance. We propose the Semantic-Aware Fine-Tuning (SAFT) framework to address semantic compression in specific domains, which incorporates Semantic-Aware Soft-Label Supervision (SASS) and Intra-modal Structural Distillation (ISD) to establish a promising paradigm for domain-specific TBIR tasks. Experiments across diverse CLIP-like models demonstrate that SAFT yields an average mAP@20 gain of 7.8 points on SecMM-TBIR over standard image-text contrastive (ITC) fine-tuning, while also improving general-domain performance. The entire benchmark will be released to facilitate further research.","authors":["Jingyang Tan","Sheng Yang","Yuanpeng Chen","Jian Wang","Nianjin Ye","Chen Xing","Lanpeng Jia"],"published":"2026-08-11T06:00:27Z","updated":"2026-08-11T06:00:27Z","abstract_url":"https://arxiv.org/abs/2608.10524v1","html_url":"https://arxiv.org/html/2608.10524v1","pdf_url":"https://arxiv.org/pdf/2608.10524v1.pdf","matched_keywords":["retrieval","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10522v1","title":"Unlocking the Power of Medical Tabular Data via Semantic-Aware Multimodal Pre-training","abstract":"While vision-language models dominate medical representation learning, unstructured text lacks the dense, quantitative diagnostic phenotypes inherent in structured clinical tables. However, existing multimodal pre-training methods underutilize this potential due to semantic-agnostic designs that treat tabular inputs as flat vectors and employ unstable continuous regression objectives. To overcome this, we propose a novel semantic-aware framework explicitly modeling the intrinsic two-dimensional structure of tabular data. First, addressing the inter-feature hierarchy of varying diagnostic importance, we introduce Importance-Aware Adaptive Masking to construct a label-free curriculum prioritizing salient features. Second, addressing the intra-feature continuity-discreteness duality, we propose a Soft-Label Discretized Module that replaces unstable numerical regression with stable distribution matching, thereby mathematically preserving ordinal relationships. Extensive experiments across large-scale dermatology (SLICE-3D, HOP) and ophthalmology (EyePACS) datasets establish a new state-of-the-art (SOTA), demonstrating exceptional robustness and cross-domain generalizability.","authors":["Yingsheng Liu","Haiming Li","Jingmin Zhu","Jiajun Sun","Victoria Mar","Monika Janda","H. Peter Soyer","Zongyuan Ge","Zhen Yu"],"published":"2026-08-11T05:57:09Z","updated":"2026-08-11T05:57:09Z","abstract_url":"https://arxiv.org/abs/2608.10522v1","html_url":"https://arxiv.org/html/2608.10522v1","pdf_url":"https://arxiv.org/pdf/2608.10522v1.pdf","matched_keywords":["3d","representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10519v1","title":"SparSTAR: Sparse Attention for SpaceTime AutoRegressive Video Synthesis","abstract":"InfinityStar extends visual autoregressive generation to video through a sequence of image and clip pyramids. Its changing scale and cross-clip context, however, leave late-scale attention costly and make sparse patterns reused from diffusion or image VAR models unreliable. We introduce SparSTAR, a training-free block-sparse attention method tailored to this setting. At each expensive scale and attention head, SparSTAR scores contiguous key blocks from the current query and key activations, retains required conditioning context, and executes the selected blocks through a forward-only sparse path. We analyze cross-scale consistency within a clip, pattern persistence across clip boundaries, and quality degradation as reuse spans increasingly distant scales. Across these analyses, important key blocks shift, showing that recomputing block selection at each target scale is more reliable than reusing a transferred mask. On 720p text-to-video and image-to-video generation, SparSTAR preserves every token and refinement scale while providing about a 1.6x end-to-end speedup and maintaining VBench and paired-output reconstruction fidelity close to dense InfinityStar.","authors":["Jongbeom Lee","Hyunwoo Yu","Jincheol Yang","Jaemin Choi","Suk-Ju Kang"],"published":"2026-08-11T05:46:18Z","updated":"2026-08-11T05:46:18Z","abstract_url":"https://arxiv.org/abs/2608.10519v1","html_url":"https://arxiv.org/html/2608.10519v1","pdf_url":"https://arxiv.org/pdf/2608.10519v1.pdf","matched_keywords":["video","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10513v1","title":"SafeCap: Improving LVLM Safety with Image Captioning Reinforcement Learning","abstract":"Large vision-language models (LVLMs) remain vulnerable to jailbreak attacks that exploit visual inputs to bypass safety alignment inherited from their language backbones. We propose SafeCap, a reinforcement-learning framework that aligns LVLMs through learned self-captioning. SafeCap trains a policy model to first generate a safety-relevant image caption and then produce a final answer; the caption is further optimized by whether it enables a frozen LLM to reach a safety-aligned decision. This caption-mediated objective encourages the policy to expose visual cues relevant to safe response generation rather than relying solely on direct refusal supervision. Across five multimodal safety benchmarks and six vision-utility benchmarks, SafeCap substantially improves aggregate safety performance under its intended DirectCap protocol, with gains of 3.7-19.0 points in safety average across four model settings while maintaining comparable or improved vision utility. Under controlled comparisons on matched backbones and data, SafeCap outperforms safety SFT, DPO, and SafeGRPO, demonstrating the effectiveness of caption-mediated reinforcement learning for multimodal safety alignment.","authors":["Caoyuan Ma","Wenpu Liu","Weichu Xie","Tian Gu","Shilei Zhao","Lingxi Min","Shuai Dong","Yuqi Xu","Ji Zhao","Ziyue Wang","Wenzheng Chang","Taiqiang Wu","Yongfu Zhu","Wenqi Shao","Yinqiang Zheng"],"published":"2026-08-11T05:37:59Z","updated":"2026-08-11T05:37:59Z","abstract_url":"https://arxiv.org/abs/2608.10513v1","html_url":"https://arxiv.org/html/2608.10513v1","pdf_url":"https://arxiv.org/pdf/2608.10513v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10500v1","title":"DSAR: Dual-Stream Autoregressive Modeling of Temporal Cloth Dynamics for Photorealistic Animatable Avatars","abstract":"Creating photorealistic and temporally coherent animatable human avatars from RGB videos remains challenging. Current methods struggle to capture realistic cloth dynamics, producing over-smoothed appearance or severe artifacts on out-of-distribution poses. This limitation stems from a fundamental oversight: existing approaches neglect the temporal causality inherent in cloth physics, where current states emerge from previous states through temporal evolution rather than instantaneous skeletal configurations alone. Without explicit modeling of this causal structure, networks learn pose-appearance correlations instead of motion evolution, leading to poor generalization. We introduce a dual-stream autoregressive framework that explicitly models both observable geometric information and implicit internal state. The geometric stream propagates surface displacement from the previous frame, while the state stream fuses current features with historical states retrieved from a memory bank. Motion-adaptive aggregation handles spatially-varying dynamics, and adaptive regularization balances smoothness with flexibility. Experiments on challenging datasets demonstrate significant improvements in rendering quality, temporal consistency, and generalization to motion patterns beyond training distributions, validating that dual-stream temporal modeling enables realistic cloth dynamics.","authors":["Haozhong Xiong","Yao Yu","Yu Zhou","Sidan Du"],"published":"2026-08-11T05:19:21Z","updated":"2026-08-11T05:19:21Z","abstract_url":"https://arxiv.org/abs/2608.10500v1","html_url":"https://arxiv.org/html/2608.10500v1","pdf_url":"https://arxiv.org/pdf/2608.10500v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10497v1","title":"SapiensID 2.0: Aligning Human Recognition Foundation Models with Human Perception","abstract":"While foundation models have significantly advanced human recognition across diverse modalities, they predominantly rely on static, geometric feature extraction. This approach fundamentally diverges from human perception. Consequently, current models often suffer from \"semantic blindness,\" overfitting to transient noise while failing to leverage invariant soft biometrics, and struggle to capture temporal motion signatures. To bridge this gap, we propose SapiensID 2.0, a human recognition framework enriched with both semantic and temporal awareness. To overcome the lack of soft-biometric annotations, we transfer zero-shot semantic knowledge from Multimodal Large Language Models (MLLMs) into a discriminative embedding space. We resolve the dimensional mismatch between these spaces using Invariant Trait Alignment (ITA) to distill core persistent traits, and Transient Noise Disentanglement (TND) to decouple artifacts like clothing. Furthermore, we design a Kinematic Semantic Attention Head (K-SAH) that extends spatial attention across temporal windows. By tracking semantic patches over time, K-SAH captures rich kinematic signatures without requiring large-scale video datasets. Extensive experiments demonstrate that SapiensID 2.0 achieves state-of-the-art performance across image- and video-based person re-identification and gait recognition, while maintaining robust face recognition capabilities.","authors":["Yiyang Su","Jie Zhu","Feng Liu","Anil K. Jain","Xiaoming Liu"],"published":"2026-08-11T05:13:05Z","updated":"2026-08-11T05:13:05Z","abstract_url":"https://arxiv.org/abs/2608.10497v1","html_url":"https://arxiv.org/html/2608.10497v1","pdf_url":"https://arxiv.org/pdf/2608.10497v1.pdf","matched_keywords":["video","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10489v1","title":"When Vision Becomes Text: Visual Token Pruning via Cross-Modal Residual Guidance in VLMs","abstract":"Abundant visual information strengthens vision-language model (VLM) perception, yet massive visual tokens raise inference costs. Existing visual token pruning methods rely on similarity-based guidance, which exploits pairwise text-vision and vision-vision token correlations for compression. However, such methods only capture local layer-level signals and overlook the whole inference process in VLM. In this paper, we revisit VLM inference and present a new efficient guidance scheme that complements similarity-based guidance. In particular, we identify a key observation: as LLM layers deepen, text tokens continuously aggregate visual information via self-attention and progressively absorb partial visual content into textual representations. To quantify this phenomenon, we propose Cross Modal Absorption (CMA) from a geometric representation perspective to measure how much visual information is absorbed by text, revealing that more visual tokens in deeper layers can be approximately explained by the text subspace. We accordingly propose Cross Modal Residual (CMR). It projects visual tokens onto the text subspace via Tikhonov regularized least squares and exploits reconstruction residuals to quantify visual information that cannot be explained by text. Finally, based on CMR, we present SIEVE, a training-free visual token compression method that combines CMR, text-attention relevance, and residual-space diversity to retain task-relevant and complementary tokens. Experiments on diverse VLM architectures verify the effectiveness of SIEVE. For instance, on LLaVA-NeXT-7B, SIEVE keeps only $11.1\\%$ of visual tokens while preserving $97.5\\%$ of the original average performance, achieving $3.62\\times$ prefill speedup, $2.49\\times$ end-to-end speedup, and a $6.02\\times$ KV-cache reduction.","authors":["Congyang Ou","Ruike Song","Yang Zhou","Libo Sun","Haokui Zhang","Zhenbo Luo"],"published":"2026-08-11T05:04:33Z","updated":"2026-08-11T05:04:33Z","abstract_url":"https://arxiv.org/abs/2608.10489v1","html_url":"https://arxiv.org/html/2608.10489v1","pdf_url":"https://arxiv.org/pdf/2608.10489v1.pdf","matched_keywords":["representation","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"}],"favorites":[],"latest":{"generated_at_utc":"2026-08-12T03:20:05+00:00","category":"cs.CV","keywords":["video","retrieval","3d","agent","representation","instance","multimodal","diffusion"],"fetch_window_hours":72,"daily_window_hours":30,"match_count":66,"new_or_recent_papers":[{"id":"2608.11205v1","title":"AdvFD: Boosting Visual Generation via Adversarial Fr'echet Distance Loss","abstract":"Fréchet distance has recently emerged as an effective distribution-level objective for generator post-training, complementing the conventional sample-level diffusion and flow-matching losses. However, directly optimizing Fréchet objectives can cause Fréchet hacking. The target metrics keep improving, but visual quality and Fréchet alignment in other feature spaces may stagnate or deteriorate. We attribute this failure to the static pretrained feature spaces used by existing Fréchet losses. These feature spaces provide incomplete and fixed views of the differences between real and generated distributions. To address this limitation, we propose Adversarial Fréchet Distance (AdvFD), which complements the static representation targets in FD-Loss with a calibrated adversarially learned representation. AdvFD augments the original static Fréchet objective with a learnable representation that adversarially maximizes the Fréchet discrepancy between real and generated samples, while the generator minimizes the same discrepancy in the resulting adaptive feature space. To prevent the adversarial representation from trivially increasing the objective through feature amplification, we further introduce real-feature whitening, which normalizes its scale and covariance geometry and stabilizes the min--max optimization. Extensive experiments show that AdvFD consistently improves one-step generator post-training across both JiT and pMF backbones and across different model scales.","authors":["Mingju Gao","Jingkai Zhou","Kun Gai","Changqian Yu","Hao Tang"],"published":"2026-08-11T17:59:56Z","updated":"2026-08-11T17:59:56Z","abstract_url":"https://arxiv.org/abs/2608.11205v1","html_url":"https://arxiv.org/html/2608.11205v1","pdf_url":"https://arxiv.org/pdf/2608.11205v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"html","source_text_chars":83290,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation, diffusion 相关；摘要显示其主要贡献为：Fréchet distance has recently emerged as an effective distribution-level objective for generator post-training, complementing the conventional sample-level diffusion and flow-matching losses. However, directly optimizing Fréchet objectives can cause Fréchet h...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:06+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11204v1","title":"Surgical WAM: A World-Action Model for Data-Efficient Surgical Robot Learning","abstract":"Learning reliable surgical manipulation policies is bottlenecked by the scarcity of action-labeled demonstrations: teleoperated surgical robot (e.g., dVRK) trajectories with synchronized kinematics are costly to collect, while surgical tasks demand precise contact handling, long-horizon reasoning, and bimanual coordination. Endoscopic video is comparatively inexpensive and abundant relative to synchronized video--kinematics trajectories, and a natural way to exploit it is to learn world models of surgical scenes. However, existing surgical world models use video primarily for simulation or policy evaluation, and rarely translate the learned dynamics into closed-loop control. This gap raises our central question: under a fixed budget of action-labeled demonstrations, does action-free video pretraining improve closed-loop surgical manipulation? To answer it, we introduce the Surgical World-Action Model (Surgical WAM), a unified generative model built on Cosmos Policy that jointly predicts future endoscopic observations and executable surgical robot action chunks. Surgical WAM first learns surgical visual dynamics from action-free video and is then fine-tuned on the fixed action-labeled budget; at deployment, it acts as a closed-loop, receding-horizon controller that executes a short prefix of each predicted action chunk and replans from the resulting observation. On a suite of four simulated surgical manipulation tasks, video pretraining improves the average success rate from 63.5% to 77.8%, including an absolute gain of 20 percentage points on PegTransfer, with the largest improvements on contact-rich and bimanual tasks. These results demonstrate that action-free video provides transferable visual dynamics priors for learning surgical robot control with limited action supervision, positioning data-efficient video pretraining as a practical path toward scaling up surgical robot learning.","authors":["Wenrui Bao","Tianyun Jiang","Zhiben Chen","Ser-Nam Lim","Peter D. Peng","Yuzhang Shang"],"published":"2026-08-11T17:59:13Z","updated":"2026-08-11T17:59:13Z","abstract_url":"https://arxiv.org/abs/2608.11204v1","html_url":"https://arxiv.org/html/2608.11204v1","pdf_url":"https://arxiv.org/pdf/2608.11204v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":50575,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Learning reliable surgical manipulation policies is bottlenecked by the scarcity of action-labeled demonstrations: teleoperated surgical robot (e.g., dVRK) trajectories with synchronized kinematics are costly to collect, while surgical tasks demand precise co...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:06+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11203v1","title":"Capturing Uncertainty in Human Motion for Representation Learning in Soccer","abstract":"This paper presents a self-supervised representation learning framework for understanding 3D skeleton-based human motion in soccer, using future motion prediction as the learning objective. Since human motion is inherently uncertain, accounting for multiple plausible futures is essential for capturing the underlying motion dynamics and learning effective representations. To this end, we introduce a conditioning module for motion prediction that models a probabilistic distribution over discretized future motions in 3D Euclidean space, learning multimodality with explicit supervision from future trajectories. Experiments on large-scale soccer player tracking data show that our approach substantially improves motion prediction accuracy. Moreover, the learned representations effectively transfer to multiple soccer downstream applications, demonstrating strong cross-task generalization.","authors":["Yizhou Xu","Lars Bretzner","Tiesheng Wang","Atsuto Maki"],"published":"2026-08-11T17:59:10Z","updated":"2026-08-11T17:59:10Z","abstract_url":"https://arxiv.org/abs/2608.11203v1","html_url":"https://arxiv.org/html/2608.11203v1","pdf_url":"https://arxiv.org/pdf/2608.11203v1.pdf","matched_keywords":["3d","representation","multimodal"],"source_used":"html","source_text_chars":114098,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, representation, multimodal 相关；摘要显示其主要贡献为：This paper presents a self-supervised representation learning framework for understanding 3D skeleton-based human motion in soccer, using future motion prediction as the learning objective. Since human motion is inherently uncertain, accounting for multiple p...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:06+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11201v1","title":"VidForensics-M1: Meta-Detection Reinforcement Learning with Verifiable Temporal Grounding for AI-Generated Video Forensics","abstract":"Recent advances in video generation models have significantly improved the realism of synthetic videos, blurring the boundary between generated and authentic content and raising concerns about misinformation. Existing MLLM-based detectors mainly rely on supervised fine-tuning or label-level reinforcement learning, where coarse supervision limits generalization to unseen scenarios and emerging video generators. To overcome these limitations, we are the first to introduce \\textbf{meta-detection} into AI-generated video detection, enabling reliable forgery detection by jointly optimizing predicted labels and supporting evidence within reinforcement learning. This paradigm requires reliable evidence signals and effective mechanisms to integrate them into label-level optimization. Textual rationales provide semantic descriptions of forgery artifacts, but their generation and verification depend on external models, making supervision vulnerable to hallucinations and semantic biases. In contrast, temporal grounding provides more objective and verifiable evidence, as manipulated intervals can be precisely controlled during forgery construction. Based on this insight, we propose an automated data construction pipeline that generates paired real-fake videos by replacing temporal segments with boundary-frame-conditioned video generation models. Furthermore, we introduce \\textbf{Evidence-Guided Reward Redistribution}, which performs evidence-aware credit assignment by redistributing rewards among label-correct responses according to evidence quality. This preserves reliable label supervision while encouraging detectors to acquire fine-grained and verifiable forgery localization capabilities. Extensive experiments demonstrate that \\textbf{VidForensics-M1} effectively leverages verifiable temporal evidence to achieve robust and generalizable AI-generated video detection.","authors":["Bowei Liu","Zheng Lu","Yuhan Bian","Xinchen Zhang","Xingming Shui","Yuesheng Huang","Xuhuan Li","Zihao Liu","Yifan Yang","Jun Zhou","Xiu Li"],"published":"2026-08-11T17:58:10Z","updated":"2026-08-11T17:58:10Z","abstract_url":"https://arxiv.org/abs/2608.11201v1","html_url":"https://arxiv.org/html/2608.11201v1","pdf_url":"https://arxiv.org/pdf/2608.11201v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":77817,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Recent advances in video generation models have significantly improved the realism of synthetic videos, blurring the boundary between generated and authentic content and raising concerns about misinformation. Existing MLLM-based detectors mainly rely on super...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:07+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11191v1","title":"Test-Time Self-Evolving GUI Visual Grounding via Reflection-Guided On-Policy Self-Distillation","abstract":"GUI Visual Grounding is a fundamental capability for GUI agents. Existing models typically freeze their parameters after deployment, limiting their ability to adapt to unseen interfaces. Although recent methods attempt to adapt models via test-time reinforcement learning, they cannot reflect upon failed exploration. To overcome this, we propose a Test-Time Self-Evolving framework that enables models to improve after deployment without human-annotated ground truth. It constructs a closed-loop of Exploration, Evaluation, Reflection, and Internalization. Specifically, the agent first explores unseen interfaces by predicting grounding coordinates for given instructions. To evaluate these explorations, we introduce an MLLM-based Reflector to assess the generated results and provide the corresponding reasoning reflections. To internalize reflection knowledge into the model weights, we propose Reflection-Guided On-Policy Self-Distillation, which translates high-level reasoning into dense token-level supervision via a conditioned self-teacher. Furthermore, we design a Contrastive Calibration method to prevent incorrect auto-regressive prefixes from corrupting the supervisory signals during failed explorations. Extensive experiments across six benchmarks demonstrate our framework's effectiveness, achieving an average accuracy improvement of 7.4% over the base model. To the best of our knowledge, this is the first work to successfully exploit on-policy self-distillation for test-time adaptation in GUI visual grounding. By filling the gap in post-deployment adaptation, our framework completes the self-evolving capability of GUI agents. The code will be released.","authors":["Shiyu Xuan","Zechao Li"],"published":"2026-08-11T17:50:25Z","updated":"2026-08-11T17:50:25Z","abstract_url":"https://arxiv.org/abs/2608.11191v1","html_url":"https://arxiv.org/html/2608.11191v1","pdf_url":"https://arxiv.org/pdf/2608.11191v1.pdf","matched_keywords":["agent"],"source_used":"html","source_text_chars":56602,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 agent 相关；摘要显示其主要贡献为：GUI Visual Grounding is a fundamental capability for GUI agents. Existing models typically freeze their parameters after deployment, limiting their ability to adapt to unseen interfaces. Although recent methods attempt to adapt models via test-time reinforcem...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:07+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11167v1","title":"MultiModal Code-Switching: Interleaving Visual Objects into Language for Explicit Object-Level Alignment","abstract":"Existing Multimodal Large Language Models (MLLMs) predominantly rely on image-text pairs for modality alignment pretraining, mapping global image representations to long textual descriptions. However, this image-level alignment suffers from referential ambiguity: models struggle to infer the correspondences between multiple visual objects and textual entities from the global representation, leading to data inefficiency and suboptimal semantic grounding. To address this, we propose MultiModal Code-Switching (MMCS), a novel pretraining paradigm that provides explicit object-level supervision. Inspired by the linguistic phenomenon of code-switching, MMCS interleaves vision and language by replacing textual entities with their corresponding visual objects, enforcing local vision-language grounding. We further develop a scalable data synthesis pipeline to generate a pretraining dataset of 773K samples with accurate object-entity correspondences. Experiments show that MMCS is highly data-efficient: with only 50K samples, it matches or surpasses models trained on 600K image-text pairs. Furthermore, MMCS consistently improves visual grounding and perception capabilities across varying model scales.","authors":["Changhao Xiang","Shangyu Xing","Zhen Wu","Jianbing Zhang","Xinyu Dai"],"published":"2026-08-11T17:28:52Z","updated":"2026-08-11T17:28:52Z","abstract_url":"https://arxiv.org/abs/2608.11167v1","html_url":"https://arxiv.org/html/2608.11167v1","pdf_url":"https://arxiv.org/pdf/2608.11167v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"html","source_text_chars":89399,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation, multimodal 相关；摘要显示其主要贡献为：Existing Multimodal Large Language Models (MLLMs) predominantly rely on image-text pairs for modality alignment pretraining, mapping global image representations to long textual descriptions. However, this image-level alignment suffers from referential ambigu...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:07+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11150v1","title":"CausalSplat: Towards Comprehensive Hierarchical Reasoning in 3D Gaussian Splatting","abstract":"While 3D Gaussian Splatting (3DGS) has advanced open vocabulary scene understanding, existing methods remain confined to explicit queries. They struggle to interpret implicit intents, complex spatial constraints, and commonsense reasoning required for practical embodied interactions. To address this gap, we introduce the task of reasoning 3D Gaussian segmentation and construct two benchmarks, Causal-LERF and Causal-ScanNet. These benchmarks systematically evaluate commonsense, spatial, affordance, and counterfactual reasoning. Evaluations reveal that current state of the art methods perform poorly on these reasoning challenges. Therefore, we propose CausalSplat, a framework that integrates vision-language models with 3D scene graphs to disentangle explicit structural perception from implicit logical inference. Extensive experiments demonstrate that CausalSplat achieves state of the art performance on our reasoning benchmarks while showing strong generalizability on standard referring and open vocabulary 3D segmentation tasks. Project Page: https://jiayuding031020.github.io/CausalSplat","authors":["Jiayu Ding","Meilu Song","Yun Chen","Wei Gao","Ge Li"],"published":"2026-08-11T17:09:49Z","updated":"2026-08-11T17:09:49Z","abstract_url":"https://arxiv.org/abs/2608.11150v1","html_url":"https://arxiv.org/html/2608.11150v1","pdf_url":"https://arxiv.org/pdf/2608.11150v1.pdf","matched_keywords":["3d"],"source_used":"html","source_text_chars":63995,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d 相关；摘要显示其主要贡献为：While 3D Gaussian Splatting (3DGS) has advanced open vocabulary scene understanding, existing methods remain confined to explicit queries. They struggle to interpret implicit intents, complex spatial constraints, and commonsense reasoning required for practic...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:07+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11149v1","title":"PRMU: A Corpus-Free Benchmark for Person-Centric Knowledge Unlearning in Multimodal Large Language Models","abstract":"Multimodal large language models (MLLMs) have demonstrated remarkable capabilities in storing and recalling rich person-related knowledge, raising increasing concerns about reliable knowledge removal. However, existing machine unlearning approaches for MLLMs typically assume access to original forget and retain corpora, which are often unavailable in realistic deletion scenarios. To address this limitation, we introduce PRMU, a benchmark for evaluating corpus-free multimodal unlearning under realistic person-centric deletion requests. PRMU focuses on naturally acquired person-related knowledge and evaluates whether models can remove target knowledge while preserving related knowledge through diverse textual and visual probes, including adversarial evaluation and fine-grained locality analysis. To facilitate research in this setting, we further introduce Similarity-Gated Projection Editing (SGPE), a lightweight corpus-free unlearning baseline with knowledge displacement, protected parameter-space editing, and locality-aware multimodal control. Extensive experiments on representative MLLMs reveal that existing unlearning methods often suffer from unfavorable forgetting-locality trade-offs, with significant locality degradation under aggressive forgetting settings, and remain vulnerable to multimodal knowledge reactivation. Meanwhile, SGPE provides a competitive trade-off between target forgetting, locality preservation, and general multimodal utility. We hope PRMU can facilitate future research toward realistic and scalable multimodal machine unlearning. Code and dataset will be released at https://github.com/2231122/PRMU.","authors":["Huafeng Chen","Yueming Lyu","Ziyuan Chen","Wenda Tan","Chenyang Si","Liucheng Guo","Caifeng Shan"],"published":"2026-08-11T17:09:28Z","updated":"2026-08-11T17:09:28Z","abstract_url":"https://arxiv.org/abs/2608.11149v1","html_url":"https://arxiv.org/html/2608.11149v1","pdf_url":"https://arxiv.org/pdf/2608.11149v1.pdf","matched_keywords":["multimodal"],"source_used":"html","source_text_chars":50830,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 multimodal 相关；摘要显示其主要贡献为：Multimodal large language models (MLLMs) have demonstrated remarkable capabilities in storing and recalling rich person-related knowledge, raising increasing concerns about reliable knowledge removal. However, existing machine unlearning approaches for MLLMs...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:07+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11142v1","title":"SAR2Agri: Learning SAR Intensity Representations for Agricultural Monitoring","abstract":"Agricultural monitoring faces unique challenges, arising from the landscape's complex temporal, phenological, and climate dynamics, yet monitoring them is critical for ensuring food security. Synthetic Aperture Radar (SAR) satellites offer all-weather day-night imaging capability supporting key monitoring tasks including crop type mapping, yield prediction and phenological event detection. Existing multimodal remote sensing foundation models including TerraMind and CopernicusFM learn SAR representations by grounding them in optical imagery using joint encoding and contrastive learning techniques, while SAR-specific foundation models such as SAR-JEPA, SARMAE, and SAR-W-MixMAE primarily focus on target detection, flood mapping, and land cover classification applications. Recent work has introduced phenology inspired temporal pretext tasks with optical imagery which has shown strong performance on agricultural downstream tasks. In this work, we propose the first self-supervised learning pipeline focused on using only SAR intensity imagery for agricultural applications. We improve the temporal pretext tasks through masking and curriculum learning to enhance the pretraining pipeline's ability to capture phenological features from SAR. On the SICKLE benchmark, our final model achieves 84.9% IoU on crop type mapping, outperforming optical baselines (by 15.3 pt) and existing SAR baselines (by 2.2 pt), demonstrating the effectiveness of our proposed pipeline for pretraining SAR intensity encoders for agricultural monitoring.","authors":["Moti Rattan Gupta","Anupam Sobti"],"published":"2026-08-11T17:01:26Z","updated":"2026-08-11T17:01:26Z","abstract_url":"https://arxiv.org/abs/2608.11142v1","html_url":"https://arxiv.org/html/2608.11142v1","pdf_url":"https://arxiv.org/pdf/2608.11142v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"html","source_text_chars":61351,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation, multimodal 相关；摘要显示其主要贡献为：Agricultural monitoring faces unique challenges, arising from the landscape's complex temporal, phenological, and climate dynamics, yet monitoring them is critical for ensuring food security. Synthetic Aperture Radar (SAR) satellites offer all-weather day-nig...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:07+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11123v1","title":"AlbumentationsX: One Augmentation Pipeline for Images and Related Annotations","abstract":"Augmentation can corrupt a training example when an image and its annotations receive different random changes. A crop must use the same coordinates for the image, mask, boxes, keypoints, stereo views, video frames, or volume. Code paths that choose these values separately can silently misalign the data. AlbumentationsX keeps the transform list, probabilities, annotation settings, and random seed in one Compose object. Each call chooses random values once and applies them to every supported part of the training example. The library keeps each object's mask, box, and label together and lets projects add their own transforms. It can also save the pipeline definition, show what happened in one call, and run that call again. The examples place Compose after files have been decoded into arrays and before PyTorch groups examples into a batch. AlbumentationsX executes the declared transforms. Practitioners still decide whether a flip, crop, color change, or other operation preserves the correct label for their task.","authors":["Vladimir Iglovikov"],"published":"2026-08-11T16:34:47Z","updated":"2026-08-11T16:34:47Z","abstract_url":"https://arxiv.org/abs/2608.11123v1","html_url":"https://arxiv.org/html/2608.11123v1","pdf_url":"https://arxiv.org/pdf/2608.11123v1.pdf","matched_keywords":["video"],"source_used":"html","source_text_chars":23720,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video 相关；摘要显示其主要贡献为：Augmentation can corrupt a training example when an image and its annotations receive different random changes. A crop must use the same coordinates for the image, mask, boxes, keypoints, stereo views, video frames, or volume. Code paths that choose these val...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:08+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11077v1","title":"Learning Gaussian Structure: Intervention-Guided Density Control for Feed-Forward Driving Reconstruction","abstract":"Feed-forward Gaussian reconstruction has recently emerged as an efficient approach for driving scene reconstruction. However, prevailing LiDAR-based methods preserve the initial correspondence between observed points and Gaussian primitives, treating the initialized primitive set as the final representation. Unlike optimization-based 3DGS, these methods cannot accumulate gradients during training to determine how the scenes representation should be densified. Meanwhile, the shared sparse backbone only fuses observations from different timestamps implicitly, without explicitly aggregating cross-time evidence for individual primitives. In this paper, we present Learning Gaussian Structure (LGS), a framework that enhances both Gaussian structure and primitive attributes. Our key observation is that changes in local gradient responses induced by a prune or add intervention reveal whether the corresponding structural adjustment benefits reconstruction. Based on this observation, our Gaussian Densify Policy learns a Densify Map comprising Prune and Addition Scores from controlled interventions, and directly adjusts the Gaussian structure during inference. We further develop a compact Cross-Time Point Query that explicitly retrieves and aggregates neighboring features from Gaussian primitives at other timestamps for reliable attribute prediction. Extensive experiments on the Waymo Open Dataset and PandaSet demonstrate that LGS consistently outperforms existing methods.","authors":["Hang Li","Jiahe Li","Meiying Gu","Jin Zheng","Lina Yu","Xiao Bai"],"published":"2026-08-11T15:38:55Z","updated":"2026-08-11T15:38:55Z","abstract_url":"https://arxiv.org/abs/2608.11077v1","html_url":"https://arxiv.org/html/2608.11077v1","pdf_url":"https://arxiv.org/pdf/2608.11077v1.pdf","matched_keywords":["3d","representation"],"source_used":"html","source_text_chars":45411,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, representation 相关；摘要显示其主要贡献为：Feed-forward Gaussian reconstruction has recently emerged as an efficient approach for driving scene reconstruction. However, prevailing LiDAR-based methods preserve the initial correspondence between observed points and Gaussian primitives, treating the init...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:08+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11051v1","title":"HUI360: A 360° Egocentric Dataset and Baselines for Human-Robot Interaction Anticipation","abstract":"As robots increasingly operate in human-populated environments, anticipating human intentions is essential for enabling proactive and socially aware behavior. Automatic anticipation of human-robot interactions is thus emerging as a crucial perception challenge for embodied agents. To this end, we introduce HUI360, the largest dataset for human-robot interaction anticipation in the wild and its set of baselines. The dataset was collected from a mobile robot, in the wild, over multiple days within a 3-month period, and in several environments, capturing natural, spontaneous behaviors from both passersby and users, and encompassing a diverse range of individuals. This variety enables evaluating and improving the generalization capabilities of interaction anticipation models. We designed a pipeline and share code for automatic interaction annotation in arbitrary 360-degree equirectangular videos, along with interfaces for manual refinement. Using this pipeline, we release the HUI360 open set of 1M pre-processed annotations, including detailed 2D poses, facial keypoints, and segmentation masks, obtained using state-of-the-art computer vision methods and manually curated to ensure high-quality tracking and interaction annotation. Additionally, we release the raw panoptic 360-degree images captured from the robot's egocentric viewpoint (on demand, for research purpose only in compliance with GDPR). Finally, we establish benchmark baselines for interaction anticipation, including the first cross-dataset evaluations for this task: to this end, we also release 6M annotations for another existing in-the-wild outdoor dataset collected from a mobile robot (SSUP-HRI). Dataset and code can be found at https://hucebot.github.io/hui360.","authors":["Raphael Lorenzo-Louis","Fabio Amadio","Bertrand Luvison","Serena Ivaldi"],"published":"2026-08-11T15:22:14Z","updated":"2026-08-11T15:22:14Z","abstract_url":"https://arxiv.org/abs/2608.11051v1","html_url":"https://arxiv.org/html/2608.11051v1","pdf_url":"https://arxiv.org/pdf/2608.11051v1.pdf","matched_keywords":["video","agent"],"source_used":"html","source_text_chars":74301,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, agent 相关；摘要显示其主要贡献为：As robots increasingly operate in human-populated environments, anticipating human intentions is essential for enabling proactive and socially aware behavior. Automatic anticipation of human-robot interactions is thus emerging as a crucial perception challeng...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:08+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11050v1","title":"3D Weighted Geometric Graph Neural Networks for Sheep Facial Pain Assessment","abstract":"Deep learning systems perform mainly within the 2D for a single image domain and take the face as a single-dimension representation, losing sight of the 3D anatomy of sheep and cross-landmark spatial relationships that are intrinsic to the clinically proven Sheep Pain Facial Expression Scale (SPFES). This paper presents the \\textbf{3D Sheep Pain Facial Expression System (3D-SPFES)}, a novel, monocular depth-aware geometric graph neural network system that integrates each SPFES facial landmark, such as the ears, eyes, and nose, into 3D Euclidean space estimated from a single RGB camera by using VideoDepthAnything, thus preventing the need for specialized depth hardware. Each landmark node includes a feature vector containing its 3D spatial coordinates, estimated surface normal, and facial attribute class embedding. Edges linked to nodes are assigned weights based on an aggregate metric that combines both Euclidean distance and surface co-planarity in a 3D space. A Weighted Geometric Graph Neural Network (WG-GNN) studies this graph using $\\mathcal{K} = 3$ geometry-aware message-passing layers enhanced by a scaled dot-product attention method that selectively enhances anatomically relevant inter-landmark messages. The resultant node embeddings are combined into $\\mathcal{O} = 3$ pain-level clusters and integrated into a Normalized Pain Score (NPS) within the range of $[0, 100%]$ a confidence-weighted, SPFES-derived scoring method.","authors":["Alam Noor","Luis Almeida","Mohamed Daoudi"],"published":"2026-08-11T15:21:36Z","updated":"2026-08-11T15:21:36Z","abstract_url":"https://arxiv.org/abs/2608.11050v1","html_url":"https://arxiv.org/html/2608.11050v1","pdf_url":"https://arxiv.org/pdf/2608.11050v1.pdf","matched_keywords":["video","3d","representation"],"source_used":"html","source_text_chars":65562,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d, representation 相关；摘要显示其主要贡献为：Deep learning systems perform mainly within the 2D for a single image domain and take the face as a single-dimension representation, losing sight of the 3D anatomy of sheep and cross-landmark spatial relationships that are intrinsic to the clinically proven S...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:08+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11037v1","title":"Multi-Level Evidence Aggregation for Robust Facial Phenotype Retrieval in Rare Genetic Disorder Prioritization","abstract":"AI-assisted facial phenotyping supports rare genetic disorder prioritization by retrieving visually similar diagnosed cases from facial image reference databases such as the GestaltMatcher Database (GMDB). Existing GestaltMatcher-based retrieval frameworks compare each test image with individual gallery images in a facial phenotype embedding space. However, this pointwise formulation does not fully exploit available evidence, because patients may have multiple images and disorders may be represented by multiple diagnosed gallery patients. We propose an inference-time multi-level evidence aggregation framework that improves facial phenotype retrieval without modifying the underlying GestaltMatcher-Arc encoder. The framework combines embedding-level patient aggregation of multiple images from the same individual, patient-weighted disorder centroids, and hybrid individual-centroid scoring to integrate test-patient observations, disorder-level gallery evidence, and local nearest-neighbor evidence. We evaluated the approach on GMDB v1.1.4 across disorders represented during training (GMDB-Freq), unseen disorders (GMDB-Rare), and multi-image patient subsets, using a unified gallery containing both GMDB-Freq and GMDB-Rare disorders. Multi-level evidence aggregation improved mean per-disorder top-$N$ retrieval accuracy across all evaluation subsets. Top-1 accuracy increased from 38.52% to 48.82% on GMDB-Freq and from 19.38% to 23.79% on GMDB-Rare. On multi-image subsets, top-1 accuracy increased from 46.12% to 60.94% on GMDB-Multi-Freq and from 18.54% to 26.71% on GMDB-Multi-Rare. These findings show that inference-time aggregation can improve next-generation facial phenotype retrieval without retraining the encoder, supporting a shift from isolated single-image matching toward multi-level aggregation of patient and disorder evidence for rare-disorder prioritization.","authors":["Alexander Hustinx","Carolin Kaffiné","Behnam Javanmardi","Tzung-Chien Hsieh","Peter Krawitz"],"published":"2026-08-11T15:12:44Z","updated":"2026-08-11T15:12:44Z","abstract_url":"https://arxiv.org/abs/2608.11037v1","html_url":"https://arxiv.org/html/2608.11037v1","pdf_url":"https://arxiv.org/pdf/2608.11037v1.pdf","matched_keywords":["retrieval"],"source_used":"html","source_text_chars":121520,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 retrieval 相关；摘要显示其主要贡献为：AI-assisted facial phenotyping supports rare genetic disorder prioritization by retrieving visually similar diagnosed cases from facial image reference databases such as the GestaltMatcher Database (GMDB). Existing GestaltMatcher-based retrieval frameworks co...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:08+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11017v1","title":"R4DSG: Relative 4D Scene Graph Memory for Object-Centric Question Answering in Long Egocentric Video","abstract":"Long-horizon egocentric video is a rich substrate for wearable AI assistants, but object-centric questions such as where an item was moved, when it last changed state, or why it was relocated remain difficult because caption- and transcript-based memories rarely preserve persistent object identity or structured spatial change. Existing long-video QA methods mainly emphasize temporal grounding and clip retrieval, while prior 3D scene-graph methods typically assume stronger geometry than free-motion wearable RGB video provides, including point clouds, RGB-D input, posed views, sparse reconstruction, or reconstructed scenes. R4DSG introduces a relative 4D scene graph memory for long egocentric video. Instead of storing raw graph sequences, R4DSG converts video into compact queryable memory entries indexed by time, place, persistent objects, anchor-relative change, and local interaction context. The main idea is to separate stable anchors from dynamic objects, maintain persistent object identity across frames, and represent object state through anchor-relative transitions rather than a globally aligned world model. Built on recent RGB-only advances in promptable video segmentation, temporal propagation, and relative 3D lifting, the method produces a retrieval-ready memory directly usable for long-horizon question answering. Evaluation on a 255-question object-related subset from EgoLifeQA shows, under question-only retrieval, a 6.7-point overall gain over EgoRAG-Text and a 12.5-point gain on when questions, which highlights the value of temporally organized object memory. These results position relative 4D scene graphs as a practical memory substrate for wearable assistants, AR systems, and embodied multimedia agents. GitHub Page: https://dualtransparency.github.io/R4DSG/.","authors":["Ke Ma","Yamin Mao","Weiming Li","Shuai Tan","Yijie Zhong","Hao Chen","Haofen Wang","Meng Wang"],"published":"2026-08-11T15:00:15Z","updated":"2026-08-11T15:00:15Z","abstract_url":"https://arxiv.org/abs/2608.11017v1","html_url":"https://arxiv.org/html/2608.11017v1","pdf_url":"https://arxiv.org/pdf/2608.11017v1.pdf","matched_keywords":["video","retrieval","3d","agent"],"source_used":"html","source_text_chars":53367,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, retrieval, 3d, agent 相关；摘要显示其主要贡献为：Long-horizon egocentric video is a rich substrate for wearable AI assistants, but object-centric questions such as where an item was moved, when it last changed state, or why it was relocated remain difficult because caption- and transcript-based memories rar...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:08+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.11013v1","title":"Watching Synthetic Videos: Aligning Cross-modal Representations with Visual Synthesis for Zero-shot Video Captioning","abstract":"Text-only training is a popular paradigm in zero-shot video captioning, where the video distribution is not available to the model during training, leading to a cross-modal gap between the training (text-only) and the inference (video-only). Previous works attempt to bridge the gap through simple linear transformations. However, the inherent gap between text and video makes cross-modal representation space alignment insufficient, resulting in inaccurate sentences. To address this issue, we propose a novel zero-shot video captioning framework (WSV) consisting of two training stages, which first generates corresponding synthetic video latent representations via a pretrained text-to-video generation model. To strengthen the fidelity of the latent representations, we propose a polisher capable of bridging the gap between real and synthetic video distributions. Subsequently, we design a prompter that conditions GPT-2 on the polished latent representations to generate the captions in the second training stage. During inference, an input video is encoded by a pretrained 3D Causal VAE and then fed directly into the prompter, which in turn guides GPT-2 to produce the final caption. Experimental results conducted on MSVD, MSR-VTT, and VATEX datasets demonstrate that our proposed method achieves scores of 52 and 95.7 on the B@4 and CIDEr metrics, respectively.","authors":["Liangyu Fu","Junbo Wang","Yuke Li","Ya Jing","Xuecheng Wu","Zhiyong Wang"],"published":"2026-08-11T14:57:44Z","updated":"2026-08-11T14:57:44Z","abstract_url":"https://arxiv.org/abs/2608.11013v1","html_url":"https://arxiv.org/html/2608.11013v1","pdf_url":"https://arxiv.org/pdf/2608.11013v1.pdf","matched_keywords":["video","3d","representation"],"source_used":"html","source_text_chars":48639,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d, representation 相关；摘要显示其主要贡献为：Text-only training is a popular paradigm in zero-shot video captioning, where the video distribution is not available to the model during training, leading to a cross-modal gap between the training (text-only) and the inference (video-only). Previous works at...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:09+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10995v1","title":"HNDiff: Haze-Noise Diffusion for Image Dehazing","abstract":"Existing diffusion-based methods have recently made significant progress in image dehazing. However, they typically neglect the physics of haze formation and reconstruct clean images from pure Gaussian noise, thereby limiting their restoration potential. To address this issue, we propose Haze-Noise Diffusion (HNDiff), a novel diffusion framework that embeds the atmospheric scattering model as an inductive bias. By grounding diffusion in physical principles, HNDiff ensures that the restoration aligns more closely with underlying mechanisms of haze formation. In its forward process, we introduce joint haze-noise diffusion with a haze-aware noise scheduler, which progressively adds both haze and noise to an image. Essentially, the scheduler adapts noise levels according to haze density, meaning that regions with heavier haze receive stronger noise injection to encourage content generation, while clearer regions receive lighter noise to better preserve details, which directly links the forward degradation process with the physics of haze. In the reverse process, we then derive a physically consistent dehazing-denoising process that simultaneously removes haze and noise to restore a clean image in a manner aligned with the forward degradation process. To further enhance practicality, we propose Latent HNDiff, which compiles clean latent priors that can be seamlessly integrated into existing dehazing networks to boost performance. Extensive experiments show that our work significantly improves leading dehazing backbones and achieves state-of-the-art results on benchmark datasets. The project page is available at https://jin-ting-he.github.io/HNDiff .","authors":["Jin-Ting He","Fu-Jen Tsai","Yan-Tsung Peng","Min-Hung Chen","Chia-Wen Lin","Yen-Yu Lin"],"published":"2026-08-11T14:47:38Z","updated":"2026-08-11T14:47:38Z","abstract_url":"https://arxiv.org/abs/2608.10995v1","html_url":"https://arxiv.org/html/2608.10995v1","pdf_url":"https://arxiv.org/pdf/2608.10995v1.pdf","matched_keywords":["diffusion"],"source_used":"html","source_text_chars":55627,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 diffusion 相关；摘要显示其主要贡献为：Existing diffusion-based methods have recently made significant progress in image dehazing. However, they typically neglect the physics of haze formation and reconstruct clean images from pure Gaussian noise, thereby limiting their restoration potential. To a...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:09+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10985v1","title":"PEAK: Precise and Persistent Concept Erasure via k-Sparse Autoencoders","abstract":"Erasing concepts from large-scale text-to-image (T2I) diffusion models has become increasingly crucial due to the growing concerns over copyright infringement, privacy violations, and offensive content. Existing approaches struggle to achieve both precise and persistent concept erasure: inaccurate localization of concept-related representations may cause unintended semantic interference, while incomplete removal of the underlying concept knowledge allows adversarial recovery. To address this dilemma, we propose PEAK, a \\textbf{\\textit{precise}} and \\textbf{\\textit{persistent}} concept erasure framework via k-Sparse Autoencoders (kSAEs). PEAK first trains a kSAE on internal activations of the diffusion denoising network to decompose dense representations into interpretable sparse features. By contrasting sparse activations induced by target and non-target prompts, PEAK identifies a compact set of target-specific features according to both activation strength and frequency. These localized features are then used for parameter optimization, where PEAK selectively suppresses target-related activations while preserving complementary non-target ones towards the original model. This feature-guided optimization embeds concept erasure directly into diffusion parameters, eliminating the need for additional inference-time intervention and facilitating effective persistence against adversarial attacks. Extensive experiments demonstrate that PEAK achieves effective and robust concept erasure. On the I2P benchmark, PEAK reduces NudeNet detections from 582 to 6, lowers the average attack success rate (ASR) from 96.52\\% to 5.63\\%, and preserves general generation quality on MS-COCO with a near-zero KID. Our code and models are available at: https://github.com/manmanTAT/PEAK","authors":["Man Jiang","Ouxiang Li","Weibao Xue","Zhenhua Tang","Yuan Wang","Shuo Wang","Yanbin Hao"],"published":"2026-08-11T14:38:01Z","updated":"2026-08-11T14:38:01Z","abstract_url":"https://arxiv.org/abs/2608.10985v1","html_url":"https://arxiv.org/html/2608.10985v1","pdf_url":"https://arxiv.org/pdf/2608.10985v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"html","source_text_chars":71459,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation, diffusion 相关；摘要显示其主要贡献为：Erasing concepts from large-scale text-to-image (T2I) diffusion models has become increasingly crucial due to the growing concerns over copyright infringement, privacy violations, and offensive content. Existing approaches struggle to achieve both precise and...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:09+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10981v1","title":"ThinkAfford: Affordance-Centric Reasoning for Fine-Grained 3D Grounding in Cluttered Scenes","abstract":"Task-driven 3D affordance grounding aims to localize the functional region in a cluttered 3D scene that enables an action specified by a natural-language instruction. Existing methods either predict 3D masks directly or construct them by selecting and fusing intermediate 2D/3D regions. However, they remain vulnerable to two intertwined failure modes: the predicted or selected regions may miss the target interaction area or have unsuitable granularity, while language grounding may confuse visually similar alternatives under relational instructions. To this end, we introduce ThinkAfford, which decouples high-recall affordance proposal generation from instruction-grounded reasoning. Specifically, the Affordance Proposal Generation module first uses learnable affordance prompts and multi-level visual features to predict interaction-conditioned heatmaps, extracting a variable number of fine-grained proposals without parsed object or part names as segmentation prompts. Visual-Prompted Affordance Reasoning then reasons over labeled proposal overlays using the full instruction, returning identifiers in a structured \"think-then-answer\" response. Moreover, Group Relative Policy Optimization uses proposal-level rewards from lifted 3D overlap to align VPAR selection with final 3D grounding. On the SceneFun3D validation split, ThinkAfford achieves 10.69% AP50 and 25.46% AP25 under the official evaluator, outperforming comparable 3D open-vocabulary and vision-language-model-based 2D-to-3D baselines. Module-level diagnostics further show that APG attains 77.5% recall at 25% intersection-over-union, while GRPO-trained VPAR achieves 72.1% selection accuracy on APG-covered queries, compared with 63.4% under supervised fine-tuning.","authors":["Xinrui Lin","Sha Zhang","Shumin Wang","Zenghuan Zhu","Jiajun Deng","Yanyong Zhang"],"published":"2026-08-11T14:36:16Z","updated":"2026-08-11T14:36:16Z","abstract_url":"https://arxiv.org/abs/2608.10981v1","html_url":"https://arxiv.org/html/2608.10981v1","pdf_url":"https://arxiv.org/pdf/2608.10981v1.pdf","matched_keywords":["3d"],"source_used":"html","source_text_chars":39689,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d 相关；摘要显示其主要贡献为：Task-driven 3D affordance grounding aims to localize the functional region in a cluttered 3D scene that enables an action specified by a natural-language instruction. Existing methods either predict 3D masks directly or construct them by selecting and fusing...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:09+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10964v1","title":"CARE: Confidence-Aware Reasoning for Reliable Medical VQA","abstract":"Reinforcement Fine-Tuning (RFT) has enabled medical Multimodal Large Language Models (MLLMs) to produce Chain-of-Thought (CoT) reasoning for visual question answering, yet these models suffer from $\\textit{confidence miscalibration}$---a systematic gap between expressed certainty and actual diagnostic accuracy that undermines clinical trust. We propose $\\textbf{CARE}$, a $\\textbf{C}$onfidence-$\\textbf{A}$ware medical $\\textbf{RE}$asoning framework that jointly optimizes accuracy and calibration through a dual-stage pipeline. First, a scalable Medical-CoT synthesis provides structured cold-start data for Supervised Fine-Tuning. Second, Group Relative Policy Optimization (GRPO) with a novel $\\textbf{Confidence-Aware Reward (CAR)}$ mechanism ties the model's confidence to diagnostic correctness within the reward signal. Across three Medical VQA benchmarks, $\\textbf{CARE}$ achieves the highest diagnostic accuracy while obtaining the lowest Expected Calibration Error and Hallucination Rate, establishing a foundation for trustworthy clinical decision support. Our code is available at https://github.com/anotherbricki/CARE.","authors":["Yuetian Du","Yucheng Wang","Zhenyuan Chen","Luyuan Chen","Rongyu Zhang","Jinjian Zhang","Wei Zhou","Zhijie Xu","Ming Kong","Zhan Zhou","Jie Liu","Qiang Zhu"],"published":"2026-08-11T14:28:52Z","updated":"2026-08-11T14:28:52Z","abstract_url":"https://arxiv.org/abs/2608.10964v1","html_url":"https://arxiv.org/html/2608.10964v1","pdf_url":"https://arxiv.org/pdf/2608.10964v1.pdf","matched_keywords":["multimodal"],"source_used":"html","source_text_chars":27937,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 multimodal 相关；摘要显示其主要贡献为：Reinforcement Fine-Tuning (RFT) has enabled medical Multimodal Large Language Models (MLLMs) to produce Chain-of-Thought (CoT) reasoning for visual question answering, yet these models suffer from $\\textit{confidence miscalibration}$---a systematic gap betwee...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-08-12T03:20:09+00:00","status":"fallback"},"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10954v1","title":"Evidence-Grounded Trustworthy Multimodal Reasoning and Evaluation Benchmark in Complex Urban Scenes","abstract":"While Multimodal Large Language Models (MLLMs) demonstrate impressive performance in benign scenarios, their cognitive reliability deteriorates significantly in complex scenes under adverse conditions. In these settings, models often rely on implicit inference without sufficient visual evidence, leading to a disconnect between perception and reasoning. Meanwhile, existing outcome-oriented benchmarks evaluate only final predictions and fail to diagnose failures in the underlying reasoning process. To address this gap, the authors propose AD2-Bench, which introduces a Hierarchical Visual Diagnosis framework that decomposes reasoning into a structured Chain of Evidence (CoE). This fine-grained diagnosis reveals that robust multimodal reasoning fundamentally depends on accurate evidence acquisition. Building on this perspective, the authors formulate reasoning from a probabilistic viewpoint and identify two primary causes of reasoning failure: Spatial Ambiguity, where models fail to distinguish target objects from background clutter, resulting in localization errors; and Semantic Uncertainty, where degraded visual features lead to incorrect semantic interpretation, resulting in understanding errors. To overcome these evidence deficiencies, they further propose Evidence-grounded Visual Reasoning (EGVOR), which replaces implicit reasoning with the explicit generation of Evidence Atoms - structured spatial-semantic triplets that enforce tight alignment between localization and semantic understanding. The model is trained through a hierarchical curriculum that progresses from reflective supervision construction to reinforcement learning, where reducing reasoning variance is explicitly rewarded. Extensive experiments demonstrate that EGVOR substantially improves reasoning stability under adverse conditions, providing a more robust framework for trustworthy multimodal cognition.","authors":["Zhaoyang Wei","Bowen Jiang","Xumeng Han","Jiashu Li","Xuehui Yu","Yuling Liu","Guorong Li","Zhenjun Han","Jianbin Jiao"],"published":"2026-08-11T14:23:07Z","updated":"2026-08-11T14:23:07Z","abstract_url":"https://arxiv.org/abs/2608.10954v1","html_url":"https://arxiv.org/html/2608.10954v1","pdf_url":"https://arxiv.org/pdf/2608.10954v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10952v1","title":"Multiple Scale Latents for Learned Image Compression","abstract":"Most learned image compression systems rely on a single latent representation combined with a hyperprior, which limits their ability to efficiently capture image structure across spatial scales. In this work, we propose a hierarchical latent representation to improve the efficiency of the entropy model. By using multiple latents at different scales, each with its own entropy model, we better capture the spatial structure of the latent representation. Our experiments show that this approach achieves a 17.9% BD-rate reduction over VVC on Kodak, demonstrating the effectiveness of multi-scale latent representations. Furthermore, the approach is orthogonal to other advances in learned image compression, making it a versatile addition to existing methods.","authors":["Jonas Brenig","Radu Timofte"],"published":"2026-08-11T14:22:20Z","updated":"2026-08-11T14:22:20Z","abstract_url":"https://arxiv.org/abs/2608.10952v1","html_url":"https://arxiv.org/html/2608.10952v1","pdf_url":"https://arxiv.org/pdf/2608.10952v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10949v1","title":"StreamFlow: Dynamic Memory Flows for Streaming Video Understanding","abstract":"Streaming video understanding requires multimodal large language models (MLLMs) to preserve relevant evidence from continuously evolving streams under strict causality and bounded memory. Yet existing paradigms remain limited: model-based methods require intrusive backbone updates, while memory-based methods expend substantial visual-encoding computation on temporally redundant content and rely on rigid access to visual history. To address these limitations, we introduce StreamFlow, an efficient visual memory framework that enables dynamic, on-demand access to historical visual information. StreamFlow combines a lightweight, dynamics-aware mid-term memory that filters temporal redundancy before visual encoding with a latent long-term memory that consolidates historical video content into visual latents accessible to subsequent reasoning. During generation, an attention-guided retrieval mechanism injects relevant visual latents when the model's reliance on visual evidence weakens. StreamFlow achieves state-of-the-art streaming video understanding performance, reaching 67.73% overall accuracy on StreamingBench, while also delivering strong performance on offline long-video benchmarks. Relative to the vanilla setting, it improves the visual attention score (VAS) by 59.1% while reducing end-to-end latency and peak memory by 50.4% and 21.1%, respectively, enabling more visually grounded and efficient reasoning.","authors":["Muxin Fu","Yifan Zhang","Wentao Zhang","Fangming Guo","Qian Chen","Guibin Zhang","Shuicheng Yan","Bo An"],"published":"2026-08-11T14:19:03Z","updated":"2026-08-11T14:19:03Z","abstract_url":"https://arxiv.org/abs/2608.10949v1","html_url":"https://arxiv.org/html/2608.10949v1","pdf_url":"https://arxiv.org/pdf/2608.10949v1.pdf","matched_keywords":["video","retrieval","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10938v1","title":"GS-CPE: Unified 6-Degree-of-Freedom Camera Pose Estimation via 3D Gaussian Splatting","abstract":"Despite substantial progress in visual localization, from scene coordinate regression to direct camera pose regression, achieving both robust generalization and high accuracy remain challenging. This study introduces GS-CPE (Gaussian Splatting based Camera Pose Estimation), a coarse-to-fine framework for 6-DoF camera pose estimation that unifies geometry-based coarse pose estimation with robust 3D Gaussian Splatting (3DGS) warping based pose refinement. GS-CPE first estimates a coarse pose via retrieval-guided geometric pose estimation on a 3DGS scene representation, then refines it by minimizing a visibility aware masked RGB warping objective in a multi-scale optimization framework, with adaptive re-rendering. Extensive experiments on indoor and outdoor benchmarks including 7Scenes, Cambridge Landmarks, FAST-LIVO2 datasets, and a custom dataset demonstrate state-of-the-art performance, consistently outperforming in both accuracy and generalization.","authors":["Huaiyuan Weng","Chul Min Yeum","Su-Min Kang"],"published":"2026-08-11T14:06:51Z","updated":"2026-08-11T14:06:51Z","abstract_url":"https://arxiv.org/abs/2608.10938v1","html_url":"https://arxiv.org/html/2608.10938v1","pdf_url":"https://arxiv.org/pdf/2608.10938v1.pdf","matched_keywords":["retrieval","3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10933v1","title":"SafeCA: Safe Cross-Attention Localization and Regulation for Text-to-Video Jailbreak Defense","abstract":"Text-to-Video (T2V) generative models are vulnerable to jailbreak attacks in real-world deployment, leading them to produce harmful or inappropriate content. Existing defense approaches mainly rely on input filtering or reconstruction, which not only incur high computational latency but also tend to distort semantics. To address these issues, we experimentally and systematically analyze the differences between clean and jailbreak samples in the cross-attention feature space, revealing for the first time a cumulative separation effect and a progressively increasing trend of linear separability between the two during the diffusion process. Based on this insight, we propose SafeCA, a feature-level defense mechanism for safe cross-attention localization and regularization. Firstly, we identify key defensive regions and values through attention stability analysis using cross-attention features collected from clean prompts within a single inference. Secondly, SafeCA mitigates anomalous activations via attention masking with energy normalization and introduces a lightweight semantic-space adapter to redirect abnormal semantic flows. Furthermore, we detect and suppress potentially malicious tokens by back-propagating feature anomaly signals to the input cue words, thereby enhancing the deployability of the defense in commercial models. Experimental results show that SafeCA reduces the jailbreak success rate by about 20% on mainstream T2V models, adds almost no inference overhead (+0.1s), and maintains good text-video semantic consistency. Overall, SafeCA provides an architecture-level, deployable protection paradigm for T2V generation models.","authors":["Siyuan Liang","Yupeng Qiu","Junfeng Fang","Rong-Cheng Tu","Jiaxing Huang","Dacheng Tao"],"published":"2026-08-11T14:01:24Z","updated":"2026-08-11T14:01:24Z","abstract_url":"https://arxiv.org/abs/2608.10933v1","html_url":"https://arxiv.org/html/2608.10933v1","pdf_url":"https://arxiv.org/pdf/2608.10933v1.pdf","matched_keywords":["video","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10932v1","title":"Temporally Grounded Compositional Camera Motion Understanding via Geometric Knowledge Distillation","abstract":"Understanding camera motion is fundamental to video perception, with applications in spatial intelligence and controllable video generation. Multimodal large language models (MLLMs) provide a natural interface for this task, but existing work typically assigns one or more labels to an entire clip. Such clip-level recognition overlooks two defining properties of real camera motion: it can change within a shot, and multiple movements can occur simultaneously. We therefore formulate camera-motion understanding as temporally grounded, compositional recognition, which requires a model to localize motion-consistent intervals and identify every movement active within each interval. We introduce CamChoreo, a benchmark of 4,229 real single-shot clips with expert-annotated temporal segments. Its annotations use a compact vocabulary of 20 direction-aware labels, and nearly half of the segments contain compound camera motion, with multiple movement primitives active simultaneously. Recognizing such fine-grained, compositional motion is hard for current MLLMs, whose visual encoders emphasize semantic content rather than the geometric evidence on which camera motion depends. Directly injecting features from a frozen 3D foundation model addresses this gap, but requires running the expensive geometry model on every input; we refer to this baseline as CamInject. We instead propose CamDistill, which distills the same geometric knowledge into lightweight camera tokens during training and removes the 3D model at inference. CamDistill matches the accuracy of direct feature injection without running the 3D teacher at inference. Together, CamChoreo and CamDistill advance camera-motion understanding from clip-level labeling to temporally grounded, compositional recognition. Project page: https://ddz16.github.io/cammotion.github.io/.","authors":["Dazhao Du","Shiyan Du","Jian Liu","Yongjian Yu","Bohai Gu","Tao Han","Hualuo Liu","Eric Liu","Yujia Zhang","Xi Chen","Song Guo"],"published":"2026-08-11T14:00:02Z","updated":"2026-08-11T14:00:02Z","abstract_url":"https://arxiv.org/abs/2608.10932v1","html_url":"https://arxiv.org/html/2608.10932v1","pdf_url":"https://arxiv.org/pdf/2608.10932v1.pdf","matched_keywords":["video","3d","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10908v1","title":"Order Matters: LVLMs as Judges for Temporal Reasoning in Image Sequences","abstract":"As generative multimedia evolves from static image synthesis to complex, interleaved visual narratives, a foundational bottleneck has emerged: the judgment crisis. While human perception naturally synthesizes the temporal and logical flow of a story, automated evaluation systems remain largely \"blind\" to sequential continuity, often failing to distinguish between a coherent narrative and a semantically shuffled or contradictory sequence. This work identifies a critical structural gap in current multimodal evaluation paradigms, arguing that the reliance on Large Vision-Language Models (LVLMs) as judges is fundamentally limited by architectural biases. Our analysis reveals a profound performance dichotomy: while models may appear competent in isolated pointwise scoring, they suffer a catastrophic collapse when required to perform pairwise discrimination of temporal order. We demonstrate that this is not merely a data-scarcity issue but a structural one. Through a series of diagnostic probes, we uncover systematic positional asymmetries, specifically primacy and recency effects, where a model's judgment of a story is significantly influenced by the placement of a frame, often more than by its semantic consistency. These biases, potentially rooted in causal masking and rotary embeddings, suggest that current transformer-based judges are inherently ill-equipped for long-form visual reasoning. By exposing these blind spots, we challenge the multimedia community to move beyond snapshot-centric metrics and instead pioneer Temporally-Aware Evaluation paradigms that treat visual sequences as unified logical structures rather than unordered collections of frames.","authors":["Martina Ianaro","Guilherme Fernandes","Maurizio Gabbrielli","Joao Magalhaes"],"published":"2026-08-11T13:29:03Z","updated":"2026-08-11T13:29:03Z","abstract_url":"https://arxiv.org/abs/2608.10908v1","html_url":"https://arxiv.org/html/2608.10908v1","pdf_url":"https://arxiv.org/pdf/2608.10908v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10888v1","title":"Sensor-Informed Per-Point Covariance for Structured-Light 3D Imaging","abstract":"Per-point uncertainty models are important in structured-light 3D reconstruction for probabilistic registration, fusion, and quality assessment. In practice, however, point-cloud covariances are often modeled as isotropic constants or inferred from local surface geometry and therefore do not explicitly reflect the measurement process. This is a limitation in fringe projection profilometry (FPP), where phase noise propagates through calibrated reconstruction and produces strongly anisotropic 3D uncertainty. This paper presents a sensor-informed first-order method for constructing a per-point 3 x 3 covariance field from experimentally measured phase precision and calibrated phase-to-depth and phase-to-3D mappings. The formulation separates a rank-1 phase-induced covariance from an effective full-rank completion obtained by incorporating fitted lateral image-space perturbation scales. Repeated-plane experiments under fixed imaging conditions show close alignment of the dominant covariance direction with the viewing ray, and consistency between the dominant phase-induced uncertainty scale and scalar depth uncertainty. In G-ICP registration, the proposed covariance substantially improves over a constant isotropic model while providing a sensor-derived uncertainty representation complementary to conventional geometry-based covariances.","authors":["Sehoon Tak","Jae-Sang Hyun"],"published":"2026-08-11T13:05:22Z","updated":"2026-08-11T13:05:22Z","abstract_url":"https://arxiv.org/abs/2608.10888v1","html_url":"https://arxiv.org/html/2608.10888v1","pdf_url":"https://arxiv.org/pdf/2608.10888v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10886v1","title":"GESTO: Human-Centric Spatio-Temporal Memory for Reasoning in Dynamic Scenes","abstract":"Robots operating in human environments need memories that capture not only what objects exist and where, but also how people use them over time and how individual interactions compose into goal-directed activities. Existing 4D scene graphs preserve object and place histories but omit activity structure, whereas activity representations are either not grounded in persistent 3D scenes or rely on externally provided event boundaries and object associations. We present GESTO (Grounded Event and Spatio-Temporal memOry), a spatio-temporal memory that couples a persistent 4D scene graph with a two-level hierarchy of atomic human--object interactions and goal-driven events. From an RGB-D observation stream, GESTO automatically extracts timestamped interactions, grounds them to persistent scene entities, groups them into events, and uses event context to refine uncertain object associations. A relation-aware tool-calling agent queries the resulting memory for activity-centric spatio-temporal reasoning. We evaluate GESTO on the reproducible text, binary, and time categories of an existing benchmark, together with 40 new Space2Event and Event2Space queries. GESTO achieves scores of 0.71, 0.75, and 0.70 on the standard categories, approaching a method supplied with ground-truth event and object grounding, while substantially outperforming the same reasoning framework when these inputs are removed. It further achieves 0.73 and 0.75 on Space2Event and Event2Space queries. Ablations show that hierarchical event structure and context-aware grounding refinement provide complementary benefits, supporting activity-grounded hierarchical memory for retrospective reasoning in dynamic human environments.","authors":["Ermanno Bartoli","Buwei He","Dennis Rotondi","Sebastian Koch","Federico Tombari","Kai O. Arras","Patric Jensfelt","Yixi Cai","Iolanda Leite"],"published":"2026-08-11T13:03:33Z","updated":"2026-08-11T13:03:33Z","abstract_url":"https://arxiv.org/abs/2608.10886v1","html_url":"https://arxiv.org/html/2608.10886v1","pdf_url":"https://arxiv.org/pdf/2608.10886v1.pdf","matched_keywords":["3d","agent","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10870v1","title":"NullEdit: Stealthy Image Protection via VLM Condition Redirection","abstract":"Modern image editors combine vision-language models (VLMs) with diffusion transformer backbones to modify a single reference image according to instructions without fine-tuning. This capability also enables unauthorized manipulation of publicly released images. Existing inference-time defenses either invalidate edits through conspicuous corruption, thereby exposing the protection, or allow them to proceed with identity or reference content drift, thereby failing to prevent the editing behavior itself. We instead target a stealthy and harmless no-op in which the requested edit is suppressed, the output remains natural and source-preserving without conspicuous artifacts or identity replacement, and harmful semantics requested by malicious instructions are absent. We propose NullEdit, which targets the VLM representation jointly formed from the reference image and instruction before it conditions the downstream DiT backbone. Using normal-edit and no-edit anchors, NullEdit redirects this representation, while cross-prompt gradient averaging transfers protection to held out instructions. Across Step1X-Edit and Qwen-Image-Edit on CelebA-HQ and VGGFace2, NullEdit reduces the EditReward IF score by 0.813 on average relative to the SOTA baseline while preserving subject identity and source content.","authors":["Weiyao Huang","Liqin Wang","Ziqi Sheng","Wei Lu"],"published":"2026-08-11T12:46:09Z","updated":"2026-08-11T12:46:09Z","abstract_url":"https://arxiv.org/abs/2608.10870v1","html_url":"https://arxiv.org/html/2608.10870v1","pdf_url":"https://arxiv.org/pdf/2608.10870v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10864v1","title":"Multi-View Relational Distillation for Spatial Reasoning with Vision-Language Models","abstract":"Vision-language models (VLMs) have achieved strong image and video understanding, yet their visual-spatial representations remain geometrically fragile, leading to failures in spatial reasoning needed for embodied AI, robotics, and autonomous driving. Prior approaches to geometry grounding either fine-tune VLMs on spatial question answering, which can perpetuate spurious visual representations, or fuse features from large geometry-grounded vision models, which substantially increases model size at inference. Knowledge distillation from geometry-grounded vision models offers an alternative, but directly matching multi-view teacher features can disrupt the pretrained alignment between visual and textual representations, degrading object- and language-semantic capabilities. We propose multi-view relational distillation (MVRD), which distills patch-wise cosine similarities across views instead of the teacher features themselves. These relations encode geometric correspondences adequate for spatial understanding, while leaving the student representation underdetermined, allowing it to remain close to its pretrained vision- language space. Across representative VLMs, MVRD improves visual-spatial reasoning, outperforming supervised fine-tuning and feature distillation while approaching feature fusion methods with considerably fewer added parameters and lower latency. We show that MVRD makes visual representations more geometric while retaining language alignment, and generalizes to 3D scene understanding tasks such as object grounding, dense captioning, and question answering.","authors":["Kiet T. Nguyen","Hanbo Shim","Jinwoo Kim","Seunghoon Hong"],"published":"2026-08-11T12:34:41Z","updated":"2026-08-11T12:34:41Z","abstract_url":"https://arxiv.org/abs/2608.10864v1","html_url":"https://arxiv.org/html/2608.10864v1","pdf_url":"https://arxiv.org/pdf/2608.10864v1.pdf","matched_keywords":["video","3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10860v1","title":"Flex-$π$: A Multi-Stream World-Action Model with Compute Flexibility","abstract":"World-action models (WAMs) predict the future to act better, but nearly all of them predict only RGB latents, trained purely for pixel reconstruction, with no explicit signal for the 3D geometry or object semantics manipulation needs. We find a surprising free lunch: the same frozen video-generation VAE that encodes RGB also encodes 3D pointmaps almost losslessly, with no pointmap-specific training at all. This lets us supervise Flex-$π$, a 6B-parameter WAM, on 3D geometry and object-centric DINO semantics alongside RGB, at no cost in new sensors, new pre-training, or inference latency. Every visual signal is projected into this shared latent space and denoised jointly with actions inside a Mixture-of-Transformers backbone; per-stream dropout with cross-modality forcing then lets a single trained checkpoint run on any subset of these streams, from a fast action-only mode to full joint generation. The result is a policy that is exceptionally demonstration-efficient and generalizes well, beating the strongest baselines by up to 2-7$\\times$ on dexterous, precise, real-world bimanual manipulation tasks both in and out of distribution, all while running faster than $π_{0.5}$. Our project website: https://flex-pi.github.io/","authors":["Ge Yan","Jinghao Liu","Yuzhi Fan","Lei Cai","Minwen Liao","Jesse Zhang","Dieter Fox"],"published":"2026-08-11T12:33:51Z","updated":"2026-08-11T12:33:51Z","abstract_url":"https://arxiv.org/abs/2608.10860v1","html_url":"https://arxiv.org/html/2608.10860v1","pdf_url":"https://arxiv.org/pdf/2608.10860v1.pdf","matched_keywords":["video","3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10838v1","title":"PolyLayout: Hierarchical VLM-Guided Layout Generation Beyond Rectangular Rooms","abstract":"Generating physically plausible 3D room layouts is essential for home furnishing retail, enabling customers to visualize products in their own homes and confidently make purchasing decisions. However, a gap exists between academic research and real-world application: existing solutions primarily focus on algorithmic strategies for furniture placement, largely neglecting the non-rectangular geometries and strict door/window constraints prevalent in real homes. To bridge the gap, we introduce a hybrid, hierarchical framework tailored for retail, specifically designed to support scalable spatial planning applications. Our system decouples generation into three stages: (1) functional furniture clustering and fine-grained intra-zone placement; (2) macro-routing guided by a vision-language model (VLM) to anchor both these clustered zones and any remaining standalone furniture within diverse polygonal boundaries; and (3) rule-based optimization for collision-free micro-arrangements that respect architectural constraints. We evaluate our system on production-scale catalogs and a representative set of irregular real-world topologies. Our results show that our approach attains the highest perceptual plausibility while maintaining good geometric compliance at relatively low latency, and extends to irregular boundaries that existing methods do not natively support.","authors":["Yutong Jiang","Zahra Atashgahi","Carlos Soto Garcia Delgado","Ruben Brokkelkamp","Davide Zanutto","Efşan Sökmen","Shahin Shahkarami"],"published":"2026-08-11T12:04:14Z","updated":"2026-08-11T12:04:14Z","abstract_url":"https://arxiv.org/abs/2608.10838v1","html_url":"https://arxiv.org/html/2608.10838v1","pdf_url":"https://arxiv.org/pdf/2608.10838v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10835v1","title":"UniProbe: A Learnable Token-Level Hallucination Detector for Large VLMs using Multi-Structural Internal Representations","abstract":"Large Vision-Language Models (LVLMs) achieve impressive visual reasoning and dialogue capabilities, yet frequently hallucinate content unsupported by the visual input. Effective mitigation requires token-level localization, enabling targeted intervention without discarding the entire response. Existing detectors require expensive full-model fine-tuning, rely on external verifiers that ignore the model's generation process, or reduce internal signals to isolated features and hand-crafted statistics, discarding spatial, sequential, and relational structure. We introduce \\textbf{UniProbe}, a lightweight, unified, learnable detector that models a frozen LVLM's heterogeneous computational trace from a single forward pass. UniProbe constructs a directed graph over image patches, query tokens, and generated tokens, with attention weights encoding their relations. It processes this trace with alternating structure-aware modules: a GNN for relational evidence, a ViT for 2-D visual geometry, and a GRU for response order. Interleaving them allows spatial, relational, and sequential evidence to interact throughout the detector. We further develop a streaming variant for hallucination-aware decoding, which detects and resamples hallucinated tokens during generation, and a self-adaptation strategy aligning the detector with the LVLM's own generations. Across diverse LVLM backbones, UniProbe achieves state-of-the-art token-level and object-hallucination detection. During decoding, it reduces object hallucinations by up to 55\\% at $1.06\\times$ the latency of standard generation.","authors":["Dvir Samuel","Guy Bar-Shalom","Fabrizio Frasca","Ethan Fetaya","Yftah Ziser","Gal Chechik","Haggai Maron"],"published":"2026-08-11T12:01:59Z","updated":"2026-08-11T12:01:59Z","abstract_url":"https://arxiv.org/abs/2608.10835v1","html_url":"https://arxiv.org/html/2608.10835v1","pdf_url":"https://arxiv.org/pdf/2608.10835v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10827v1","title":"MIRA: Medical Image Reflection for Agentic Diagnosis","abstract":"Medical visual agents can use tools to inspect images and retrieve external knowledge, but indiscriminate tool use may introduce noisy or misleading evidence. Reliable diagnosis therefore requires not only acquiring additional observations, but also verifying whether tool actions are necessary and whether the resulting evidence supports the current hypothesis. We introduce MIRA (Medical Image Reflection for Agentic Diagnosis), a medical visual diagnostic framework for autonomous evidence search and reflective verification. MIRA dynamically invokes image-processing operations, including zooming, grounding, pointing, rotation, and measurement, as well as web search, while evaluating the relevance and consistency of the acquired evidence. We develop MIRA through a two-stage training strategy. First, a tool-augmented Monte Carlo Tree Search data engine explores diverse diagnostic hypotheses and jointly verifies visual grounding accuracy and semantic consistency to construct supervised fine-tuning trajectories. Second, reinforcement learning further improves decision-making through online reflective principle evolution: failure cases are distilled into candidate principles, and only principles that improve held-out rollout rewards are retained. Across nine medical visual reasoning benchmarks, MIRA achieves an average score of 64.73, improving its Qwen3-VL-8B backbone by 7.44 points. It also increases useful tool-use judgments from 56.2% to 73.8% and reduces harmful judgments from 8.9% to 1.6%. Qualitative analyses show that MIRA can re-examine evidence, correct premature conclusions, and adapt its tool-use strategy. Project page: https://MIRA-VL.github.io/","authors":["Shengzhi Wang","Jun Yang","Kai Wu","Xiaozhong Ji","Yiwen Ye","Ziyang Chen","Mingliang Xiong","Wen Fang","Mingqing Liu","Mengyuan Xu","Miaoxuan Shan","Caiyan Liu","Bin He","Qingwen Liu"],"published":"2026-08-11T11:57:27Z","updated":"2026-08-11T11:57:27Z","abstract_url":"https://arxiv.org/abs/2608.10827v1","html_url":"https://arxiv.org/html/2608.10827v1","pdf_url":"https://arxiv.org/pdf/2608.10827v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10824v1","title":"Neural Introspection Gating for Adaptive KV-Cache Reuse in Vision-Language-Action Models","abstract":"Vision-Language-Action(VLA) models map camera images and language instructions directly to motor commands through a single autoregressive transformer. In real-time control, they still spend substantial compute recomputing key-value(KV) representations for visual tokens that barely change across neighboring frames. Recent work such as VLA-Cache reduces that cost by reusing KV states for visually static patches, but its policy relies only on observation-space heuristics and does not account for the model's own uncertainty. We propose Gated VLA-Cache, a lightweight, training-free extension that augments visual-similarity caching with neural introspection. The method monitors the logit margin between the top two predicted action tokens, a zero-cost confidence signal available during decoding. When the margin drops below a threshold, the cache is invalidated and a full recompute is triggered. Evaluated on four LIBERO benchmark suites with both OpenVLA and OpenVLA-OFT, Gated VLA-Cache improves reliability when blind caching hurts. On LIBERO-Goal and LIBERO-Long, it recovers over 100% of the lost accuracy while retaining 80% of the compute savings.","authors":["Zhijie Wu","Kento Kawaharazuka","Kei Okada"],"published":"2026-08-11T11:53:10Z","updated":"2026-08-11T11:53:10Z","abstract_url":"https://arxiv.org/abs/2608.10824v1","html_url":"https://arxiv.org/html/2608.10824v1","pdf_url":"https://arxiv.org/pdf/2608.10824v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10807v1","title":"Modelling Geographic Atrophy Progression using Implicit Neural Representations","abstract":"Age-related Macular Degeneration (AMD) is the major cause of blindness in the Western world. Its late dry phase is characterised by irreversible atrophic areas, namely Geographic Atrophy (GA). Longitudinal Fundus Autofluorescence (FAF) image acquisitions are currently the main tool for assessing lesion growth over time at the image level. However, due to its highly individualised progression, the evolution of late AMD remains poorly understood. In this work, we propose using Implicit Neural Representations (INRs) to model GA progression at the individual level in a low-data setting. Our approach generates both FAF and GA segmentation at both past and future time points. Among the comparison models, our method achieves competitive segmentation quality across different scenarios, yielding the lowest Mean Absolute Error (MAE) for the GA lesion area and the highest DICE score, without sacrificing FAF image quality. The code is available at https://github.com/SimoneSarrocco/ga-progression-with-inrs.","authors":["Simone Sarrocco","Paul Friedrich","Florentin Bieder","Christina Bornberg","Philippe Valmaggia","Peter Maloca","Philippe Cattin"],"published":"2026-08-11T11:26:01Z","updated":"2026-08-11T11:26:01Z","abstract_url":"https://arxiv.org/abs/2608.10807v1","html_url":"https://arxiv.org/html/2608.10807v1","pdf_url":"https://arxiv.org/pdf/2608.10807v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10798v1","title":"Beyond Fixed Luminance: Towards Panchromatic and Orthochromatic Image Colorization","abstract":"Most image colorization systems operate in $Lab$ space by predicting chroma ($ab$) while preserving an input-derived luminance channel ($L$). While effective on standard benchmarks, this fixed-luminance design restricts brightness changes and becomes unreliable when grayscale formation deviates from natural-image luminance, as in historical orthochromatic photography. We propose a luminance-agnostic colorization framework that formulates colorization as full-RGB image editing using a foundation image-editing model. To bridge modern panchromatic and historical orthochromatic conditions, we introduce a mixed grayscale objective that trains the model under both standard luminance grayscale and a red-insensitive grayscale formation. Experiments on COCO, ImageNet, and a multi-instance benchmark show that our method is competitive on standard grayscale inputs and substantially more robust under orthochromatic inputs, with qualitative comparisons and a human study indicating fewer visible color artifacts.","authors":["Swarnim Maheshwari","Syed Imam Ali","Vineeth N. Balasubramanian"],"published":"2026-08-11T11:12:24Z","updated":"2026-08-11T11:12:24Z","abstract_url":"https://arxiv.org/abs/2608.10798v1","html_url":"https://arxiv.org/html/2608.10798v1","pdf_url":"https://arxiv.org/pdf/2608.10798v1.pdf","matched_keywords":["instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10796v1","title":"E$^3$mo-Bench: A Scalable Benchmark for Multimodal Evoked and Expressed Emotion Understanding via Bayesian Pairwise Alignment","abstract":"Understanding both expressed and evoked emotions is critical for multimodal large language models (MLLMs) to achieve comprehensive affect-aware interactions. However, existing benchmarks typically examine expressed and evoked emotions in isolation or are constrained to coarse-grained and incomplete affective characterizations. To bridge this gap, we introduce E$^3$mo-Bench, a scalable benchmark comprising $12{,}314$ question-answer pairs across $2{,}524$ videos with predefined affective perspectives. It evaluates evoked and expressed emotion understanding via $3$ complementary tasks: emotion perception, open-vocabulary recognition, and valence-arousal-dominance (VAD) assessment. To efficiently scale reliable continuous annotations, we propose Bayesian Pairwise Alignment, which aggregates sparse, low-burden pairwise judgments into anchor-referenced VAD estimates. Furthermore, we develop E$^3$mo-Score, a training-free agent that aggregates complementary judgments from a five-model committee to improve VAD estimation. Extensive experiments validate the effectiveness of our framework and expose a pronounced performance skew between evoked and expressed emotion paradigms. These findings, coupled with MLLMs' persistent deficits in fine-grained recognition and dimensional assessment, chart a clear course for advancing multimodal emotional intelligence.","authors":["Lancheng Gao","Ziheng Jia","Shengyan Li","Zixuan Xing","Jiarui Wang","Huiyu Duan","Xiongkuo Min"],"published":"2026-08-11T11:05:22Z","updated":"2026-08-11T11:05:22Z","abstract_url":"https://arxiv.org/abs/2608.10796v1","html_url":"https://arxiv.org/html/2608.10796v1","pdf_url":"https://arxiv.org/pdf/2608.10796v1.pdf","matched_keywords":["video","agent","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10790v1","title":"MVTrack: Ultrafast Appearance-Free Moving Object Tracking from Compressed Bitstreams","abstract":"Deploying modern video trackers at scale is bottlenecked by the computational cost of RGB-based object detectors. To this end, we present MVTrack, an ultrafast tracker for moving objects that operates directly on H.264 bitstreams. MVTrack combines MVDet, a lightweight detector for motion vector fields, with MVLink, a minimalist kinematic association module. On VIRAT, MVTrack outperforms YOLO26n while using 60$\\times$ fewer parameters, requiring 40$\\times$ fewer FLOPs, and reducing CPU latency by 8.6$\\times$. These results demonstrate that compressed video data alone can enable accurate and scalable surveillance tracking, thereby bypassing the need for pixel reconstruction.","authors":["Iñaki Erregue","Kamal Nasrollahi","Sergio Escalera"],"published":"2026-08-11T10:53:22Z","updated":"2026-08-11T10:53:22Z","abstract_url":"https://arxiv.org/abs/2608.10790v1","html_url":"https://arxiv.org/html/2608.10790v1","pdf_url":"https://arxiv.org/pdf/2608.10790v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10764v1","title":"FADE: From Passive Verification to Active Discovery in Counterfactual Video Understanding","abstract":"Counterfactual video understanding evaluates whether models grasp physical and commonsense regularities. However, existing multiple-choice question (MCQ) benchmarks inadvertently leak target events through their questions and candidate options. This reduces the core challenge from active discovery to text-guided verification. In this paper, we present FADE, an effective training framework for counterfactual discovery and explanation. Our method is built on an evidence-first, two-stage training paradigm. First, evidence-internalized supervised fine-tuning grounds the model's predictions in decisive visual anomalies. Second, we apply a fading-anchor reinforcement learning strategy that progressively removes textual guidance, compelling the model to independently discover and explain evidence. To rigorously evaluate this capability, we also introduce an effective pipeline that converts existing MCQ datasets into aligned MCQ, open-ended question answering (OQA), and captioning tasks without requiring additional data curation. Our simple approach yields strong results. Using Qwen3-VL-8B as the baseline, FADE achieves state-of-the-art strict paired scores across all three tasks on DualityVidQA-test and IPV-Bench, outperforming GPT-5.6. In specific, when transitioning from constrained MCQs to unconstrained OQA and captioning, our model demonstrates remarkable robustness. Its performance retention is 90.4% and 67.4% on DualityVidQA-test-substantially higher than the 48.1% and 30.7% retained by GPT-5.6. We hope this simple framework can serve as a solid baseline for future research in unconstrained counterfactual video understanding.","authors":["Fufangchen Zhao","Jinhu Fu","Jiachen Lei","Jiahong Wu","Xiangxiang Chu","Danfeng Yan"],"published":"2026-08-11T10:22:08Z","updated":"2026-08-11T10:22:08Z","abstract_url":"https://arxiv.org/abs/2608.10764v1","html_url":"https://arxiv.org/html/2608.10764v1","pdf_url":"https://arxiv.org/pdf/2608.10764v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10758v1","title":"Where To Look? : Causal Tracing of Vision Encoders in VLM","abstract":"Vision-language models can describe an image with remarkable accuracy, yet a more fundamental question remains unanswered: what visual information actually drives their answers? In this work, we investigate this question through causal tracing, and we observe that highly causal vision tokens often lie outside the target region. Extending the analysis to larger vision-language models reveals a similar pattern across models and corruption settings, suggesting that strong multimodal performance does not necessarily imply spatially localized causal representations. We further investigate: can these models preserve visual structure when appearance cues are removed? and find that visual cues are exploited to understand visual structures. Together, our experiments expose a gap between seeing, using, and reasoning over visual structure, and provide a causal framework for studying how visual information is transformed, preserved, and ultimately used by modern vision-language models.","authors":["Naren Kumar S","Tirth Bhatt","Mayank Singh"],"published":"2026-08-11T10:17:34Z","updated":"2026-08-11T10:17:34Z","abstract_url":"https://arxiv.org/abs/2608.10758v1","html_url":"https://arxiv.org/html/2608.10758v1","pdf_url":"https://arxiv.org/pdf/2608.10758v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10756v1","title":"Embodied Multimodal Grounding for Open-Vocabulary Mobile Manipulation via Semantic 3D Gaussian Splatting","abstract":"Embodied mobile manipulation requires language, visual observations, three-dimensional scene structure, and action feasibility to be aligned before execution. We study open-vocabulary target grounding with few-shot manipulation in local household workspaces and present an embodied multimodal grounding framework that integrates active multi-view Semantic 3D Gaussian Splatting (Semantic-3DGS), reachability-aware base positioning, and a diffusion-based vision-language-action policy. A task-driven local Semantic-3DGS serves as a shared interface across active sensing, language-conditioned 3D localization, obstacle-aware scene reasoning, base preparation, and semantic conditioning of the action model. To preserve pretrained action priors, the 3D semantic cues are injected only into the late action-expert blocks. In expanded 50-trial real-robot evaluations against representative vision-language-action (VLA) approaches, the full system achieves 60% long-horizon success compared with 40% for PointVLA and 28% for DexVLA, and reaches 74% success in heavily cluttered manipulation compared with 52% for the single-view variant and 46% for PointVLA. It also maintains 75% success under a 75 cm height shift and eliminates photo-induced false grasps. These results indicate that explicit, refreshable 3D semantic grounding can improve robustness under clutter, occlusion, viewpoint variation, and embodiment constraints.","authors":["Huosen Ou","Dongni Song","Yuncong Wang","Tao Zhou","Yiding Ji"],"published":"2026-08-11T10:16:30Z","updated":"2026-08-11T10:16:30Z","abstract_url":"https://arxiv.org/abs/2608.10756v1","html_url":"https://arxiv.org/html/2608.10756v1","pdf_url":"https://arxiv.org/pdf/2608.10756v1.pdf","matched_keywords":["3d","multimodal","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10744v1","title":"Beyond Pixels: From Video Priors to 4D Worlds","abstract":"4D generation synthesizes dynamic 3D scenes from conditions such as text or images. Existing methods either reconstruct generated RGB videos with a separate 4D model or adapt a particular video generator to predict geometry directly. The former suffers from distribution mismatch and error propagation, whereas the latter ties 4D prediction to a specific generator and may require retraining when the generator or conditioning regime changes. We ask whether the final denoised latents of video models that share a variational autoencoder (VAE) can instead provide a reusable interface to explicit 4D prediction. Building on this insight, we introduce direct latent-to-4D generation and instantiate it as Latent-to-4D, which bypasses RGB by aligning a video latent with the token grid of a pretrained 4D decoder and refining it through frame-wise and global spatiotemporal attention. Trained on roughly 1K existing reconstruction clips, a single checkpoint transfers unchanged across multiple video diffusion transformers within the same VAE family. On Text4D-200 and I4D-200, Latent-to-4D surpasses matched same-latent Wan+4RC cascades in projection-based DINO-F1 by 2.88--3.45 and 5.81 points, respectively, while also being preferred by human raters for geometry, temporal stability, and overall quality.","authors":["Zihao Liu","Xiaolong Shen","Zhenglin Zhou","Ruijie Quan","Yi Yang"],"published":"2026-08-11T10:02:41Z","updated":"2026-08-11T10:02:41Z","abstract_url":"https://arxiv.org/abs/2608.10744v1","html_url":"https://arxiv.org/html/2608.10744v1","pdf_url":"https://arxiv.org/pdf/2608.10744v1.pdf","matched_keywords":["video","3d","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10724v1","title":"InterPruner: Interactive Structured Pruning via Taylor-Implicit Criterion and Language-Prior Modulator for Multimodal Object Detection","abstract":"Multimodal object detection proves effective in remote sensing, especially the RGB-Infrared paradigm. The parallel feature extractors provide rich multimodal information for robust detection, yet introduce substantial channel redundancy and computational overhead. Existing pruning methods can reduce channel redundancy, but they are designed for unimodal backbones, overlooking cross-modal interactions and dynamic scene-wise redundancy. In this paper, we propose InterPruner, the first interactive structured channel pruning framework for RGB-infrared object detectors. Specifically, we first derive a Taylor-Implicit Criterion(TIC) to quantify channel importance via high-order Taylor expansion and the implicit function theorem. Then, a Modality Interaction Redundancy Analyzer (MIRA) identifies redundant channels via mutual compensability assessment. Finally, a Scene-Prior Channel Anchor (SPCA) uses language priors as semantic anchors to measure channel-scene relevance for dynamic channel importance estimation. Cross-modality channel pruning for RGB-Infrared detection is yet unexplored. Extensive experiments on RGB-infrared object detection dataset demonstrate that InterPruner maintains high performance with negligible degradation. Specifically, it even achieves a 0.6% mAP increase on the FLIR dataset when pruning 50% of the channels. Code will be available on GitHub to facilitate future work.","authors":["Qi Ming","Zihan Yang","Shaoguang Huang","Si Sun","Hanqing Zhang","Nanqing Liu","Jiahui Lv","Juan Fang","Aleksandra Pizurica"],"published":"2026-08-11T09:42:23Z","updated":"2026-08-11T09:42:23Z","abstract_url":"https://arxiv.org/abs/2608.10724v1","html_url":"https://arxiv.org/html/2608.10724v1","pdf_url":"https://arxiv.org/pdf/2608.10724v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10720v1","title":"Ex-Omni-2D: Expressive Omni-Modal Dialogue Models with Native Visual Presence","abstract":"Omni-modal dialogue models can understand multimodal inputs and synthesize spoken replies, yet their responses remain visually disembodied. We introduce \\textbf{Ex-Omni-2D}, an omni-modal dialogue framework that generates a coordinated response comprising text, personalized speech, and reference-conditioned video. Given a multimodal query, reference image, and reference audio, the model predicts a structured \\textit{Visual Thought Plan} (VTP) describing scene, emotion, and motion, followed by response text and native multi-codebook speech units. These units form a shared acoustic-temporal interface: they are decoded into speech and aligned online with video frames. This interface enables the response and avatar pathways to be learned from heterogeneous speech, dialogue, and avatar-video data, avoiding the need for large-scale query--text--speech--video supervision. A full-sequence Video Generator serves as the primary Teacher. For efficient incremental generation, we further distill it into a few-step block-causal \\emph{Streaming Student} whose Prefix Streaming mechanism carries a clean latent across consecutive chunks to reduce cumulative late-chunk degradation. With four-step inference, the complete four-GPU pipeline achieves an end-to-end RTF of 1.293 at $400\\times720$/$720\\times400$, providing a practical quality--efficiency operating point.","authors":["Haoyu Zhang","Zhipeng Li","Xiaoying Tang","Tianshu Yu","Yiwen Guo"],"published":"2026-08-11T09:37:11Z","updated":"2026-08-11T09:37:11Z","abstract_url":"https://arxiv.org/abs/2608.10720v1","html_url":"https://arxiv.org/html/2608.10720v1","pdf_url":"https://arxiv.org/pdf/2608.10720v1.pdf","matched_keywords":["video","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10712v1","title":"Compact Feed-Forward 3D Gaussians via Saliency-Guided Primitive Merging","abstract":"3D scene reconstruction, modeling, and rendering are highly relevant for numerous tasks, and 3D Gaussian splatting has become a standard choice in this context. Its feed-forward variants provide fast reconstruction from sparse input views but often produce per-pixel primitives, leading to highly redundant and thus inefficient representations. We present a structure-aware merging pipeline that takes per-pixel primitives from any feed-forward method and consolidates them into a compact, content-adaptive Gaussian set while largely retaining visual quality at just $\\frac{1}{20}^\\text{th}$ of the Gaussians of a per-pixel method. We group spatially coherent Gaussians of similar appearance into variable-size clusters via adaptive superpixel segmentation guided by a saliency map, which allocates fine segments to textured regions and coarse segments to homogeneous areas. We compress each cluster into a compact latent representation through a learned encoder, then match and consolidate representations across views based on geometric overlap and feature similarity via a learned merger. A level-of-detail decoder then produces the final Gaussians at a controllable resolution, enabling a flexible quality-efficiency trade-off at inference. As a post-processing module, the pipeline is backbone-agnostic, leveraging the strengths of existing feed-forward methods. This leads to better and more robust quality than achieved by previous approaches that target a reduction in primitive count, while providing a highly compact representation, that can be rendered efficiently.","authors":["Tim-Felix Fassch","Jochen Kall","Cyrill Stachniss"],"published":"2026-08-11T09:32:08Z","updated":"2026-08-11T09:32:08Z","abstract_url":"https://arxiv.org/abs/2608.10712v1","html_url":"https://arxiv.org/html/2608.10712v1","pdf_url":"https://arxiv.org/pdf/2608.10712v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10708v1","title":"Self-Geometry: GT-Free and Plug-and-Play Test-Time Adaptation for Geometrically Consistent 3D Vision Foundation Models","abstract":"Recent Vision Foundation Models (VFMs) predict depth, camera pose, and pointmap in a single forward pass without per-scene optimization, achieving strong generalization. However, enforcing explicit multi-view geometric consistency, e.g., through bundle adjustment, is computationally costly and is thus not imposed during VFM pretraining, so such inconsistency can arise. To address this, implicit self-consistency derived from model outputs (e.g., pointmaps, features), though enforced at test-time in prior work, delivers inherently limited performance gain, especially on scenes where the pretrained VFM is highly inaccurate. In contrast to this implicit signal, we propose Self-Geometry, a plug-and-play test-time adaptation pipeline that directly imposes explicit multi-view geometric constraints using 2D pixel correspondences as pseudo ground-truth. Our proposed Self-Geometry consists of Geometric Disentanglement Optimization, which combines Multi-View Consistency and Epipolar Consistency losses with Gradient Disentanglement to prevent gradient conflict; Frame Angular-Neighbor, a view sampler based on SO(3) geodesic distances for lightly imposing these constraints; and Lightweight TTA, which adapts VFMs via LoRA. Our method achieves consistent improvements in both pose and geometry estimation across six VFMs (VGGT, $π^3$, DA3-Giant/Large/Base/Small) and four benchmarks (7Scenes, ETH3D, ScanNet++, HiRoom).","authors":["Seokhyun Youn","Dahyeon Kye","Sung-Ho Bae","Jihyong Oh"],"published":"2026-08-11T09:28:50Z","updated":"2026-08-11T09:28:50Z","abstract_url":"https://arxiv.org/abs/2608.10708v1","html_url":"https://arxiv.org/html/2608.10708v1","pdf_url":"https://arxiv.org/pdf/2608.10708v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10706v1","title":"MMArt A Multi-Perspective Multimodal Dataset for Visual Art Understanding","abstract":"Recent vision-language models demonstrate impressive general visual understanding, yet their art interpretation remains shallow: they describe surface content but struggle with formal analysis, grounded historical interpretation, or affective characterization. We argue this is not only a model but also a dataset limitation. Existing art datasets are single perspective resources, where no dataset provides narrative, formal, emotional, and historical perspectives simultaneously for the same artworks. We introduce MMArt, a large-scale dataset of 74,234 WikiArt paintings, each annotated with four independently annotated perspectives plus a harmonized unified caption, produced by specialized vision-language models or human annotation and validated through complementary quality evaluations. Two complementarity analyses establish that perspectives encode genuinely distinct information. A generative analysis shows that formal analysis descriptions best preserve compositional style, and historical descriptions carry strong affective signal in reconstructed images. A discriminative retrieval analysis reveals task-asymmetry: narrative descriptions drive retrieval (R@1 = 44.0%), while formal descriptions, strongest for reconstruction, are nearly nondiscriminative at retrieval scale (R@1 = 7.8%). Leave-one-out analysis further confirms that historical descriptions are the least replaceable perspective across both tasks. Together, the two analyses establish that no single perspective suffices for all tasks, directly motivating MMArt multi-perspective design. The dataset, code, and additional information are available at https://shuaiwang97.github.io/MMArt/.","authors":["Shuai Wang","Wangyuan Ding","Yixian Shen","Jia-Hong Huang","Stevan Rudinac","Monika Kackovic","Nachoem Wijnberg","Marcel Worring"],"published":"2026-08-11T09:28:20Z","updated":"2026-08-11T09:28:20Z","abstract_url":"https://arxiv.org/abs/2608.10706v1","html_url":"https://arxiv.org/html/2608.10706v1","pdf_url":"https://arxiv.org/pdf/2608.10706v1.pdf","matched_keywords":["retrieval","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10682v1","title":"Visual Geometry Foundation-Aware Gaussians for Single-Frame Surround-View Driving Reconstruction","abstract":"Single-frame surround-view reconstruction faces severe geometric instability and rendering artifacts due to minimal inter-camera overlap. While existing methods rely on complex decoders or auxiliary cues, they remain bottlenecked by the weak geometric capacity of upstream features. We argue that leveraging pretrained visual geometry priors strengthens upstream representations and alleviates the geometric ambiguity in sparse surround views. To this end, we propose VGGD, a visual geometry foundation-aware 3D Gaussian Splatting framework for feed-forward surround-view driving reconstruction, which shifts geometric modeling to the frontend and adapts foundation priors to the driving camera setting. First, VGGD leverages VGGT to provide transferable multi-view geometric prior tokens. Next, we introduce a Dual-Path Neck to decouple geometry-consistent and appearance-aware representations, improving appearance completion in weakly observed regions. We further apply Scale Warmup to stabilize early geometry learning and suppress scale drift under ego-pose changes. Finally, we use a hybrid pixel--volume Gaussian decoder to produce a renderable 3D Gaussian scene for novel-view synthesis. Experiments on the nuScenes single-frame benchmark show that VGGD achieves the best overall rendering quality among the compared methods and improves relative geometric consistency.","authors":["Junhong Lin","Jinlong Wang","Xianda Guo","Yanlun Peng","Wei Zheng","Guoqing Liu","Hanli Wang","Tiesong Zhao","Wei Gao"],"published":"2026-08-11T09:04:33Z","updated":"2026-08-11T09:04:33Z","abstract_url":"https://arxiv.org/abs/2608.10682v1","html_url":"https://arxiv.org/html/2608.10682v1","pdf_url":"https://arxiv.org/pdf/2608.10682v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10677v1","title":"Chartography: A Benchmark for Professional Chart Understanding","abstract":"Professionals across medicine, engineering, finance, manufacturing, and the sciences often make consequential decisions from charts. Existing chart benchmarks do not sufficiently measure this ability: they are dominated by bar, line, and pie formats, rely on shorter reasoning chains, and are nearing saturation, with frontier models already scoring 80-90%. We introduce Chartography, a benchmark of 100 tasks that pair charts drawn from professional practice, in domain-specific formats that standard chart benchmarks rarely include, with questions written by professionals who read these charts for a living and independently verified by three additional experts. In an evaluation of 30 frontier-model configurations (20 scored trials per task), the best configuration reaches only 45.0% mean pass@1; the remainder span 9.0-39.5%. Failures concentrate in visual perception: models can miss nuanced features, misread values along sparsely labeled axes, mishandle projected 3D geometry, and violate domain conventions encoded in the chart. We release all tasks, images, provenance metadata, and evaluation code.","authors":["Suhaas Garre","Chris Mutty","Sushant Mehta","Edwin Chen"],"published":"2026-08-11T08:57:25Z","updated":"2026-08-11T08:57:25Z","abstract_url":"https://arxiv.org/abs/2608.10677v1","html_url":"https://arxiv.org/html/2608.10677v1","pdf_url":"https://arxiv.org/pdf/2608.10677v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10665v1","title":"VERDICT: Training-Free Step-Wise Verification of Multimodal Reasoning via Disagreement-Aware Consensus","abstract":"Multimodal large language models often generate reasoning chains containing subtle errors that lead to incorrect answers. Current verification approaches have notable limitations. Existing approaches either require expensive labelled supervision with inconsistent cross-task performance or aggregate scores from multiple sources by simple aggregations, missing a key insight: when these scores disagree, that disagreement itself carries important information about whether a reasoning step is truly valid or not. We formalise this as a coupled scoring problem among disparate, frozen verifiers, interpretable as a coordination game with a unique closed-form equilibrium where agreement signals valid steps while disagreement reveals instability. Towards this end, we propose a training-free domain-agnostic step-wise verification approach we call VERDICT: VERification via Disagreement-Informed Coupled Thresholding. To our knowledge, VERDICT is the first training-free verifier that makes the structure of cross-modal disagreement explicit and actionable. It computes consensus scores through a closed-form solution, enabling both disagreement-aware filtering and stability-conscious ranking of reasoning steps. Evaluated across six benchmarks, \\method consistently improves over the base model by up to +5.95%, and performs competitively with domain-specific critics that demand extensive supervision, demonstrating that cross-modal agreement provides robust verification signals without task-specific adaptation and Training-Free Verification","authors":["Rohit Sinha","Kunal Tilaganji","Tanuja Ganu","Nagarajan Natarajan","Amit Sharma","Vineeth Balasubramanian"],"published":"2026-08-11T08:46:38Z","updated":"2026-08-11T08:46:38Z","abstract_url":"https://arxiv.org/abs/2608.10665v1","html_url":"https://arxiv.org/html/2608.10665v1","pdf_url":"https://arxiv.org/pdf/2608.10665v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10657v1","title":"Retrieval-Augmented Vision Foundation Models for Robust Leukemia Cell Classification across Multiple Microscopy Datasets","abstract":"Leukemia cell image classification is challenged by real-world domain shifts from acquisition, staining, illumination, and site protocols, causing single-dataset models to generalize poorly in real clinical scenarios. This work presents a robust framework for leukemia classification across multiple heterogeneous datasets using a two-stage pipeline with a pretrained vision foundation model. Stage 1 performs binary classification (leukemia vs. non-leukemia) and is trained using 122,167 single-cell images. Stage 2 is conditionally applied to Stage 1 positives to perform subtype classification into Acute Lymphoblastic Leukemia (ALL) and Acute Myeloid Leukemia (AML), trained using 69,400 single-cell images. Labels are harmonized across five heterogeneous datasets to enable cross-dataset training, and performance is evaluated on a held-out dataset protocol to assess domain-shift generalization. Within this pipeline, three encoders are benchmarked (DinoBloom, pretrained on single-cell images; BiomedCLIP, pretrained on biomedical data; and CLIP as a general-purpose model) under linear probing, Low-Rank Adaptation (LoRA), and a Retrieval-Augmented Classification (RAC) module that retrieves the top-k most similar cell images to provide cytomorphological grounding. The objective is to quantify how much domain-specific pretraining contributes to performance under domain shift, and whether cost-effective adaptation and retrieval can be a viable alternative to expensive domain-specialized pretraining. The held-out protocol additionally serves as a diagnostic tool, revealing when classification performance is attributable to dataset-specific artifacts rather than to cytomorphological features.","authors":["Carlos Zamora","Hiram Zuniga","Ulises Orozco-Rosas","Kenia Picos"],"published":"2026-08-11T08:39:16Z","updated":"2026-08-11T08:39:16Z","abstract_url":"https://arxiv.org/abs/2608.10657v1","html_url":"https://arxiv.org/html/2608.10657v1","pdf_url":"https://arxiv.org/pdf/2608.10657v1.pdf","matched_keywords":["retrieval"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10636v1","title":"DistilVDR: A Compact End-to-End Visual Document Retriever via Dual-Student Distillation","abstract":"Visual document retrieval (VDR) is dominated by multi-billion-parameter models that are slow to index at full corpus scale and expensive to serve. Prior compression routes either train a smaller multi-vector encoder from scratch or distil only the query side; neither yields a compact single-vector retriever end-to-end. We present DistilVDR, a 524M end-to-end VDR system distilled bilaterally from a single 8B vision-language teacher under a pointwise cosine alignment loss. All supervision comes from the frozen teacher's embedding space, which was itself trained with relevance supervision, so the student objective needs no relevance labels, negative sampling, or contrastive term. We match VDR's text-query and image-document input asymmetry with an asymmetric encoder-only student that concentrates visual capacity on the document side and keeps the query side at 70M parameters. We release two variants that share the same encoders and training and differ only in the document encoder's visual-tile budget: DistilVDR-HiRes attains 61.74 average NDCG@5 on ViDoRe v1+v2+v3 (86.9% of the 8B teacher) and leads every reproduced sub-1B baseline on the high-resolution-sensitive v3 benchmark, while DistilVDR-Fast attains 59.98 at a 3 times smaller visual-token budget. Both variants store one million documents in a 15.6 times smaller index than the strongest sub-1B multi-vector baseline and index the corpus an order of magnitude faster. The code is available at https://github.com/Ryenhails/NanoVDR.","authors":["Zhuchenyang Liu","Ziyi Wang","Yao Zhang","Yu Xiao"],"published":"2026-08-11T08:23:39Z","updated":"2026-08-11T08:23:39Z","abstract_url":"https://arxiv.org/abs/2608.10636v1","html_url":"https://arxiv.org/html/2608.10636v1","pdf_url":"https://arxiv.org/pdf/2608.10636v1.pdf","matched_keywords":["retrieval"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10635v1","title":"MedUP: Awakening Unified Understanding and Perception in Medical Vision-Language Models","abstract":"Medical Vision-Language Models (Med-VLMs) excel at verbalizing visual content, yet precise visual perception, segmentation, and grounding remain challenging. Existing approaches either verbalize regions as coordinate strings or rely on external modules that decouple perception from understanding, creating representation gaps for region-language alignment. We present MedUP, a Med-VLM that natively unifies perception and understanding within a shared token space. At its core lies UniMedTok, a region tokenizer that encodes masks as discrete tokens in the LLM vocabulary, enabling the model to seamlessly interleave mask tokens with text. We curate UniMed-Train, a 1.84M-instance corpus spanning text-guided segmentation, region-grounded understanding, medical VQA and CoT-based segmentation, and introduce UniMed-Bench for unified evaluation. Extensive experiments show that MedUP outperforms native, agentic, and dual-decoder Med-VLMs across all tasks while remaining competitive with specialist segmentors, demonstrating the strong potential of unified understanding and perception modeling.","authors":["Yuan Wang","Hualiang Wang","Yixin Chen","Songtao Jiang","Shujian Gao","Jiaming Lin","Siming Fu","Jian Wu","Zuozhu Liu"],"published":"2026-08-11T08:22:13Z","updated":"2026-08-11T08:22:13Z","abstract_url":"https://arxiv.org/abs/2608.10635v1","html_url":"https://arxiv.org/html/2608.10635v1","pdf_url":"https://arxiv.org/pdf/2608.10635v1.pdf","matched_keywords":["agent","representation","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10628v1","title":"InSight-doc: Agentic Visual Perception for Long-Document Understanding","abstract":"Long-document understanding often requires reasoning over many visually rich pages, making inference costly and prone to context rot. In this work, we propose InSight-doc, an agentic visual perception framework that treats visual resolution as an adaptive reasoning-time resource. InSight-doc starts from low resolution and selectively zooms into high-resolution regions for finer evidence, without relying on any external retriever. To train such an agent, we construct an active-perception corpus of 17.9K high-quality SFT examples with region-level zoom-in trajectories, accompanied by 19.2K hard RL examples. Through SFT+RL, InSight-doc-8B improves the baseline by 4.3--16.4 accuracy points over document VQA benchmarks. On long documents, it reduces hallucination by more than 40% and inference latency by 41%--68% while maintaining an accuracy lead. Our code, datasets, and model are released at https://github.com/m-Just/InSight-doc .","authors":["Kaican Li","Weiyan Xie","Lewei Yao","Jiannan Wu","Lanqing Hong","Yongxiang Huang","Nevin L. Zhang"],"published":"2026-08-11T08:15:16Z","updated":"2026-08-11T08:15:16Z","abstract_url":"https://arxiv.org/abs/2608.10628v1","html_url":"https://arxiv.org/html/2608.10628v1","pdf_url":"https://arxiv.org/pdf/2608.10628v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10602v1","title":"Gaussian Sculpting: End-to-End Controllable Surface Reconstruction via Field Optimization","abstract":"3D Gaussian Splatting (3DGS) has recently enabled real-time novel view synthesis with impressive quality. However, it struggles to recover accurate surfaces under limited viewpoints and due to the inherent irregularity of Gaussian primitives. The resulting geometric errors are notoriously difficult to correct manually. To address these issues, we propose Gaussian Sculpting, a fully differentiable end-to-end framework for high-quality surface reconstruction. Our key insight is to anchor Gaussians onto an evolving differentiable surface, allowing them to guide signed distance field (SDF) optimization instead of extracting the surface only during post-processing. To enable stable gradient isolation during joint optimization, we design a bi-level training strategy in which the outer loop optimizes the geometry represented by the SDF, while the inner loop updates the Gaussians with the geometry fixed. We further impose constraints on Gaussian parameters to ensure consistency with the underlying surface, thereby improving both geometric and appearance fidelity during optimization. In addition, we introduce a multi-resolution subdivision scheme based on octree-like partitioning to preserve fine details while reducing memory consumption. Experiments on object-level scenes demonstrate that our method effectively removes redundant surfaces, recovers missing structures caused by limited viewpoints, and achieves strong reconstruction quality even at relatively low resolutions.","authors":["Ke Jiaxin","Juncheng Liu","Yi Wang","Zhouhui Lian","Bin Liu","Shengfa Wang","Xiangjia He"],"published":"2026-08-11T07:42:24Z","updated":"2026-08-11T07:42:24Z","abstract_url":"https://arxiv.org/abs/2608.10602v1","html_url":"https://arxiv.org/html/2608.10602v1","pdf_url":"https://arxiv.org/pdf/2608.10602v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10600v1","title":"BooST: Bridging Semantics and Motions for Efficient Skill Transfer","abstract":"Skill abstraction---the process of learning reusable and temporally extended behaviors---has emerged as a key paradigm for improving sample efficiency and generalization in robot learning. For efficient skill transfer to real robots, learned skills must generalize across tasks and domains, remain robust to visual and dynamic perturbations, and be efficient enough for practical deployment. However, existing methods typically satisfy only a subset of these properties, as they capture either high-level semantic intent (what) or low-level motion dynamics (how). This incomplete skill transfer yields weak priors for policy learning, thereby demanding substantial in-domain data for downstream adaptation. To address these challenges, we introduce BooST, a two-stage framework that explicitly bridges semantics and motions to satisfy all three desiderata. BooST first leverages a cross-modal VQ-VAE to capture both semantic intent and motion dynamics, yielding a unified skill representation. It then distills this representation into a lightweight policy for efficient downstream adaptation to new tasks. Extensive experiments across simulation and real-robot settings demonstrate that BooST achieves superior few-shot adaptation, cross-domain skill transfer, and robustness to dynamic visual distractors, while maintaining a lightweight yet expressive design suitable for real-world deployment.","authors":["Jusuk Lee","Daesol Cho","Jonghun Shin","Seungyeon Yoo","Jonghae Park","Taekbeom Lee","H. Jin Kim"],"published":"2026-08-11T07:35:12Z","updated":"2026-08-11T07:35:12Z","abstract_url":"https://arxiv.org/abs/2608.10600v1","html_url":"https://arxiv.org/html/2608.10600v1","pdf_url":"https://arxiv.org/pdf/2608.10600v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10566v1","title":"Iterative Erasure Count Is Not an Affine-Invariant Concept Dimension","abstract":"How many directions does a neural representation use to encode a concept? A common answer repeatedly erases probe directions and reports the stopping count or cumulative removed rank. We show that both quantities can change under an information-preserving invertible reparameterization, so neither is intrinsically a concept dimension. We distinguish model-defined population quantities (generating dimension, sufficient linear dimension, and minimum guarding rank) from procedure-defined quantities such as stopping count and cumulative edit rank. In a population Gaussian construction, an invertible shear preserves the prediction problem and all three quantities, yet changes the cumulative Euclidean erasure count from one to two. The separation holds for Moore--Penrose ordinary least squares and every finite nonnegative ridge weight. For a two-output full-QR procedure matching our motivating video analysis, cumulative edit rank similarly changes from two to the ambient dimension four. Conversely, the complete cumulative metric-QR trajectory is affine-equivariant when its positive-definite metric, probe, regularizer, and tie-breaking are transported consistently; exact covariance is one corollary, not a canonical semantic metric. In a known-rank finite-sample Adam/QR calibration, identity mixing stops after one accepted update in all 20 large-sample runs, whereas each tested shear $a\\in\\{.5,.75,1,1.25,2\\}$ accepts at least two updates in all 20 runs. Controlled reparameterizations of frozen V-JEPA2 features preserve rank-zero predictions yet alter later Euclidean trajectories under practical optimization. These visual contact experiments are stress tests, not estimates of contact dimension. Iterative erasure therefore returns a procedure-relative estimand jointly determined by representation geometry and the full measurement procedure, not a semantic dimension by itself.","authors":["Tingan Jin","Shuhang Dong","Haosong Li","Chung-Hsien Chou"],"published":"2026-08-11T06:53:50Z","updated":"2026-08-11T06:53:50Z","abstract_url":"https://arxiv.org/abs/2608.10566v1","html_url":"https://arxiv.org/html/2608.10566v1","pdf_url":"https://arxiv.org/pdf/2608.10566v1.pdf","matched_keywords":["video","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10524v1","title":"Rethinking Text-Based Image Retrieval in Specific Domain","abstract":"Driven by the rapid advancement of vision-language representation learning, Text-based Image Retrieval (TBIR) has made notable progress. However, existing benchmarks are predominantly constructed on an exclusive single-match assumption between query and images. While effective in general scenarios, this assumption fails to reflect practical system performance in specific domains (e.g., surveillance), where a single query often corresponds to multiple relevant candidate images. To address this limitation, we design a Domain-Specific Multi-Match Text-based Image Retrieval (DSMM-TBIR) data engine. Leveraging this engine, we construct Security Multi-Match TBIR (SecMM-TBIR), a benchmark comprising 50k surveillance images with 200 comprehensive queries. Furthermore, we observe that vanilla contrastive learning in specific domains suffers from severe false negatives, forcing the model to push apart semantically similar pairs and thus degrading retrieval performance. We propose the Semantic-Aware Fine-Tuning (SAFT) framework to address semantic compression in specific domains, which incorporates Semantic-Aware Soft-Label Supervision (SASS) and Intra-modal Structural Distillation (ISD) to establish a promising paradigm for domain-specific TBIR tasks. Experiments across diverse CLIP-like models demonstrate that SAFT yields an average mAP@20 gain of 7.8 points on SecMM-TBIR over standard image-text contrastive (ITC) fine-tuning, while also improving general-domain performance. The entire benchmark will be released to facilitate further research.","authors":["Jingyang Tan","Sheng Yang","Yuanpeng Chen","Jian Wang","Nianjin Ye","Chen Xing","Lanpeng Jia"],"published":"2026-08-11T06:00:27Z","updated":"2026-08-11T06:00:27Z","abstract_url":"https://arxiv.org/abs/2608.10524v1","html_url":"https://arxiv.org/html/2608.10524v1","pdf_url":"https://arxiv.org/pdf/2608.10524v1.pdf","matched_keywords":["retrieval","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10522v1","title":"Unlocking the Power of Medical Tabular Data via Semantic-Aware Multimodal Pre-training","abstract":"While vision-language models dominate medical representation learning, unstructured text lacks the dense, quantitative diagnostic phenotypes inherent in structured clinical tables. However, existing multimodal pre-training methods underutilize this potential due to semantic-agnostic designs that treat tabular inputs as flat vectors and employ unstable continuous regression objectives. To overcome this, we propose a novel semantic-aware framework explicitly modeling the intrinsic two-dimensional structure of tabular data. First, addressing the inter-feature hierarchy of varying diagnostic importance, we introduce Importance-Aware Adaptive Masking to construct a label-free curriculum prioritizing salient features. Second, addressing the intra-feature continuity-discreteness duality, we propose a Soft-Label Discretized Module that replaces unstable numerical regression with stable distribution matching, thereby mathematically preserving ordinal relationships. Extensive experiments across large-scale dermatology (SLICE-3D, HOP) and ophthalmology (EyePACS) datasets establish a new state-of-the-art (SOTA), demonstrating exceptional robustness and cross-domain generalizability.","authors":["Yingsheng Liu","Haiming Li","Jingmin Zhu","Jiajun Sun","Victoria Mar","Monika Janda","H. Peter Soyer","Zongyuan Ge","Zhen Yu"],"published":"2026-08-11T05:57:09Z","updated":"2026-08-11T05:57:09Z","abstract_url":"https://arxiv.org/abs/2608.10522v1","html_url":"https://arxiv.org/html/2608.10522v1","pdf_url":"https://arxiv.org/pdf/2608.10522v1.pdf","matched_keywords":["3d","representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10519v1","title":"SparSTAR: Sparse Attention for SpaceTime AutoRegressive Video Synthesis","abstract":"InfinityStar extends visual autoregressive generation to video through a sequence of image and clip pyramids. Its changing scale and cross-clip context, however, leave late-scale attention costly and make sparse patterns reused from diffusion or image VAR models unreliable. We introduce SparSTAR, a training-free block-sparse attention method tailored to this setting. At each expensive scale and attention head, SparSTAR scores contiguous key blocks from the current query and key activations, retains required conditioning context, and executes the selected blocks through a forward-only sparse path. We analyze cross-scale consistency within a clip, pattern persistence across clip boundaries, and quality degradation as reuse spans increasingly distant scales. Across these analyses, important key blocks shift, showing that recomputing block selection at each target scale is more reliable than reusing a transferred mask. On 720p text-to-video and image-to-video generation, SparSTAR preserves every token and refinement scale while providing about a 1.6x end-to-end speedup and maintaining VBench and paired-output reconstruction fidelity close to dense InfinityStar.","authors":["Jongbeom Lee","Hyunwoo Yu","Jincheol Yang","Jaemin Choi","Suk-Ju Kang"],"published":"2026-08-11T05:46:18Z","updated":"2026-08-11T05:46:18Z","abstract_url":"https://arxiv.org/abs/2608.10519v1","html_url":"https://arxiv.org/html/2608.10519v1","pdf_url":"https://arxiv.org/pdf/2608.10519v1.pdf","matched_keywords":["video","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10513v1","title":"SafeCap: Improving LVLM Safety with Image Captioning Reinforcement Learning","abstract":"Large vision-language models (LVLMs) remain vulnerable to jailbreak attacks that exploit visual inputs to bypass safety alignment inherited from their language backbones. We propose SafeCap, a reinforcement-learning framework that aligns LVLMs through learned self-captioning. SafeCap trains a policy model to first generate a safety-relevant image caption and then produce a final answer; the caption is further optimized by whether it enables a frozen LLM to reach a safety-aligned decision. This caption-mediated objective encourages the policy to expose visual cues relevant to safe response generation rather than relying solely on direct refusal supervision. Across five multimodal safety benchmarks and six vision-utility benchmarks, SafeCap substantially improves aggregate safety performance under its intended DirectCap protocol, with gains of 3.7-19.0 points in safety average across four model settings while maintaining comparable or improved vision utility. Under controlled comparisons on matched backbones and data, SafeCap outperforms safety SFT, DPO, and SafeGRPO, demonstrating the effectiveness of caption-mediated reinforcement learning for multimodal safety alignment.","authors":["Caoyuan Ma","Wenpu Liu","Weichu Xie","Tian Gu","Shilei Zhao","Lingxi Min","Shuai Dong","Yuqi Xu","Ji Zhao","Ziyue Wang","Wenzheng Chang","Taiqiang Wu","Yongfu Zhu","Wenqi Shao","Yinqiang Zheng"],"published":"2026-08-11T05:37:59Z","updated":"2026-08-11T05:37:59Z","abstract_url":"https://arxiv.org/abs/2608.10513v1","html_url":"https://arxiv.org/html/2608.10513v1","pdf_url":"https://arxiv.org/pdf/2608.10513v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10500v1","title":"DSAR: Dual-Stream Autoregressive Modeling of Temporal Cloth Dynamics for Photorealistic Animatable Avatars","abstract":"Creating photorealistic and temporally coherent animatable human avatars from RGB videos remains challenging. Current methods struggle to capture realistic cloth dynamics, producing over-smoothed appearance or severe artifacts on out-of-distribution poses. This limitation stems from a fundamental oversight: existing approaches neglect the temporal causality inherent in cloth physics, where current states emerge from previous states through temporal evolution rather than instantaneous skeletal configurations alone. Without explicit modeling of this causal structure, networks learn pose-appearance correlations instead of motion evolution, leading to poor generalization. We introduce a dual-stream autoregressive framework that explicitly models both observable geometric information and implicit internal state. The geometric stream propagates surface displacement from the previous frame, while the state stream fuses current features with historical states retrieved from a memory bank. Motion-adaptive aggregation handles spatially-varying dynamics, and adaptive regularization balances smoothness with flexibility. Experiments on challenging datasets demonstrate significant improvements in rendering quality, temporal consistency, and generalization to motion patterns beyond training distributions, validating that dual-stream temporal modeling enables realistic cloth dynamics.","authors":["Haozhong Xiong","Yao Yu","Yu Zhou","Sidan Du"],"published":"2026-08-11T05:19:21Z","updated":"2026-08-11T05:19:21Z","abstract_url":"https://arxiv.org/abs/2608.10500v1","html_url":"https://arxiv.org/html/2608.10500v1","pdf_url":"https://arxiv.org/pdf/2608.10500v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10497v1","title":"SapiensID 2.0: Aligning Human Recognition Foundation Models with Human Perception","abstract":"While foundation models have significantly advanced human recognition across diverse modalities, they predominantly rely on static, geometric feature extraction. This approach fundamentally diverges from human perception. Consequently, current models often suffer from \"semantic blindness,\" overfitting to transient noise while failing to leverage invariant soft biometrics, and struggle to capture temporal motion signatures. To bridge this gap, we propose SapiensID 2.0, a human recognition framework enriched with both semantic and temporal awareness. To overcome the lack of soft-biometric annotations, we transfer zero-shot semantic knowledge from Multimodal Large Language Models (MLLMs) into a discriminative embedding space. We resolve the dimensional mismatch between these spaces using Invariant Trait Alignment (ITA) to distill core persistent traits, and Transient Noise Disentanglement (TND) to decouple artifacts like clothing. Furthermore, we design a Kinematic Semantic Attention Head (K-SAH) that extends spatial attention across temporal windows. By tracking semantic patches over time, K-SAH captures rich kinematic signatures without requiring large-scale video datasets. Extensive experiments demonstrate that SapiensID 2.0 achieves state-of-the-art performance across image- and video-based person re-identification and gait recognition, while maintaining robust face recognition capabilities.","authors":["Yiyang Su","Jie Zhu","Feng Liu","Anil K. Jain","Xiaoming Liu"],"published":"2026-08-11T05:13:05Z","updated":"2026-08-11T05:13:05Z","abstract_url":"https://arxiv.org/abs/2608.10497v1","html_url":"https://arxiv.org/html/2608.10497v1","pdf_url":"https://arxiv.org/pdf/2608.10497v1.pdf","matched_keywords":["video","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"},{"id":"2608.10489v1","title":"When Vision Becomes Text: Visual Token Pruning via Cross-Modal Residual Guidance in VLMs","abstract":"Abundant visual information strengthens vision-language model (VLM) perception, yet massive visual tokens raise inference costs. Existing visual token pruning methods rely on similarity-based guidance, which exploits pairwise text-vision and vision-vision token correlations for compression. However, such methods only capture local layer-level signals and overlook the whole inference process in VLM. In this paper, we revisit VLM inference and present a new efficient guidance scheme that complements similarity-based guidance. In particular, we identify a key observation: as LLM layers deepen, text tokens continuously aggregate visual information via self-attention and progressively absorb partial visual content into textual representations. To quantify this phenomenon, we propose Cross Modal Absorption (CMA) from a geometric representation perspective to measure how much visual information is absorbed by text, revealing that more visual tokens in deeper layers can be approximately explained by the text subspace. We accordingly propose Cross Modal Residual (CMR). It projects visual tokens onto the text subspace via Tikhonov regularized least squares and exploits reconstruction residuals to quantify visual information that cannot be explained by text. Finally, based on CMR, we present SIEVE, a training-free visual token compression method that combines CMR, text-attention relevance, and residual-space diversity to retain task-relevant and complementary tokens. Experiments on diverse VLM architectures verify the effectiveness of SIEVE. For instance, on LLaVA-NeXT-7B, SIEVE keeps only $11.1\\%$ of visual tokens while preserving $97.5\\%$ of the original average performance, achieving $3.62\\times$ prefill speedup, $2.49\\times$ end-to-end speedup, and a $6.02\\times$ KV-cache reduction.","authors":["Congyang Ou","Ruike Song","Yang Zhou","Libo Sun","Haokui Zhang","Zhenbo Luo"],"published":"2026-08-11T05:04:33Z","updated":"2026-08-11T05:04:33Z","abstract_url":"https://arxiv.org/abs/2608.10489v1","html_url":"https://arxiv.org/html/2608.10489v1","pdf_url":"https://arxiv.org/pdf/2608.10489v1.pdf","matched_keywords":["representation","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-08-12T03:20:05+00:00","last_seen_at":"2026-08-12T03:20:05+00:00"}],"tracked_paper_count":66,"storage_mode":"latest_overwrite"}};
